-- Hyperspace Lua has neither require nor package: a mod's scripts only share
-- globals, and load order follows hyperspace.xml.
_G.apGameData = gamedata

]=], "@gamedata.lua", "t", _ENV)
  if chunk == nil then
    print("SYNTAX ERROR in gamedata.lua: " .. tostring(err))
    _G.__syntaxErrors = (_G.__syntaxErrors or 0) + 1
  else
    local ok, runErr = pcall(chunk)
    if not ok then
      print("LOAD ERROR in gamedata.lua: " .. tostring(runErr))
      _G.__loadErrors = (_G.__loadErrors or 0) + 1
    end
  end
end

