do
  local chunk, err = load([=[
local TAG = "[AP-gift] "

local function giftLog(message)
    log(TAG .. message)
end

local GIFT_BLUEPRINTS = {}
for numero = 1, 12 do
    GIFT_BLUEPRINTS[numero] = "AP_GIFT_" .. numero
end

local function giftSlot(gift)
    local slot = gift and tostring(gift.location or ""):match("^shop:(%d+)$")
    return slot and tonumber(slot) or nil
end

-- A package's sector and ship come from its slot number, counted the same way as in the apworld.
local function giftSector(gift)
    local sectors = (_G.apShopConfig or {}).sectors
    local slot = giftSlot(gift)
    if sectors == nil or slot == nil then
        return nil
    end
    return (slot - 1) % sectors + 1
end

local function giftOwner(gift)
    local config = _G.apShopConfig or {}
    local slot = giftSlot(gift)
    if config.owners == nil or slot == nil then
        return nil
    end
    return config.owners[math.floor((slot - 1) / (config.sectors or 1)) % #config.owners + 1]
end

local function flying()
    local ok, name = pcall(function() return Hyperspace.ships.player.myBlueprint.blueprintName end)
    if not ok or name == nil then
        return nil
    end
    name = tostring(name)
    return (_G.apShopConfig or {}).per == "per_class" and name:gsub("_[23]$", "") or name
end

local function ownerAboard(gift)
    local owner = giftOwner(gift)
    return owner == nil or owner == flying()
end

local function currentSector()
    local ok, level = pcall(function() return Hyperspace.App.world.starMap.worldLevel end)
    return ok and tonumber(level) and math.floor(level) + 1 or nil
end

local function soldHere(gift)
    local sector = giftSector(gift)
    return (sector == nil or sector == currentSector()) and ownerAboard(gift)
end

local function sectorReached(gift)
    local sector = giftSector(gift)
    return (sector == nil or sector <= (currentSector() or 1)) and ownerAboard(gift)
end

local function shipClassOf(base)
    local ok, class = pcall(function()
        local bp = Hyperspace.Global.GetInstance():GetBlueprints():GetShipBlueprint(base, -1)
        return bp ~= nil and bp.shipClass:GetText() or nil
    end)
    if ok and type(class) == "string" and class ~= "" then
        return class
    end
    return _G.apShipLabel and apShipLabel(base) or base
end

-- The ship (class or layout) and the sector a shop slot is sold on, each nil when any will do.
function apShopSlotWhere(key)
    local gift = { location = tostring(key) }
    if giftSlot(gift) == nil then
        return nil, nil
    end
    return giftOwner(gift), giftSector(gift)
end

-- Where a shop slot is sold in this seed ("Kestrel Cruiser B, sector 6"), as hints say it: nil when anywhere.
function apShopPlace(key)
    local gift = { location = tostring(key) }
    if giftSlot(gift) == nil then
        return nil
    end
    local parts = {}
    local owner = giftOwner(gift)
    if owner ~= nil then
        local label = shipClassOf((tostring(owner):gsub("_[23]$", "")))
        if (_G.apShopConfig or {}).per == "per_layout" then
            local variant = tostring(owner):match("_([23])$")
            label = label .. " " .. (variant == "2" and "B" or variant == "3" and "C" or "A")
        end
        parts[#parts + 1] = label
    end
    local sector = giftSector(gift)
    if sector ~= nil then
        parts[#parts + 1] = apT("shop.place.sector", { n = sector })
    end
    return #parts > 0 and table.concat(parts, ", ") or nil
end

function apShopPages()
    local slots = tonumber(_G.apShopSlotCount) or 0
    local sectors = (_G.apShopConfig or {}).sectors
    local owners = #((_G.apShopConfig or {}).owners or {})
    if sectors ~= nil or owners > 0 then
        return math.max(1, math.min(4, math.ceil(slots / (sectors or 1) / math.max(1, owners) / 3)))
    end
    if slots > 100 then return 4 end
    if slots > 60 then return 3 end
    if slots > 30 then return 2 end
    return 1
end

local function visibleGifts()
    return 3 * apShopPages()
end

local function announceSize()
    pcall(function()
        Hyperspace.playerVariables.ap_shop_pages = apShopPages()
    end)
end

local DEAL_BLUEPRINTS = { "AP_DEAL_1", "AP_DEAL_2", "AP_DEAL_3", "AP_DEAL_4", "AP_DEAL_5", "AP_DEAL_6" }

local DEAL_REWARD = { 35, 55, 80, 60, 90, 130 }
-- Their price in the store (blueprints.xml.append), put back when a deal opens again.
local DEAL_COST = { 5, 10, 15, 5, 10, 15 }

-- shop_deal_scrap: the deals' scrap, in percent (100 by default). At 0 the deals are off: they show as closed.
local function dealPercent()
    local value = _G.apSeedOption and apSeedOption("shop_deal_scrap")
    return math.max(0, math.min(200, math.floor(tonumber(value) or 100)))
end

local function dealReward(index)
    return math.floor((DEAL_REWARD[index] or 30) * dealPercent() / 100)
end

-- The blood pacts, on the shop's second page: more scrap, and a chance in a hundred to lose a crew member for
-- good, Clone Bay or not.
local DEAL_BLOOD = { [4] = 5, [5] = 10, [6] = 20 }

local DEAL_SELF_CHANCE = 34

_G.apShopGifts = {}

local sold = {}

local function alreadyGone(key)
    if key == nil then
        return true
    end
    if sold[key] then
        return true
    end
    return _G.apCheckAlreadySent ~= nil and _G.apCheckAlreadySent(key) == true
end

local assignment = {}
-- shop_hints: the packages already hinted, and whether the player is at an Archipelago beacon now.
local hintedGifts = {}
local atApShop = false

local dealsSigned = {}

local function giftDesc(name)
    local ok, blueprint = pcall(function()
        return Hyperspace.Blueprints:GetWeaponBlueprint(name)
    end)
    if ok and blueprint ~= nil and tostring(blueprint.name) == name then
        return blueprint.desc
    end
    return nil
end

local function dealDesc(name)
    local ok, blueprint = pcall(function()
        return Hyperspace.Blueprints:GetAugmentBlueprint(name)
    end)
    if ok and blueprint ~= nil and tostring(blueprint.name) == name then
        return blueprint.desc
    end
    return nil
end

local KIND_KEY = {
    progression = "shop.kind.progression",
    useful = "shop.kind.useful",
    filler = "shop.kind.filler",
    trap = "shop.kind.trap",
}

local KIND_ART = {
    progression = "ap_gift_progression",
    useful = "ap_gift_useful",
    filler = "ap_gift_filler",
    trap = "ap_gift_trap",
}

local function setGiftArt(blueprintName, kind)
    pcall(function()
        local blueprint = Hyperspace.Blueprints:GetWeaponBlueprint(blueprintName)
        if blueprint ~= nil and tostring(blueprint.name) == blueprintName then
            blueprint.weaponArt = KIND_ART[kind] or "ap_gift"
        end
    end)
end

local BASE_PRICE = { progression = 70, useful = 30, filler = 10, trap = 10 }

local function offerFor(gift)
    local offers = (_G.apShopConfig or {}).offers
    local offer = type(offers) == "table" and gift ~= nil and gift.location ~= nil
        and offers[gift.location] or nil
    return type(offer) == "table" and offer or {}
end

local function giftPrice(gift)
    if gift == nil then
        return 0
    end
    local fixed = tonumber(gift.cost) or tonumber(offerFor(gift).price)
    if fixed ~= nil then
        return math.max(1, math.floor(fixed))
    end
    return BASE_PRICE[gift.kind] or BASE_PRICE.useful
end


local EMPTY_TEXTS = {
    noseed = { "shop.slot.noseed.title", "shop.slot.noseed.short", "shop.slot.noseed.body" },
    waiting = { "shop.slot.waiting.title", "shop.slot.waiting.short", "shop.slot.waiting.body" },
    sector = { "shop.slot.sector.title", "shop.slot.sector.short", "shop.slot.sector.body" },
    ship = { "shop.slot.ship.title", "shop.slot.ship.short", "shop.slot.ship.body" },
    later = { "shop.slot.later.title", "shop.slot.later.short", "shop.slot.later.body" },
    empty = { "shop.slot.empty.title", "shop.slot.empty.short", "shop.slot.empty.body" },
}

-- Why a shop slot is empty, from what the player can act on: wait, go to a sector, fly another ship, or nothing.
local function emptyReason()
    local gifts = _G.apShopGifts or {}
    local linked = _G.apContractState ~= nil and _G.apContractState.connected == true
    if #gifts == 0 and not linked then
        return "noseed", {}
    end
    if _G.apShopWaiting and apShopWaiting() then
        return "waiting", {}
    end
    local here = currentSector() or 1
    local nextSector, otherShips, earlier = nil, {}, false
    for _, gift in ipairs(gifts) do
        if not alreadyGone(gift.location or gift.item) then
            local sector = giftSector(gift)
            if not ownerAboard(gift) then
                local owner = giftOwner(gift)
                if owner and not otherShips[owner] then
                    otherShips[owner] = true
                    otherShips[#otherShips + 1] = owner
                end
            elseif sector ~= nil and sector > here then
                nextSector = math.min(nextSector or sector, sector)
            elseif sector ~= nil and sector < here then
                earlier = true
            end
        end
    end
    if nextSector then
        return "sector", { n = nextSector }
    end
    if #otherShips > 0 then
        local names = {}
        for index = 1, math.min(2, #otherShips) do
            names[#names + 1] = shipClassOf(tostring(otherShips[index]):gsub("_[23]$", ""))
        end
        return "ship", { ship = table.concat(names, ", ") }
    end
    if earlier then
        return "later", {}
    end
    return "empty", {}
end

function apShopEmptyReason()
    return emptyReason()
end

local function writeGift(blueprintName, gift)
    local desc = giftDesc(blueprintName)
    if desc == nil then
        giftLog("gift blueprint missing: " .. tostring(blueprintName)
            .. " (is blueprints.xml.append not loaded?)")
        return false
    end

    if gift == nil then
        setGiftArt(blueprintName, nil)
        local reason, params = emptyReason()
        local keys = EMPTY_TEXTS[reason]
        desc.title.data = apT(keys[1], params)
        desc.shortTitle.data = apT(keys[2], params)
        desc.description.data = apT(keys[3], params)
        desc.title.isLiteral = true
        desc.shortTitle.isLiteral = true
        desc.description.isLiteral = true
        desc.tooltip.data = desc.description.data
        desc.tooltip.isLiteral = true
        desc.cost = 0
        return true
    end

    setGiftArt(blueprintName, gift.kind)

    local who = tostring(gift.slot or "?")
    local me = _G.apOwnSlotName and _G.apOwnSlotName() or nil
    local forMe = gift.mine == true or (me ~= nil and who == tostring(me))

    desc.title.data = forMe and apT("shop.slot.title.self")
        or apT("shop.slot.title", { slot = who })
    desc.title.isLiteral = true

    if forMe then
        desc.shortTitle.data = apT("shop.slot.self.short")
    else
        desc.shortTitle.data = _G.apTruncate and _G.apTruncate(who, 12) or who
    end
    desc.shortTitle.isLiteral = true

    local details = { tostring(gift.item or apT("shop.slot.unknown_item")) }
    if gift.game ~= nil and tostring(gift.game) ~= "" then
        details[#details + 1] = tostring(gift.game)
    end
    local sphere = tonumber(gift.sphere) or tonumber(offerFor(gift).sphere)
    if sphere ~= nil then
        details[#details + 1] = apT("shop.slot.sphere", { n = math.floor(sphere) })
    end
    if gift.kind ~= nil then
        details[#details + 1] = KIND_KEY[gift.kind] and apT(KIND_KEY[gift.kind])
            or tostring(gift.kind)
    end
    local text = details[1] .. "\n" .. table.concat(details, ", ", 2)

    desc.description.data = text
    desc.description.isLiteral = true
    desc.tooltip.data = text
    desc.tooltip.isLiteral = true

    desc.cost = giftPrice(gift)
    return true
end

function apApplyShopGifts()
    local applied = 0
    local function giftKey(gift)
        return gift and (gift.location or gift.item) or nil
    end

    local placed = {}
    for _, blueprintName in ipairs(GIFT_BLUEPRINTS) do
        local current = assignment[blueprintName]
        local key = giftKey(current)
        if not alreadyGone(key) and soldHere(current) then
            placed[key] = true
        else
            assignment[blueprintName] = nil
        end
    end

    announceSize()
    local nextGift = 1
    for rank, blueprintName in ipairs(GIFT_BLUEPRINTS) do
        if rank > visibleGifts() then
            assignment[blueprintName] = nil
        elseif assignment[blueprintName] == nil then
            while nextGift <= #_G.apShopGifts do
                local candidate = _G.apShopGifts[nextGift]
                local key = giftKey(candidate)
                if alreadyGone(key) or placed[key] or not soldHere(candidate) then
                    nextGift = nextGift + 1
                else
                    break
                end
            end
            local gift = _G.apShopGifts[nextGift]
            if gift ~= nil then
                assignment[blueprintName] = gift
                placed[giftKey(gift)] = true
                nextGift = nextGift + 1
            end
        end

        local gift = assignment[blueprintName]
        if writeGift(blueprintName, gift) and gift ~= nil then
            applied = applied + 1
        end
    end

    for index, blueprintName in ipairs(DEAL_BLUEPRINTS) do
        local desc = dealDesc(blueprintName)
        if dealPercent() == 0 then
            dealsSigned[blueprintName] = true
        end
        if desc ~= nil and dealsSigned[blueprintName] and dealPercent() == 0 then
            desc.title.data = apT("deal.closed.title")
            desc.title.isLiteral = true
            desc.shortTitle.data = apT("deal.closed.short")
            desc.shortTitle.isLiteral = true
            desc.description.data = apT("deal.closed.body")
            desc.description.isLiteral = true
            -- A closed deal costs nothing: a click must not take scrap for nothing.
            desc.cost = 0
        elseif desc ~= nil and not dealsSigned[blueprintName] then
            desc.cost = DEAL_COST[index] or 5
            local reward = tostring(dealReward(index))
            local blood = DEAL_BLOOD[index]
            desc.title.data = apT(blood and "deal.blood.title" or "deal.title", { scrap = reward })
            desc.title.isLiteral = true
            desc.shortTitle.data = apT("deal.short", { scrap = reward })
            desc.shortTitle.isLiteral = true
            desc.description.data = apT("deal.body", { scrap = reward })
                .. (blood and ("\n\n" .. apT("deal.blood.risk", { chance = blood })) or "")
            desc.description.isLiteral = true
            desc.tooltip.data = desc.description.data
            desc.tooltip.isLiteral = true
        end
    end
    if applied > 0 then
        giftLog(applied .. " gift(s) displayed in the Archipelago shop")
    end
    if atApShop then
        apShopGiftsHintSeen()
    end
    return applied
end

-- shop_hints "seen": the packages on display at an Archipelago beacon become hints, once each, so their owners
-- know where their item waits. A seed from before the option hints nothing.

local function shopHintsOn()
    local value = _G.apSeedOption and apSeedOption("shop_hints")
    return value == 1 or value == "seen"
end

function apShopGiftsHintSeen()
    if not shopHintsOn() or _G.apSoloEnabled or _G.apNetHintLocation == nil then
        return 0
    end
    local hinted = 0
    for rank, blueprintName in ipairs(GIFT_BLUEPRINTS) do
        local gift = assignment[blueprintName]
        local key = gift and gift.location
        if rank <= visibleGifts() and key ~= nil and not hintedGifts[key] and not alreadyGone(key) then
            local name = _G.apLocationNameFor and apLocationNameFor(key)
            if name ~= nil and apNetHintLocation(name) then
                hintedGifts[key] = true
                hinted = hinted + 1
            end
        end
    end
    if hinted > 0 then
        giftLog(hinted .. " package(s) seen in the Archipelago shop, hinted on the server")
    end
    return hinted
end

function apShopGiftsAtApShop(here)
    atApShop = here == true
    if atApShop then
        apShopGiftsHintSeen()
    end
end

_G.apShopSlotCount = 0

function apShopSlotKeys()
    local keys = {}
    for slot = 1, (_G.apShopSlotCount or 0) do
        keys[#keys + 1] = "shop:" .. slot
    end
    return keys
end

-- What a shop slot held, bought or not: { item, slot, kind }, or nil before the scout.
function apShopSlotContent(key)
    key = tostring(key)
    for _, gift in ipairs(_G.apShopGifts or {}) do
        if tostring(gift.location or "") == key then
            return gift
        end
    end
    return nil
end

function apShopGiftsScouted(scouted)
    if type(scouted) ~= "table" then
        return false
    end
    giftLog(#scouted .. " location(s) scouted from the server")
    return apShopGiftsConfigure(scouted)
end

function apShopGiftsForgetSeed()
    sold = {}
    dealsSigned = {}
    giftLog("new seed: gifts and deals become available again")
end

function apShopGiftsConfigure(gifts, source)
    hintedGifts = {}
    if type(gifts) ~= "table" then
        return false
    end
    if source == "demo" and ((_G.apNetConnected and _G.apNetConnected()) or _G.apSoloEnabled) then
        giftLog("a seed is loaded: the shop keeps its items, not the demo")
        return false
    end
    _G.apShopGifts = gifts
    assignment = {}
    apApplyShopGifts()
    return true
end

-- Packages bought while the ship had no room: the module never put them aboard.
local boughtWithoutRoom = {}

function apShopPackageBought(blueprintName)
    boughtWithoutRoom[blueprintName] = true
end

local function playerHas(blueprintName)
    if boughtWithoutRoom[blueprintName] then
        boughtWithoutRoom[blueprintName] = nil
        return true
    end
    local found = false
    pcall(function()
        local equipment = Hyperspace.App.gui.equipScreen
        if equipment ~= nil then
            local cargo = equipment:GetCargoHold()
            for i = 0, cargo:size() - 1 do
                if tostring(cargo[i]) == blueprintName then
                    found = true
                    return
                end
            end
        end
        local weapons = Hyperspace.ships.player:GetWeaponList()
        for i = 0, weapons:size() - 1 do
            local weapon = weapons[i]
            if weapon ~= nil and tostring(weapon.blueprint.name) == blueprintName then
                found = true
                return
            end
        end
    end)
    return found
end

local function playerHasAugment(name)
    local ok, found = pcall(function()
        local list = Hyperspace.ships.player:GetAugmentationList()
        for i = 0, list:size() - 1 do
            if tostring(list[i]) == name then
                return true
            end
        end
        return false
    end)
    if ok then
        return found
    end

    local okHas, has = pcall(function()
        return Hyperspace.ships.player:HasAugmentation(name)
    end)
    return okHas and has == true
end

local function displayedPrice(blueprintName, gift)
    if gift ~= nil then
        return giftPrice(gift)
    end
    local desc = giftDesc(blueprintName)
    return desc ~= nil and math.floor(tonumber(desc.cost) or 0) or 0
end

local function collect(index, blueprintName)
    local gift = assignment[blueprintName]
    local paid = displayedPrice(blueprintName, gift)
    if gift == nil then
        giftLog("empty slot bought (" .. blueprintName .. "): nothing to send, item removed")
        pcall(function()
            Hyperspace.ships.player:RemoveItem(blueprintName, true)
        end)
        return
    end
    sold[gift.location or gift.item or blueprintName] = true

    pcall(function()
        Hyperspace.ships.player:RemoveItem(blueprintName, true)
    end)

    local who = gift and gift.slot or apT("gift.someone")
    local what = gift and gift.item or apT("gift.something")

    local reallySent = true
    if gift and gift.location and _G.apSendCheck then
        reallySent = _G.apSendCheck(gift.location, gift.item) ~= false
    end

    if not reallySent then
        local price = paid
        if price > 0 then
            pcall(function()
                Hyperspace.ships.player:ModifyScrapCount(math.floor(price), false)
            end)
        end
        -- Refused because this run does not count, not because it went out before: the package stays for later.
        local seedLoaded = _G.apContractState ~= nil and _G.apContractState.connected == true
        local notCounted = seedLoaded and ((_G.apRunRefusal ~= nil and apRunRefusal() ~= nil)
            or (_G.apTutorialRunning ~= nil and apTutorialRunning()))
        if not notCounted or gift == nil or gift.location == nil then
            giftLog("gift already sent before (" .. blueprintName .. "): refunded")
            if _G.apNotifyStatus then
                _G.apNotifyStatus(apT("shop.gift.already_sent", { price = tostring(price) }))
            end
            writeGift(blueprintName, nil)
        else
            sold[gift.location] = nil
            giftLog("gift not sent, this run does not count (" .. blueprintName .. "): refunded, kept on sale")
            if _G.apNotifyStatus then
                _G.apNotifyStatus(apT("shop.gift.not_counted", { price = tostring(price) }))
            end
            apApplyShopGifts()
        end
        return
    end

    giftLog(string.format("gift bought: %s for %s (%s)", what, who, blueprintName))
    local me = _G.apOwnSlotName and _G.apOwnSlotName() or nil
    local forMe = gift.mine == true or (me ~= nil and tostring(gift.slot) == tostring(me))
    if _G.apNotifyStatus then
        _G.apNotifyStatus(forMe and apT("shop.gift.sent.self", { item = what })
            or apT("shop.gift.sent", { item = what, slot = who }))
    end

    apApplyShopGifts()
end

-- Never the last one: the pact costs a crew member, not the run.
local function bloodPrice(index)
    local chance = DEAL_BLOOD[index]
    if chance == nil or math.random(1, 100) > chance then
        return
    end
    local player = Hyperspace.ships.player
    local alive = {}
    local crew = player.vCrewList
    for i = 0, crew:size() - 1 do
        local member = crew[i]
        local okDrone, drone = pcall(function() return member:IsDrone() end)
        if member ~= nil and member.iShipId == 0 and not member.bDead and not (okDrone and drone) then
            alive[#alive + 1] = member
        end
    end
    if #alive < 2 then
        giftLog(string.format("deal %d: the blood price falls, but only one crew member is left: spared", index))
        return
    end
    local victim = alive[math.random(1, #alive)]
    local name = tostring(victim:GetName())
    victim:Kill(true)
    giftLog(string.format("deal %d: the blood price is paid by %s", index, name))
    if _G.apNotifyWarning then
        _G.apNotifyWarning(apT("deal.blood.taken", { name = name }))
    end
end

local function signDeal(index, blueprintName)
    dealsSigned[blueprintName] = true

    pcall(function()
        Hyperspace.ships.player:RemoveItem(blueprintName, true)
    end)

    local reward = dealReward(index)
    pcall(function()
        Hyperspace.ships.player:ModifyScrapCount(reward, false)
    end)

    local againstSelf = math.random(1, 100) <= DEAL_SELF_CHANCE

    if againstSelf then
        giftLog(string.format("deal %d: +%d scrap, and the trap is ON US, in the next fight", index, reward))
        if _G.apArmDealBacklash then
            _G.apArmDealBacklash()
        end
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("deal.self", { scrap = reward }))
        end
    else
        local sent = _G.apTrapLinkSendToOne ~= nil and apTrapLinkSendToOne("Archipelago Deal")

        if sent then
            giftLog(string.format("deal %d: +%d scrap, the trap goes to someone else", index, reward))
            if _G.apNotifyStatus then
                _G.apNotifyStatus(apT("deal.other", { scrap = reward }))
            end
        else
            giftLog(string.format(
                "deal %d: +%d scrap, no one out there to take it, the trap comes back in the next fight", index, reward))
            if _G.apArmDealBacklash then
                _G.apArmDealBacklash()
            end
            if _G.apNotifyStatus then
                _G.apNotifyStatus(apT("deal.backfired", { scrap = reward }))
            end
        end
    end

    pcall(bloodPrice, index)

    local desc = dealDesc(blueprintName)
    if desc ~= nil then
        desc.title.data = apT("deal.closed.title")
        desc.title.isLiteral = true
        desc.shortTitle.data = apT("deal.closed.short")
        desc.shortTitle.isLiteral = true
        desc.description.data = apT("deal.closed.body")
        desc.description.isLiteral = true
        desc.cost = 0
    end
end

local pollDivider = 0
local refreshOnFirstTick = false

script.on_internal_event(Defines.InternalEvents.ON_TICK, function()
    -- A continued run can call on_init before its ship exists: the shop is sorted again once it does.
    if refreshOnFirstTick and Hyperspace.ships.player ~= nil then
        refreshOnFirstTick = false
        apApplyShopGifts()
    end
    pollDivider = (pollDivider + 1) % 6
    if pollDivider ~= 0 then
        return
    end
    for index, blueprintName in ipairs(GIFT_BLUEPRINTS) do
        if playerHas(blueprintName) then
            collect(index, blueprintName)
        end
    end

    for index, blueprintName in ipairs(DEAL_BLUEPRINTS) do
        if playerHasAugment(blueprintName) then
            if dealsSigned[blueprintName] then
                pcall(function()
                    Hyperspace.ships.player:RemoveItem(blueprintName, true)
                end)
                if _G.apNotifyStatus then
                    _G.apNotifyStatus(apT(dealPercent() == 0 and "deal.off" or "deal.closed"))
                end
            else
                signDeal(index, blueprintName)
            end
        end
    end
end)

script.on_init(function()
    sold = {}
    dealsSigned = {}
    apApplyShopGifts()
    refreshOnFirstTick = true
end)

script.on_internal_event(Defines.InternalEvents.JUMP_ARRIVE, function(shipManager)
    if shipManager.iShipId ~= 0 then
        return
    end
    dealsSigned = {}
    atApShop = false
    apApplyShopGifts()
end)

function apShopGiftsResetForTesting()
    sold = {}
    dealsSigned = {}
    assignment = {}
    if _G.apForgetChecksForTesting then
        _G.apForgetChecksForTesting()
    end
    apApplyShopGifts()
    giftLog("shop reset to fresh (tests)")
end

local function offerCopy(gift)
    local me = _G.apOwnSlotName and _G.apOwnSlotName() or nil
    return { item = gift.item, slot = gift.slot, sphere = gift.sphere, kind = gift.kind,
             cost = gift.cost, location = gift.location, game = gift.game,
             mine = gift.mine == true or (me ~= nil and tostring(gift.slot) == tostring(me)) }
end

function apShopGiftPeekNext()
    for _, gift in ipairs(_G.apShopGifts or {}) do
        local key = gift and (gift.location or gift.item)
        if not alreadyGone(key) and sectorReached(gift) then
            return offerCopy(gift)
        end
    end
    return nil
end

function apShopGiftGiveNext()
    local gift = apShopGiftPeekNext()
    if gift == nil then
        giftLog("no gift to give: everything is already gone")
        return nil
    end

    if gift.location and _G.apSendCheck then
        if _G.apSendCheck(gift.location, gift.item) == false then
            giftLog("gift already sent, nothing to give: " .. tostring(gift.location))
            return nil
        end
    end

    sold[gift.location or gift.item] = true
    giftLog(string.format("gift GIVEN by an event: %s for %s",
        tostring(gift.item), tostring(gift.slot)))
    apApplyShopGifts()
    return gift
end

function apShopGiftPeekMany(n)
    local found = {}
    for _, gift in ipairs(_G.apShopGifts or {}) do
        local key = gift and (gift.location or gift.item)
        if not alreadyGone(key) and sectorReached(gift) then
            found[#found + 1] = offerCopy(gift)
            if #found >= (n or 2) then
                break
            end
        end
    end
    return found
end

function apShopGiftGiveAt(location)
    if location == nil then
        return nil
    end
    for _, gift in ipairs(_G.apShopGifts or {}) do
        local key = gift and (gift.location or gift.item)
        if key == location and not alreadyGone(key) and sectorReached(gift) then
            if gift.location and _G.apSendCheck then
                if _G.apSendCheck(gift.location, gift.item) == false then
                    giftLog("gift already sent: " .. tostring(gift.location))
                    return nil
                end
            end
            sold[key] = true
            giftLog(string.format("gift CHOSEN by the player: %s for %s",
                tostring(gift.item), tostring(gift.slot)))
            apApplyShopGifts()
            return offerCopy(gift)
        end
    end
    giftLog("gift not found or already gone: " .. tostring(location))
    return nil
end

function apShopGiftsStatus()
    giftLog("Archipelago shop: " .. #_G.apShopGifts .. " gift(s) configured")
    for index, blueprintName in ipairs(GIFT_BLUEPRINTS) do
        local gift = assignment[blueprintName]
        local desc = giftDesc(blueprintName)
        giftLog(string.format("  %s: %s | displays \"%s\"",
            blueprintName,
            gift and (tostring(gift.item) .. " -> " .. tostring(gift.slot)) or "(empty)",
            desc and tostring(desc.title.data) or "?"))
    end
end

giftLog("Archipelago shop module loaded (console: LUA apShopGiftsStatus())")

]=], "@shopgift.lua", "t", _ENV)
  if chunk == nil then
    print("SYNTAX ERROR in shopgift.lua: " .. tostring(err))
    _G.__syntaxErrors = (_G.__syntaxErrors or 0) + 1
  else
    local ok, runErr = pcall(chunk)
    if not ok then
      print("LOAD ERROR in shopgift.lua: " .. tostring(runErr))
      _G.__loadErrors = (_G.__loadErrors or 0) + 1
    end
  end
end

do
  local chunk, err = load([=[
local TAG = "[AP-filler] "

local function fillerLog(message)
    log(TAG .. message)
end

local pending = {}

local toldCrewFull = false

local RESOURCE_DELIVERY = {
    scrap = function(player, n)
        player:ModifyScrapCount(n, false)
        return "filler.scrap", { n = n }
    end,
    fuel = function(player, n)
        player.fuel_count = player.fuel_count + n
        return "filler.fuel", { n = n }
    end,
    missiles = function(player, n)
        player:ModifyMissileCount(n)
        return "filler.missiles", { n = n }
    end,
    drone_parts = function(player, n)
        player:ModifyDroneCount(n)
        return "filler.drone_parts", { n = n }
    end,
    hull = function(player, n)
        player:DamageHull(-n, true)
        return "filler.hull", { n = n }
    end,
    crew = function(player, n)
        local added = 0
        for _ = 1, n do
            if player:IsCrewFull() then
                fillerLog("crew full: " .. (n - added) .. " crew member(s) not delivered")
                -- Tried again at every delivery pass: said for the first try only.
                if added == 0 and not toldCrewFull and _G.apNotifyStatus then
                    toldCrewFull = true
                    apNotifyStatus(apT("crew.waiting.new"))
                end
                break
            end
            local room = apRandomRoomId(player)
            if room == nil then
                break
            end
            player:AddCrewMemberFromString("", "human", false, room, false, math.random(0, 1) == 1)
            added = added + 1
        end
        if added == 0 then
            return nil
        end
        toldCrewFull = false
        return "filler.crew", { n = added }
    end,
}

local TRAP_LIMITS = {
    hullFloor = 3,
    fuelFloor = 2,
    systemFloor = 1,
    pursuitCeiling = 6,
    boardingCrewFloor = 2,
    fightTrapCeiling = 2,
    -- Air and a hole in the hull together kill a crew at a quiet beacon, with nothing to react to.
    drainAirWithBreach = 40,
    breachAirFloor = 40,
    -- After a drain, a crew member this hurt gets enough air back where they stand: it hurts, it does not kill.
    drainGuardSeconds = 120,
    drainGuardHealth = 0.35,
    drainGuardAir = 10,
}

_G.apTrapLimits = TRAP_LIMITS

-- The ship's air in percent, nil without an oxygen system.
local function shipAir(player)
    local oxygen = player.oxygenSystem
    if oxygen == nil then
        return nil
    end
    local levels = oxygen.oxygenLevels
    if levels:size() == 0 then
        return nil
    end
    local total = 0
    for room = 0, levels:size() - 1 do
        total = total + levels[room]
    end
    return total / levels:size()
end

local function hullBreached(player)
    local ok, breached = pcall(function() return player.ship:GetHullBreaches(true):size() > 0 end)
    return ok and breached
end

local drainGuardTicks = 0

local function guardCrewFromDrain(player)
    local oxygen = player.oxygenSystem
    local crew = player.vCrewList
    if oxygen == nil then
        return
    end
    local levels = oxygen.oxygenLevels
    for i = 0, crew:size() - 1 do
        local member = crew[i]
        local room = member ~= nil and member.iRoomId or -1
        if member ~= nil and member.iShipId == 0 and not member.bDead and room >= 0 and room < levels:size()
            and member.health.first < member.health.second * TRAP_LIMITS.drainGuardHealth
            and levels[room] < TRAP_LIMITS.drainGuardAir then
            oxygen:ModifyRoomOxygen(room, TRAP_LIMITS.drainGuardAir - levels[room])
        end
    end
end

script.on_internal_event(Defines.InternalEvents.ON_TICK, function()
    if drainGuardTicks <= 0 then
        return
    end
    drainGuardTicks = drainGuardTicks - 1
    if drainGuardTicks % 10 == 0 and Hyperspace.ships.player ~= nil then
        apTry(TAG, guardCrewFromDrain, Hyperspace.ships.player)
    end
end)

-- A room is named by the system in it: a number means nothing to the player. Nil for a room with none.
local function roomSystem(player, room)
    local ok, label = pcall(function()
        local list = player.vSystemList
        for i = 0, list:size() - 1 do
            local system = list[i]
            if system ~= nil and math.floor(system.roomId) == room then
                return apSystemLabel(Hyperspace.ShipSystem.SystemIdToName(system.iSystemType))
            end
        end
        return nil
    end)
    return ok and label or nil
end

local function where(player, room, systemKey, aboardKey)
    local system = roomSystem(player, room)
    if system ~= nil then
        return systemKey, { system = system }
    end
    return aboardKey, {}
end

local TRAP_DELIVERY = {
    fire = function(player)
        local room = apRandomRoomId(player)
        if room == nil then
            return nil
        end
        player:StartFire(room)
        return where(player, room, "trap.fire.system", "trap.fire.aboard")
    end,
    -- A breach the game draws in a room, the way a hit opens one; a damage with no damage points opens none.
    -- BreachRandomHull says nothing back in Lua (seen in game): one call, one breach.
    breach = function(player)
        if (shipAir(player) or 100) < TRAP_LIMITS.breachAirFloor then
            return nil
        end
        local room = apRandomRoomId(player)
        if room ~= nil then
            local ok = pcall(function() player.ship:BreachRandomHull(room) end)
            if ok then
                -- Told like the power surge, by a message box: a breach alone is easy to miss.
                pcall(function()
                    Hyperspace.CustomEventsParser.GetInstance():LoadEvent(Hyperspace.App.world, "AP_TRAP_BREACH", false, -1)
                end)
                return "trap.breach", { room = room }
            end
        end
        local damage = Hyperspace.Damage()
        damage.iDamage = 0
        damage.breachChance = 100
        damage.bFriendlyFire = true
        damage.ownerId = 0
        player:DamageArea(player:GetRandomRoomCenter(), damage, true)
        return "trap.breach"
    end,
    boarding = function(player)
        local alive = 0
        local crew = player.vCrewList
        for i = 0, crew:size() - 1 do
            local member = crew[i]
            if member ~= nil and member.iShipId == 0 and not member.bDead then
                alive = alive + 1
            end
        end
        if alive < TRAP_LIMITS.boardingCrewFloor then
            return nil
        end

        local room = apRandomRoomId(player)
        if room == nil then
            return nil
        end
        local ok = pcall(function()
            player:AddCrewMemberFromString("", "mantis", true, room, false, true)
        end)
        if not ok then
            return nil
        end
        return where(player, room, "trap.boarding.system", "trap.boarding.aboard")
    end,
    fuel_leak = function(player)
        local available = player.fuel_count - TRAP_LIMITS.fuelFloor
        if available <= 0 then
            return nil
        end
        local lost = math.min(available, 5)
        player.fuel_count = player.fuel_count - lost
        return "trap.fuel_leak", { n = lost }
    end,
    system_damage = function(player)
        local candidates = {}
        local systems = player.vSystemList
        for i = 0, systems:size() - 1 do
            local system = systems[i]
            if system ~= nil and system.healthState.first > TRAP_LIMITS.systemFloor then
                candidates[#candidates + 1] = system
            end
        end
        if #candidates == 0 then
            return nil
        end
        local target = candidates[math.random(1, #candidates)]
        local amount = math.min(2, target.healthState.first - TRAP_LIMITS.systemFloor)
        target:AddDamage(amount)
        return "trap.system_damage",
            { system = _G.apSystemLabel and _G.apSystemLabel(target.name) or tostring(target.name),
              n = amount }
    end,
    -- Every room loses its air at once and the oxygen system fills the ship again. Never without a working
    -- oxygen system: the crew would have nothing left to breathe, so a fire takes its place and the player is
    -- told why. With the hull breached, each room keeps some air.
    o2_drain = function(player)
        local oxygen = player.oxygenSystem
        if oxygen == nil or not oxygen:Functioning() then
            local room = apRandomRoomId(player)
            if room == nil then
                return nil
            end
            player:StartFire(room)
            return "trap.o2_drain.down", {}
        end
        local breached = hullBreached(player)
        local floor = breached and TRAP_LIMITS.drainAirWithBreach or 0
        -- Not EmptyOxygen: Hyperspace makes it do nothing outside the ship builder (seen in game).
        local levels = oxygen.oxygenLevels
        for room = 0, levels:size() - 1 do
            oxygen:ModifyRoomOxygen(room, -math.max(0, levels[room] - floor))
        end
        drainGuardTicks = TRAP_LIMITS.drainGuardSeconds * 60
        return breached and "trap.o2_drain.breach" or "trap.o2_drain"
    end,
    hull_damage = function(player)
        local hull = player.ship.hullIntegrity
        local amount = math.min(2, hull.first - TRAP_LIMITS.hullFloor)
        if amount <= 0 then
            return nil
        end
        player:DamageHull(amount, true)
        return "trap.hull_damage", { n = amount }
    end,
    fleet_advance = function()
        local starMap = Hyperspace.App.world.starMap
        if _G.apTrapFleetPushes >= TRAP_LIMITS.pursuitCeiling then
            return nil
        end
        _G.apTrapFleetPushes = _G.apTrapFleetPushes + 1
        starMap:ModifyPursuit(1)
        return "trap.fleet_advance"
    end,
    -- Armed now, sprung at the next beacon with a hostile ship: an anti-ship battery joins that fight.
    asb = function()
        return apArmFightTrap("asb") and "trap.asb" or nil
    end,
    -- Same wait: the enemy of the next fight unleashes a Flagship power surge, its lasers or its drones.
    power_surge = function()
        return apArmFightTrap("power_surge") and "trap.power_surge" or nil
    end,
    -- Same wait: the next fight's beacon gets a hazard it did not have (nebula, ion storm, asteroids, sun, pulsar).
    hazard = function()
        return apArmFightTrap("hazard") and "trap.hazard" or nil
    end,
}

-- Fight traps wait in the profile, at most fightTrapCeiling of each kind: one armed when a run ends waits for
-- the first fight of the next run.
local FIGHT_TRAPS = {
    { name = "asb", events = { "AP_TRAP_ASB" } },
    { name = "power_surge", events = { "AP_TRAP_SURGE_LASER", "AP_TRAP_SURGE_DRONES" },
      early = { "AP_TRAP_SURGE_LASER_LIGHT", "AP_TRAP_SURGE_DRONES_LIGHT" } },
    -- Its events depend on the beacon: a hazard it does not have yet.
    { name = "hazard" },
}

-- Sectors 1 and 2: a ship there cannot take a Flagship surge, it gets a lighter one.
local EARLY_SECTORS = 2

function apFightTrapArmed(name)
    local ok, value = pcall(function() return Hyperspace.metaVariables["ap_trap_" .. name] end)
    return ok and math.floor(tonumber(value) or 0) or 0
end

local function setFightTrapArmed(name, n)
    pcall(function() Hyperspace.metaVariables["ap_trap_" .. name] = n end)
end

function apArmFightTrap(name)
    local armed = apFightTrapArmed(name)
    if armed >= TRAP_LIMITS.fightTrapCeiling then
        return false
    end
    setFightTrapArmed(name, armed + 1)
    return true
end

function apTrapAsbArmed()
    return apFightTrapArmed("asb")
end

_G.apTrapFleetPushes = 0

local TRAP_TITLES = {
    fire = "trap.title.fire", breach = "trap.title.breach", fuel_leak = "trap.title.fuel_leak",
    system_damage = "trap.title.system_damage", fleet_advance = "trap.title.fleet_advance",
    hull_damage = "trap.title.hull_damage", boarding = "trap.title.boarding", asb = "trap.title.asb",
    power_surge = "trap.title.power_surge", hazard = "trap.title.hazard", o2_drain = "trap.title.o2_drain",
}

local TRAP_FALLBACK_ORDER = { "fire", "breach", "system_damage", "fuel_leak" }

local function springTrap(player, wanted)
    local order = { wanted }
    for _, name in ipairs(TRAP_FALLBACK_ORDER) do
        if name ~= wanted then
            order[#order + 1] = name
        end
    end
    for _, name in ipairs(order) do
        local effect = TRAP_DELIVERY[name]
        if effect ~= nil then
            local ok, key, params = pcall(effect, player)
            if ok and key ~= nil then
                if name ~= wanted then
                    fillerLog(string.format(
                        "trap %s impossible (floor reached), falling back to %s", wanted, name))
                end
                return key, params
            end
        end
    end
    return nil
end

function apRandomRoomId(shipManager)
    local rooms = shipManager.ship.vRoomList
    local count = rooms:size()
    if count == 0 then
        return nil
    end
    return math.floor(rooms[math.random(0, count - 1)].iRoomId)
end

local CONSUMABLE_KINDS = { filler = true, trap = true }
local RUN_START_RESOURCES = { scrap = true }

function apQueueItem(descriptor)
    if type(descriptor) ~= "table" or descriptor.kind == nil then
        fillerLog("invalid descriptor ignored")
        return false
    end
    -- Every scrap item of the seed counts toward Run Start Scrap, replayed or not: it is given once, but
    -- a share of it comes back at the start of every run.
    if descriptor.kind == "filler" and RUN_START_RESOURCES[descriptor.res] and type(_G.apInventory) == "table" then
        _G.apInventory.scrapReceived = (_G.apInventory.scrapReceived or 0) + (descriptor.n or 0)
    end
    if descriptor.isReplay and CONSUMABLE_KINDS[descriptor.kind] then
        fillerLog("already consumed in a previous session: "
            .. tostring(descriptor.res or descriptor.eff or descriptor.kind))
        return false
    end
    -- The server sends everything again after a reconnect: an item still waiting here is not queued twice.
    if descriptor.index ~= nil then
        for _, waiting in ipairs(pending) do
            if waiting.index == descriptor.index then
                return false
            end
        end
    end
    pending[#pending + 1] = descriptor
    fillerLog(string.format("queued: %s (%d in queue)",
        descriptor.res or descriptor.eff or descriptor.kind, #pending))
    return true
end

-- A ship key still in the queue is received but not in the inventory yet.
function apFillerShipsWaiting()
    for _, descriptor in ipairs(pending) do
        if descriptor.kind == "ship" then
            return true
        end
    end
    return false
end

local SHIPLESS_KINDS = { ship = true, cap = true, start = true, archive = true, pass = true }
local CATALOG_KINDS = { shop = true, crew = true }

local function noRunStarted()
    local ok, started = pcall(function() return Hyperspace.App.world.bStartedGame == true end)
    return ok and not started
end

-- Multiverse's first event takes all scrap and fuel (game_mv.lua names it): what the seed gives at the start of a
-- run waits for it, or it would be wiped. Kept in the run's save, set for a new run only.
local function startWipeDue()
    local ok, due = pcall(function() return Hyperspace.playerVariables.ap_start_wipe_due end)
    return ok and math.floor(tonumber(due) or 0) == 1
end

if _G.apStartWipeEvent then
    script.on_init(function(newGame)
        if newGame then
            pcall(function() Hyperspace.playerVariables.ap_start_wipe_due = 1 end)
        end
    end)
    local function wipeOver()
        if startWipeDue() then
            pcall(function() Hyperspace.playerVariables.ap_start_wipe_due = 0 end)
            fillerLog("start event over: run start resources can come")
        end
    end
    script.on_game_event(_G.apStartWipeEvent, false, wipeOver)
    -- A start that skips the event never blocks the run for good: the first jump ends the wait.
    script.on_internal_event(Defines.InternalEvents.JUMP_ARRIVE, function(shipManager)
        if shipManager.iShipId == 0 then
            wipeOver()
        end
    end)
end

local function safeToDeliver()
    local ok, safe = pcall(function()
        local world = Hyperspace.App.world
        if not world.bStartedGame or startWipeDue() then
            return false
        end
        local player = Hyperspace.ships.player
        if player == nil or player.bDestroyed then
            return false
        end
        -- A ship that is not hostile (a guard, a trader, a quest giver) is not a fight.
        local enemy = Hyperspace.ships.enemy
        return enemy == nil or enemy._targetable.hostile == false
    end)
    return ok and safe
end

local function markProcessed(descriptor)
    if descriptor.index ~= nil and _G.apNetItemDelivered then
        _G.apNetItemDelivered(descriptor.index)
    end
end

local function deliverOne(descriptor)
    local player = Hyperspace.ships.player
    local amount = descriptor.n or 1

    if descriptor.kind == "filler" then
        local deliver = RESOURCE_DELIVERY[descriptor.res]
        if deliver == nil then
            fillerLog("unknown resource: " .. tostring(descriptor.res))
            return false
        end
        local key, params = deliver(player, amount)
        if key == nil then
            fillerLog("delivery deferred: " .. tostring(descriptor.res))
            return false, "retry"
        end
        fillerLog("delivered: " .. key)
        if _G.apNotifyItem then
            _G.apNotifyItem(descriptor.display or apT(key, params), descriptor.sender,
                descriptor.sender == nil and not _G.apSoloEnabled)
        end
        return true
    end

    -- sector_locks: one more pass for this layout, kept for this run and the next ones.
    if descriptor.kind == "pass" then
        local inventory = _G.apInventory
        if inventory == nil or descriptor.bp == nil then
            return false
        end
        inventory.passes = inventory.passes or {}
        -- The same item sent again (a reconnection) is the same pass, not a second one.
        inventory.passIndices = inventory.passIndices or {}
        if descriptor.index ~= nil and inventory.passIndices[descriptor.index] then
            return true
        end
        if descriptor.index ~= nil then
            inventory.passIndices[descriptor.index] = true
        end
        inventory.passes[descriptor.bp] = (inventory.passes[descriptor.bp] or 0) + 1
        fillerLog("sector pass: " .. descriptor.bp .. " x" .. inventory.passes[descriptor.bp])
        if _G.apNotifyItem and not descriptor.isReplay then
            _G.apNotifyItem(descriptor.display or apT("gift.something"), descriptor.sender,
                descriptor.sender == nil and not _G.apSoloEnabled)
        end
        return true
    end

    if descriptor.kind == "archive" then
        local inventory = _G.apInventory
        if inventory == nil then
            return false
        end
        inventory.archives = (inventory.archives or 0) + (descriptor.n or 1)
        fillerLog("archive: " .. inventory.archives)
        if _G.apNotifyStatus and not descriptor.isReplay then
            local total = _G.apGoalArchives and _G.apGoalArchives() or nil
            local key = "archive.received.alone"
            if total ~= nil then
                key = inventory.archives > total and "archive.received.extra" or "archive.received"
            end
            _G.apNotifyStatus(apT(key, { done = inventory.archives, total = total or 0 }))
        end
        if _G.apDeclareGoal then
            apTry(TAG, _G.apDeclareGoal)
        end
        return true
    end

    if descriptor.kind == "ship" or descriptor.kind == "cap" or descriptor.kind == "start" then
        if _G.apInventoryAdd == nil then
            fillerLog("inventory.lua missing: inventory item ignored")
            return false
        end
        if not _G.apInventoryAdd(descriptor) then
            return false
        end
        if _G.apNotifyItem and not descriptor.isReplay then
            local name = descriptor.display
            -- A Head Start's item name is English: the game's own name of the system reads in every language.
            if descriptor.kind == "start" and descriptor.sys ~= nil and descriptor.sys ~= "reactor"
                and _G.apSystemLabel then
                name = apSystemLabel(descriptor.sys)
            end
            if name == nil and descriptor.bp ~= nil then
                name = _G.apShipLabel and _G.apShipLabel(descriptor.bp) or descriptor.bp
            end
            if name == nil and descriptor.sys ~= nil then
                name = _G.apSystemLabel and _G.apSystemLabel(descriptor.sys) or descriptor.sys
            end
            if name ~= nil and _G.apHumaniseId and name:find("%u[%u%d]*_[%u%d_]+") then
                name = _G.apHumaniseId(name)
            end
            if descriptor.kind == "start" and _G.apNotifyStatus then
                _G.apNotifyStatus(apT("start.received", { item = tostring(name) }))
            else
                _G.apNotifyItem(name, descriptor.sender, descriptor.sender == nil and not _G.apSoloEnabled)
            end
        end
        return true
    end

    if descriptor.kind == "weapon" or descriptor.kind == "drone" or descriptor.kind == "augment" then
        if _G.apDeliverEquipment == nil then
            fillerLog("equipment.lua missing: equipment item ignored")
            return false
        end
        return _G.apDeliverEquipment(descriptor)
    end

    if descriptor.kind == "crew" and tonumber(descriptor.tiers) ~= nil then
        local inventory = _G.apInventory
        if inventory == nil or type(descriptor.race) ~= "string" then
            return false
        end
        inventory.crewProgress = inventory.crewProgress or {}
        local progress = inventory.crewProgress[descriptor.race] or { n = 0 }
        progress.n = progress.n + 1
        progress.skill = descriptor.skill
        inventory.crewProgress[descriptor.race] = progress
        local name = _G.apRaceLabel and _G.apRaceLabel(descriptor.race) or descriptor.race
        fillerLog("progressive crew member " .. descriptor.race .. ": tier " .. progress.n)
        if descriptor.isReplay then
            return true
        end
        local key = progress.n >= 3 and "crew.progress.expert"
            or progress.n == 2 and "crew.progress.menu" or "crew.progress.later"
        if progress.n == 1 and not descriptor.noDelivery and _G.apRecruitCrew then
            local aboard, reason = _G.apRecruitCrew(descriptor.race, nil)
            if aboard then
                key = "crew.progress.aboard"
            elseif reason == "crew full" and _G.apOweCrew then
                apOweCrew(descriptor.race, nil)
                key = "crew.waiting"
            end
        end
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT(key, { name = tostring(name) }))
        end
        return true
    end

    if descriptor.kind == "crew" then
        local inventory = _G.apInventory
        if inventory == nil or type(descriptor.race) ~= "string" then
            return false
        end
        inventory.crew = inventory.crew or {}
        inventory.crew[#inventory.crew + 1] = {
            race = descriptor.race, skill = descriptor.skill, display = descriptor.display,
        }
        if descriptor.isReplay or descriptor.noDelivery or not _G.apRecruitCrew then
            if descriptor.noDelivery and not descriptor.isReplay and _G.apNotifyStatus then
                _G.apNotifyStatus(apT("crew.received.menu",
                    { name = tostring(descriptor.display or descriptor.race) }))
            end
            return true
        end
        local aboard, reason = _G.apRecruitCrew(descriptor.race, descriptor.skill)
        fillerLog("crew member " .. tostring(descriptor.display or descriptor.race)
            .. (aboard and " aboard" or (" catalog only: " .. tostring(reason))))
        local waiting = not aboard and reason == "crew full" and _G.apOweCrew ~= nil
        if waiting then
            apOweCrew(descriptor.race, descriptor.skill)
        end
        if _G.apNotifyStatus then
            local key = aboard and "crew.received.aboard" or (waiting and "crew.waiting" or "crew.received.menu")
            _G.apNotifyStatus(apT(key, { name = tostring(descriptor.display or descriptor.race) }))
        end
        return true
    end

    if descriptor.kind == "shop" then
        if _G.apApplyShopItem == nil then
            fillerLog("shop.lua missing: shop item ignored")
            return false
        end
        return _G.apApplyShopItem(descriptor)
    end

    if descriptor.kind == "trap" then
        if TRAP_DELIVERY[descriptor.eff] == nil then
            fillerLog("unknown trap: " .. tostring(descriptor.eff))
            if _G.apNotifyStatus then
                _G.apNotifyStatus(apT("item.unknown",
                    { name = descriptor.display or tostring(descriptor.eff) }))
            end
            return false
        end
        local key, params = springTrap(player, descriptor.eff)
        if key == nil then
            fillerLog("trap fizzled: all floors already reached")
            if _G.apNotifyTrap then
                _G.apNotifyTrap(apT("trap.fizzled"))
            end
            return true
        end
        fillerLog("trap triggered: " .. key)
        if _G.apNotifyTrap then
            local effect = apT(key, params)
            -- Our own traps are named in the player's language; one from Trap Link keeps its game's name.
            local title = descriptor.display
            if not descriptor.fromLink and TRAP_TITLES[descriptor.eff] then
                title = apT(TRAP_TITLES[descriptor.eff])
            end
            if title ~= nil and title ~= "" then
                _G.apNotifyTrap(apT("trap.named", { name = title, effect = effect }))
            else
                _G.apNotifyTrap(effect)
            end
        end
        if _G.apTrapLinkOnTrap then
            apTry(TAG, _G.apTrapLinkOnTrap, descriptor)
        end
        return true
    end

    return false
end

-- New Crew Member items waiting in the queue for a free seat.
function apFillerCrewWaiting()
    local count = 0
    for _, descriptor in ipairs(pending) do
        if descriptor.kind == "filler" and descriptor.res == "crew" then
            count = count + (tonumber(descriptor.n) or 1)
        end
    end
    return count
end

-- Whether a delivery pass can hand things out now (in a run that counts, no fight).
function apFillerCanDeliver()
    return safeToDeliver() and apFillerRunCounts()
end

-- Weapons and drones still waiting, for the "wait for the next jump" line.
function apFillerEquipmentWaiting()
    local count = 0
    for _, descriptor in ipairs(pending) do
        local family = descriptor.kind
        if family == "shop" and descriptor.bp and _G.apBlueprintFamily then
            family = apBlueprintFamily(descriptor.bp)
        end
        if family == "weapon" or family == "drone" then
            count = count + 1
        end
    end
    return count
end

-- A run started without this seed does not count: what it would use up waits for a run that does.
local function runCounts()
    local contract = _G.apContractState
    if _G.apRunMatchesSeed == nil or noRunStarted() or contract == nil or contract.connected ~= true then
        return true
    end
    return apRunMatchesSeed()
end

function apFillerRunCounts()
    return runCounts()
end

function apDeliverPending()
    if #pending == 0 then
        return
    end
    local counts = runCounts()
    local inRun = safeToDeliver() and counts
    if not inRun and counts and not noRunStarted() and _G.apShopKeepOwed then
        for _, descriptor in ipairs(pending) do
            if descriptor.kind == "shop" and not descriptor.isReplay and not descriptor.keptOwed then
                descriptor.keptOwed = true
                apShopKeepOwed(descriptor.bp)
            end
        end
    end
    local deliverable = function(descriptor)
        if inRun or SHIPLESS_KINDS[descriptor.kind] == true then
            return true
        end
        if CATALOG_KINDS[descriptor.kind] and (noRunStarted() or not counts) then
            descriptor.noDelivery = true
            return true
        end
        return false
    end
    -- Runs every tick while something is queued: leave early when nothing can be delivered yet.
    if not inRun then
        local none = true
        for _, descriptor in ipairs(pending) do
            if deliverable(descriptor) then none = false break end
        end
        if none then
            return
        end
    end

    local delivered = 0
    local deferred = {}
    local index = 1
    while index <= #pending do
        local descriptor = pending[index]
        if not deliverable(descriptor) then
            index = index + 1
        else
            table.remove(pending, index)
            local ok, result, reason = pcall(deliverOne, descriptor)
            if ok and result then
                delivered = delivered + 1
                markProcessed(descriptor)
            elseif ok and reason == "retry" then
                deferred[#deferred + 1] = descriptor
            elseif ok then
                fillerLog("permanently dropped (" .. tostring(descriptor.kind) .. "): "
                    .. tostring(descriptor.display or descriptor.bp or descriptor.res or "?"))
                markProcessed(descriptor)
            else
                descriptor.attempts = (descriptor.attempts or 0) + 1
                fillerLog(string.format("delivery failed (%s%s, attempt %d): %s",
                    tostring(descriptor.kind),
                    descriptor.bp and (" " .. tostring(descriptor.bp)) or "",
                    descriptor.attempts, tostring(result)))
                if descriptor.attempts < 3 then
                    deferred[#deferred + 1] = descriptor
                else
                    markProcessed(descriptor)
                    if _G.apNotifyStatus then
                        _G.apNotifyStatus(apT("item.failed",
                            { name = descriptor.display or tostring(descriptor.kind) }))
                    end
                end
            end
        end
        inRun = safeToDeliver() and counts
    end
    for _, descriptor in ipairs(deferred) do
        pending[#pending + 1] = descriptor
    end

    if delivered > 0 then
        fillerLog(delivered .. " item(s) delivered, " .. #pending .. " pending")
    end
end

function apRunStartScrap()
    local percent = tonumber(_G.apSeedOption and apSeedOption("run_start_scrap") or 0) or 0
    local received = tonumber((_G.apInventory or {}).scrapReceived or 0) or 0
    return math.floor(received * percent / 100)
end

-- Given once the run is under way, not in on_init: the ship may not exist yet, the start events (Multiverse's)
-- come first, and the items of the seed may not all be in. The run's save says it is still owed.
local function giveRunStartScrap()
    if math.floor(tonumber(Hyperspace.playerVariables.ap_run_scrap_owed) or 0) ~= 1 then
        return
    end
    if not (_G.apInventorySynced and apInventorySynced()) then
        return
    end
    if Hyperspace.ships.player == nil or noRunStarted() or startWipeDue() then
        return
    end
    Hyperspace.playerVariables.ap_run_scrap_owed = 0
    local amount = apRunStartScrap()
    if amount <= 0 then
        return
    end
    Hyperspace.ships.player:ModifyScrapCount(amount, false)
    fillerLog("run start scrap: +" .. amount)
    if _G.apNotifyStatus then
        _G.apNotifyStatus(apT("filler.run_start_scrap", { n = amount }))
    end
end

script.on_init(function(newGame)
    if newGame then
        pcall(function() Hyperspace.playerVariables.ap_run_scrap_owed = 1 end)
    end
end)

script.on_internal_event(Defines.InternalEvents.ON_TICK, function()
    apTry(TAG, giveRunStartScrap)
end)

function apFillerForgetSeed()
    local remaining = #pending
    pending = {}
    if remaining > 0 then
        fillerLog("new seed: " .. remaining .. " queued item(s) dropped")
    end
end

function apFillerResetForTesting()
    pending = {}
end

function apFillerPendingForTesting()
    return pending
end

function apFillerStatus()
    fillerLog(#pending .. " item(s) waiting to be delivered")
    for index, descriptor in ipairs(pending) do
        fillerLog(string.format("  %d. %s %s x%d", index, descriptor.kind,
            descriptor.res or descriptor.eff or "?", descriptor.n or 1))
    end
end

_G.apSupportedKinds = {
    ship = true, cap = true, start = true, filler = true, trap = true,
    weapon = true, drone = true, augment = true, shop = true, archive = true, crew = true, bundle = true,
    layout = true, progressive_ship = true, pass = true,
    -- Not delivered as such: the seed says its first Progressive items unlock their system (inventory.lua).
    cap_unlock = true,
}

_G.apSupportedResources = {}
for name in pairs(RESOURCE_DELIVERY) do
    _G.apSupportedResources[name] = true
end

_G.apSupportedTrapEffects = {}
for name in pairs(TRAP_DELIVERY) do
    _G.apSupportedTrapEffects[name] = true
end

script.on_init(function()
    _G.apTrapFleetPushes = 0
end)

script.on_internal_event(Defines.InternalEvents.JUMP_ARRIVE, function(shipManager)
    if shipManager.iShipId == 0 then
        apDeliverPending()
    end
end)

-- A fight trap comes as an event once the fight is on and no other event is open, one per fight. The Last Stand
-- keeps it for later, and so does a beacon that already has what the trap would bring.
local sprungHere = false
-- An anti-ship battery or a hazard brought by a trap goes away with the fight. Switching it off clears every
-- hazard, so the beacon's own ones (asteroids, sun, pulsar, ion storm) are put back right after.
local cleanupHere = nil

local RESTORE_EVENTS = {
    asteroid = "AP_TRAP_RESTORE_ASTEROID", sun = "AP_TRAP_RESTORE_SUN",
    pulsar = "AP_TRAP_RESTORE_PULSAR", storm = "AP_TRAP_RESTORE_STORM",
}
local HAZARD_EVENTS = {
    nebula = "AP_TRAP_HAZARD_NEBULA", storm = "AP_TRAP_HAZARD_STORM", asteroid = "AP_TRAP_HAZARD_ASTEROID",
    sun = "AP_TRAP_HAZARD_SUN", pulsar = "AP_TRAP_HAZARD_PULSAR",
}

-- What the beacon has on its own, before any trap.
local function beaconHazards()
    local hazards = {}
    pcall(function()
        local space = Hyperspace.App.world.space
        hazards.pds = space.bPDS == true or nil
        hazards.nebula = space.bNebula == true or nil
        hazards.storm = space.bStorm == true or nil
        hazards.asteroid = space.asteroidGenerator.bRunning == true or nil
        hazards.sun = space.sunLevel == true or nil
        hazards.pulsar = space.pulsarLevel == true or nil
    end)
    return hazards
end

local function trapEvents(trap, hazards)
    if trap.name == "asb" then
        return not hazards.pds and trap.events or {}
    end
    if trap.name == "hazard" then
        local events = {}
        for _, hazard in ipairs({ "nebula", "storm", "asteroid", "sun", "pulsar" }) do
            if not hazards[hazard] then
                events[#events + 1] = HAZARD_EVENTS[hazard]
            end
        end
        return events
    end
    local ok, level = pcall(function() return Hyperspace.App.world.starMap.worldLevel end)
    if trap.early and ok and tonumber(level) and level + 1 <= EARLY_SECTORS then
        return trap.early
    end
    return trap.events
end

local function springFightTrap()
    if sprungHere then
        return
    end
    local ready = false
    pcall(function()
        local app = Hyperspace.App
        local gui = app.gui
        local enemy = Hyperspace.ships.enemy
        ready = app.world.bStartedGame and not (gui.choiceBoxOpen or gui.event_pause or gui.menu_pause)
            and enemy ~= nil and not enemy.bDestroyed and enemy._targetable.hostile == true
            and not app.world.starMap.bossLevel
    end)
    if not ready then
        return
    end
    local hazards = beaconHazards()
    for _, trap in ipairs(FIGHT_TRAPS) do
        local armed = apFightTrapArmed(trap.name)
        local events = trapEvents(trap, hazards)
        if armed > 0 and #events > 0 then
            local event = events[math.random(1, #events)]
            local ok, err = pcall(function()
                Hyperspace.CustomEventsParser.GetInstance():LoadEvent(Hyperspace.App.world, event, false, -1)
            end)
            if not ok then
                fillerLog("fight trap " .. trap.name .. " not sprung: " .. tostring(err))
                return
            end
            setFightTrapArmed(trap.name, armed - 1)
            sprungHere = true
            if trap.name == "asb" or trap.name == "hazard" then
                cleanupHere = { trap = trap.name, hazards = hazards,
                                nebulaAdded = event == HAZARD_EVENTS.nebula
                                    or (event == HAZARD_EVENTS.storm and not hazards.nebula) }
            end
            fillerLog("fight trap sprung: " .. event)
            return
        end
    end
end

-- A pact that turns on you strikes in the next fight, not at the quiet shop beacon where a fire or a breach is
-- repaired for free. Kept in the run's save, so quitting does not cancel it. At most two strike per fight.
local DEAL_EFFECTS = { "fire", "breach", "system_damage", "hull_damage", "fuel_leak" }
local DEAL_STRIKES_PER_FIGHT = 2
local dealStrikesHere = 0

function apDealBacklashArmed()
    local ok, value = pcall(function() return Hyperspace.playerVariables.ap_deal_backlash end)
    return ok and math.floor(tonumber(value) or 0) or 0
end

local function setDealBacklash(n)
    pcall(function() Hyperspace.playerVariables.ap_deal_backlash = math.max(0, n) end)
end

function apArmDealBacklash()
    setDealBacklash(apDealBacklashArmed() + 1)
    fillerLog("pact backlash armed for the next fight (" .. apDealBacklashArmed() .. " waiting)")
end

local function strikeDealBacklash()
    local armed = apDealBacklashArmed()
    if armed <= 0 or dealStrikesHere >= DEAL_STRIKES_PER_FIGHT then
        return
    end
    local ready = false
    pcall(function()
        local app = Hyperspace.App
        local gui = app.gui
        local enemy = Hyperspace.ships.enemy
        local player = Hyperspace.ships.player
        ready = app.world.bStartedGame and player ~= nil and not player.bDestroyed
            and not (gui.choiceBoxOpen or gui.event_pause or gui.menu_pause)
            and enemy ~= nil and not enemy.bDestroyed and enemy._targetable.hostile == true
    end)
    if not ready or not runCounts() then
        return
    end
    setDealBacklash(armed - 1)
    dealStrikesHere = dealStrikesHere + 1
    local key, params = springTrap(Hyperspace.ships.player, DEAL_EFFECTS[math.random(1, #DEAL_EFFECTS)])
    if key == nil then
        fillerLog("pact backlash fizzled: all floors already reached")
        return
    end
    fillerLog("pact backlash struck: " .. key)
    if _G.apNotifyTrap then
        _G.apNotifyTrap(apT("trap.named", { name = apT("deal.own_pact"), effect = apT(key, params) }))
    end
end

-- The enemy surrendered, fled or is beaten: what the trap brought goes, it was not part of the beacon.
local function fightOver()
    local enemy = Hyperspace.ships.enemy
    if enemy == nil or enemy.bDestroyed or enemy._targetable.hostile ~= true then
        return true
    end
    if enemy.ship.hullIntegrity.first <= 0 then
        return true
    end
    return not enemy.bAutomated and enemy:CountCrew(false) == 0
end

local function cleanUpTrap()
    if cleanupHere == nil then
        return
    end
    local ready = false
    pcall(function()
        local gui = Hyperspace.App.gui
        ready = not (gui.choiceBoxOpen or gui.event_pause or gui.menu_pause) and fightOver()
    end)
    if not ready then
        return
    end
    local cleanup = cleanupHere
    cleanupHere = nil
    local ending = "AP_TRAP_ASB_END"
    if cleanup.trap == "hazard" then
        ending = cleanup.nebulaAdded and "AP_TRAP_HAZARD_END_NEBULA" or "AP_TRAP_HAZARD_END"
    end
    local ok, err = pcall(function()
        local parser = Hyperspace.CustomEventsParser.GetInstance()
        parser:LoadEvent(Hyperspace.App.world, ending, false, -1)
        for _, hazard in ipairs({ "asteroid", "sun", "pulsar", "storm" }) do
            if cleanup.hazards[hazard] then
                parser:LoadEvent(Hyperspace.App.world, RESTORE_EVENTS[hazard], false, -1)
            end
        end
    end)
    fillerLog(ok and ("trap " .. cleanup.trap .. " cleared: the fight is over")
        or ("trap not cleared: " .. tostring(err)))
end

script.on_internal_event(Defines.InternalEvents.JUMP_ARRIVE, function(shipManager)
    if shipManager.iShipId == 0 then
        sprungHere = false
        cleanupHere = nil
        dealStrikesHere = 0
    end
end)

script.on_init(function()
    sprungHere = false
    cleanupHere = nil
    dealStrikesHere = 0
end)

local pollDivider = 0
script.on_internal_event(Defines.InternalEvents.ON_TICK, function()
    pollDivider = (pollDivider + 1) % 120
    if pollDivider == 0 then
        apDeliverPending()
    end
    if pollDivider % 30 == 0 then
        apTry(TAG, springFightTrap)
        apTry(TAG, cleanUpTrap)
        apTry(TAG, strikeDealBacklash)
    end
end)

fillerLog("filler and traps module loaded (console: LUA apFillerStatus())")

]=], "@filler.lua", "t", _ENV)
  if chunk == nil then
    print("SYNTAX ERROR in filler.lua: " .. tostring(err))
    _G.__syntaxErrors = (_G.__syntaxErrors or 0) + 1
  else
    local ok, runErr = pcall(chunk)
    if not ok then
      print("LOAD ERROR in filler.lua: " .. tostring(runErr))
      _G.__loadErrors = (_G.__loadErrors or 0) + 1
    end
  end
end

do
  local chunk, err = load([=[
local TAG = "[AP-energy] "

local function energyLog(message)
    log(TAG .. message)
end

local JOULES_PER_FUEL = 1000000

local SCRAP_JOULES = JOULES_PER_FUEL / 30

local DEPOSIT_LOSS = 0.25

_G.apEnergyLink = {
    enabled = false,
    depositFuelAbove = 20,
    depositScrapAbove = 0,
    depositScrapShare = 0.25,
    withdrawFuelBelow = 3,
    withdrawFuelAmount = 2,
}

local state = {
    pool = 0,
    deposited = 0,
    withdrawn = 0,
    pendingRequest = 0,
    withdrawnThisBeacon = false,
    lastError = nil,
}

_G.apEnergyLinkState = state

function apEnergyLinkConfigure(settings)
    if type(settings) ~= "table" then
        return false
    end
    local config = _G.apEnergyLink
    for key, value in pairs(settings) do
        if config[key] ~= nil then
            config[key] = value
        end
    end
    energyLog("configure: enabled=" .. tostring(config.enabled))
    return true
end

local function joulesToFuel(joules)
    local units = math.floor(joules / JOULES_PER_FUEL)
    return units, joules - (units * JOULES_PER_FUEL)
end

local function humanJoules(joules)
    if joules >= 1000000 then
        return string.format("%.1f MJ", joules / 1000000)
    end
    if joules >= 1000 then
        return string.format("%.0f kJ", joules / 1000)
    end
    return string.format("%d J", joules)
end

_G.apEnergyLinkHuman = humanJoules
_G.apEnergyLinkJoulesPerFuel = JOULES_PER_FUEL

-- whole: skip the deposit loss (energy going back to the pool, or already net).
function apEnergyLinkDeposit(joules, whole)
    if joules <= 0 then
        return 0
    end
    if not (_G.apEnergyLink and _G.apEnergyLink.enabled) then
        energyLog("energy link disabled by the seed: nothing deposited")
        return 0
    end
    local net = whole and math.floor(joules) or math.floor(joules * (1 - DEPOSIT_LOSS))
    if net <= 0 then
        return 0
    end

    if _G.apNetEnergyLinkDeposit then
        local ok, sent = pcall(_G.apNetEnergyLinkDeposit, net)
        if not ok then
            state.lastError = tostring(sent)
            energyLog("deposit failed: " .. tostring(sent))
            return 0
        end
        if sent == false then
            state.lastError = "deposit refused by the server"
            energyLog("deposit REFUSED: " .. humanJoules(net) .. " did not go through")
            return 0
        end
        energyLog("deposited to the server: " .. humanJoules(net))
    else
        energyLog("(offline) would have deposited " .. humanJoules(net))
    end

    state.deposited = state.deposited + net
    state.pool = state.pool + net
    return net
end

function apEnergyLinkContribute()
    local config = _G.apEnergyLink
    if not config.enabled then
        return 0
    end
    local player = Hyperspace.ships.player
    if player == nil then
        return 0
    end

    local joules = 0
    local given = {}
    local fuelToTake = 0
    local scrapToTake = 0

    local surplus = player.fuel_count - config.depositFuelAbove
    if surplus > 0 then
        fuelToTake = surplus
        joules = joules + surplus * JOULES_PER_FUEL
        given[#given + 1] = apT("energylink.part.fuel", { n = surplus })
    end

    if config.depositScrapAbove > 0 then
        local ok, scrap = pcall(function()
            return Hyperspace.ships.player.currentScrap
        end)
        if ok and type(scrap) == "number" and scrap > config.depositScrapAbove then
            local share = math.floor((scrap - config.depositScrapAbove) * config.depositScrapShare)
            if share > 0 then
                scrapToTake = share
                joules = joules + share * SCRAP_JOULES
                given[#given + 1] = apT("energylink.part.scrap", { n = share })
            end
        end
    end

    if joules <= 0 then
        return 0
    end

    local net = apEnergyLinkDeposit(joules)
    if net <= 0 then
        return 0
    end

    player.fuel_count = player.fuel_count - fuelToTake
    if scrapToTake > 0 then
        player:ModifyScrapCount(-scrapToTake, false)
    end

    if net > 0 then
        energyLog("deposited " .. table.concat(given, " + ") .. " = " .. humanJoules(net)
            .. " (after " .. math.floor(DEPOSIT_LOSS * 100) .. "% loss)")
        if _G.apNotifyStatus then
            -- What lands in the reserve, in fuel: the dashboard's figure grows by this, not by what was given.
            local fuel = net / JOULES_PER_FUEL
            local shown = fuel == math.floor(fuel) and tostring(math.floor(fuel)) or string.format("%.1f", fuel)
            _G.apNotifyStatus(apT("energylink.sent", { what = table.concat(given, " + "), net = shown }))
        end
    end
    return net
end

function apEnergyLinkRequestFuel(units)
    local config = _G.apEnergyLink
    if not config.enabled then
        return false
    end
    units = units or config.withdrawFuelAmount
    if units <= 0 then
        return false
    end

    local joules = units * JOULES_PER_FUEL
    state.pendingRequest = state.pendingRequest + joules

    if _G.apNetEnergyLinkRequest then
        local ok, sent = pcall(_G.apNetEnergyLinkRequest, joules)
        if not ok then
            state.pendingRequest = state.pendingRequest - joules
            state.lastError = tostring(sent)
            energyLog("request failed: " .. tostring(sent))
            return false
        end
        if sent == false then
            state.pendingRequest = state.pendingRequest - joules
            state.lastError = "request refused by the server"
            energyLog("request REFUSED: " .. humanJoules(joules))
            return false
        end
    else
        state.pendingRequest = state.pendingRequest - joules
        energyLog("(offline) would have requested " .. humanJoules(joules))
        return false
    end
    return true
end

function apEnergyLinkGranted(joules)
    state.pendingRequest = math.max(0, state.pendingRequest - joules)
    if joules <= 0 then
        energyLog("pool empty: no fuel granted")
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("energylink.empty"))
        end
        return 0
    end

    local units, remainder = joulesToFuel(joules)
    if units <= 0 then
        apEnergyLinkDeposit(joules, true)
        energyLog("granted " .. humanJoules(joules) .. ", not enough for one unit: returned")
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("energylink.empty"))
        end
        return 0
    end

    local player = Hyperspace.ships.player
    if player == nil then
        apEnergyLinkDeposit(joules, true)
        return 0
    end

    player.fuel_count = player.fuel_count + units
    state.withdrawn = state.withdrawn + (units * JOULES_PER_FUEL)
    state.pool = math.max(0, state.pool - joules)

    if remainder > 0 then
        apEnergyLinkDeposit(remainder, true)
    end

    energyLog("received " .. units .. " fuel unit(s) from the shared pool")
    if _G.apNotifyStatus then
        _G.apNotifyStatus(apT("energylink.received", { n = units }))
    end
    return units
end

-- Every change of ours is already counted in state.pool: a pool grown by a whole fuel unit or more since the
-- last look was filled by the other players, and the player is told.
function apEnergyLinkSync(joules)
    local value = tonumber(joules) or 0
    if state.poolKnown then
        local added = math.floor((value - state.pool) / JOULES_PER_FUEL)
        if added >= 1 then
            energyLog("the other players put " .. added .. " fuel unit(s) in the shared pool")
            if _G.apNotifyStatus then
                _G.apNotifyStatus(apT("energylink.others", { n = added }))
            end
        end
    end
    state.pool = value
    state.poolKnown = true
end

-- The pool in whole fuel units, nil until the server told it.
function apEnergyLinkPoolFuel()
    if not state.poolKnown then
        return nil
    end
    return math.floor(math.max(0, state.pool) / JOULES_PER_FUEL)
end

-- Other slots fill and drain the pool too: a look every 20 seconds keeps the dashboard's figure fresh.
-- Adding 0 changes nothing and answers with the pool's value.
local lookTicks = 0
script.on_internal_event(Defines.InternalEvents.ON_TICK, function()
    lookTicks = lookTicks + 1
    if lookTicks < (state.poolKnown and 60 * 20 or 60 * 2) then
        return
    end
    lookTicks = 0
    if _G.apEnergyLink and _G.apEnergyLink.enabled and _G.apNetEnergyLinkDeposit then
        local ok, looked = pcall(_G.apNetEnergyLinkDeposit, 0)
        if not ok or looked == false then
            state.poolKnown = false
        end
    end
end)

local function considerWithdrawal()
    local config = _G.apEnergyLink
    if not config.enabled or state.withdrawnThisBeacon then
        return
    end
    local player = Hyperspace.ships.player
    if player == nil or player.fuel_count > config.withdrawFuelBelow then
        return
    end
    state.withdrawnThisBeacon = true
    energyLog("fuel at " .. player.fuel_count .. ": requesting from the shared pool")
    apEnergyLinkRequestFuel(config.withdrawFuelAmount)
end

script.on_internal_event(Defines.InternalEvents.JUMP_ARRIVE, function(shipManager)
    if shipManager.iShipId ~= 0 then
        return
    end
    state.withdrawnThisBeacon = false
    considerWithdrawal()
    apTry(TAG, apEnergyLinkContribute)
end)

script.on_init(function()
    state.withdrawnThisBeacon = false
    state.pendingRequest = 0
end)

function apEnergyLinkStatus()
    local config = _G.apEnergyLink
    energyLog("EnergyLink " .. (config.enabled and "active" or "inactive")
        .. " | 1 fuel = " .. humanJoules(JOULES_PER_FUEL)
        .. ", deposit loss " .. math.floor(DEPOSIT_LOSS * 100) .. "%")
    energyLog(string.format("  known pool=%s deposited=%s withdrawn=%s",
        humanJoules(state.pool), humanJoules(state.deposited), humanJoules(state.withdrawn)))
    energyLog(string.format("  deposit above %d fuel, request below %d",
        config.depositFuelAbove, config.withdrawFuelBelow))
end

energyLog("EnergyLink module loaded (console: LUA apEnergyLinkStatus())")

]=], "@energylink.lua", "t", _ENV)
  if chunk == nil then
