  else
    local ok, runErr = pcall(chunk)
    if not ok then
      print("LOAD ERROR in energylink.lua: " .. tostring(runErr))
      _G.__loadErrors = (_G.__loadErrors or 0) + 1
    end
  end
end

do
  local chunk, err = load([=[
local TAG = "[AP-death] "

local function deathLog(message)
    log(TAG .. message)
end

local TICKS_PER_SECOND = 60

_G.apDeathLink = {
    enabled = false,
    offered = false,
    toggle = true,
    trigger = "both",
    effect = "major_incident",
    cloned = false,
    graceSeconds = 15,
}

_G.apDeathLinkTriggers = { ship_destroyed = true, crew_death = true, both = true }
_G.apDeathLinkEffects = {
    major_incident = true, crew_member = true, hull_damage = true, fire = true,
    boarding = true, varied = true,
}

local state = {
    ticks = 0,
    lastReceivedAt = nil,
    lastSentAt = nil,
    sent = 0,
    received = 0,
    ignored = 0,
    knownCrew = nil,
    dying = {},
    cloning = {},
    away = {},
    applying = false,
}

_G.apDeathLinkState = state

local function mutedKey()
    return apNetSlotKey("ap_deathlink_off_" .. tostring(_G.apSeedFingerprint and apSeedFingerprint() or 0))
end

function apDeathLinkRemembered()
    return _G.apNetRecallText ~= nil and apNetRecallText(mutedKey()) == "1"
end

-- The player's own choice for this slot, from the dashboard. The seed's death_link_toggle can forbid it.
function apDeathLinkToggle()
    local config = _G.apDeathLink
    if not config.offered or config.toggle == false then
        return false
    end
    config.enabled = not config.enabled
    if _G.apNetRememberText then
        apNetRememberText(mutedKey(), config.enabled and "" or "1")
    end
    state.knownCrew = nil
    state.cloning = {}
    state.away = {}
    if _G.apNetAnnounceTags then
        apNetAnnounceTags()
    end
    deathLog("toggled from the dashboard: " .. (config.enabled and "on" or "off"))
    if _G.apNotifyStatus then
        _G.apNotifyStatus(apT(config.enabled and "deathlink.turned_on" or "deathlink.turned_off"))
    end
    return true
end

function apDeathLinkConfigure(settings)
    if type(settings) ~= "table" then
        return false
    end
    local config = _G.apDeathLink
    for _, key in ipairs({ "enabled", "toggle", "trigger", "effect", "cloned", "graceSeconds" }) do
        if settings[key] ~= nil then
            config[key] = settings[key]
        end
    end
    config.offered = config.enabled == true
    if config.offered and config.toggle ~= false and apDeathLinkRemembered() then
        config.enabled = false
    end
    deathLog(string.format("configure: enabled=%s trigger=%s effect=%s cloned=%s grace=%ss",
        tostring(config.enabled), config.trigger, config.effect, tostring(config.cloned),
        tostring(config.graceSeconds)))
    return true
end

local function triggerCoversRunEnd()
    local trigger = _G.apDeathLink.trigger
    return trigger == "ship_destroyed" or trigger == "both"
end

local function triggerCoversCrew()
    local trigger = _G.apDeathLink.trigger
    return trigger == "crew_death" or trigger == "both"
end

local function inGracePeriod()
    if state.lastReceivedAt == nil then
        return false
    end
    local grace = (_G.apDeathLink.graceSeconds or 0) * TICKS_PER_SECOND
    return (state.ticks - state.lastReceivedAt) < grace
end

local SEND_COOLDOWN_SECONDS = 10

function apDeathLinkSend(cause)
    local config = _G.apDeathLink
    if not config.enabled then
        return false
    end
    if state.applying then
        state.ignored = state.ignored + 1
        deathLog("death not sent: it came from a received DeathLink")
        return false
    end
    if inGracePeriod() then
        state.ignored = state.ignored + 1
        deathLog("death not sent: grace period active")
        return false
    end
    -- The last crew member dying also ends the run: one event, so the others die once.
    if state.lastSentAt ~= nil and state.ticks - state.lastSentAt < SEND_COOLDOWN_SECONDS * TICKS_PER_SECOND then
        state.ignored = state.ignored + 1
        deathLog("death not sent: one already went out a moment ago (" .. tostring(cause) .. ")")
        return false
    end

    state.sent = state.sent + 1
    state.lastSentAt = state.ticks

    local sent = false
    if _G.apNetSendDeath then
        local ok, result = pcall(_G.apNetSendDeath, cause)
        if not ok then
            deathLog("send failed: " .. tostring(result))
            return false
        end
        sent = result ~= false
        deathLog((sent and "death sent: " or "death not sent, the server refused it: ") .. tostring(cause))
    else
        deathLog("(offline) would have sent a death: " .. tostring(cause))
    end

    if _G.apNotifyStatus then
        _G.apNotifyStatus(apT(sent and "deathlink.sent" or "deathlink.not_sent"))
    end
    return sent
end

local SENT_CAUSES = {
    destroyed = "hull destroyed",
    crew = "crew wiped out",
}

function apDeathLinkOnRunEnd(cause, detail)
    local _, waiting = next(state.cloning)
    state.cloning = {}
    state.away = {}
    if cause == "victory" or cause == "menu" then
        return false
    end
    if waiting ~= nil and triggerCoversCrew() and not triggerCoversRunEnd() then
        return apDeathLinkCrewDied(waiting.name, waiting.species)
    end
    if not triggerCoversRunEnd() then
        deathLog("run end '" .. tostring(cause) .. "' ignored by trigger setting")
        return false
    end
    return apDeathLinkSend(SENT_CAUSES[cause] or "ship lost")
end

function apDeathLinkCrewDied(name, species)
    if not triggerCoversCrew() then
        return false
    end
    return apDeathLinkSend((species or "crew") .. " " .. (name or "crew member") .. " died")
end

-- Crew actually stationed on this ship (not a boarder on the enemy's), still alive.
local function aliveCrew(player)
    local alive = {}
    local crew = player.vCrewList
    for i = 0, crew:size() - 1 do
        local member = crew[i]
        if member ~= nil and member.iShipId == 0 and not member.bDead then
            alive[#alive + 1] = member
        end
    end
    return alive
end

local EFFECTS = {}

EFFECTS.major_incident = function(player)
    local candidates = {}
    local systems = player.vSystemList
    for i = 0, systems:size() - 1 do
        local system = systems[i]
        if system ~= nil and system.healthState.first > 0 then
            candidates[#candidates + 1] = system
        end
    end
    if #candidates == 0 then
        return nil
    end

    local target = candidates[math.random(1, #candidates)]
    local roomId = math.floor(target.roomId)
    local label = _G.apSystemLabel and _G.apSystemLabel(target.name) or tostring(target.name)

    local damage = Hyperspace.Damage()
    damage.iDamage = 0
    damage.breachChance = 100
    damage.fireChance = 100
    damage.bFriendlyFire = true
    damage.ownerId = 0
    pcall(function()
        player:DamageArea(player:GetRoomCenter(roomId), damage, true)
    end)

    pcall(function()
        player:StartFire(roomId)
    end)

    local amount = math.min(2, math.max(0, target.healthState.first - 1))
    if amount > 0 then
        pcall(function() target:AddDamage(amount) end)
    end

    return "deathlink.effect.major", { system = label }
end

EFFECTS.crew_member = function(player)
    local alive = aliveCrew(player)
    if #alive < 2 then
        return nil
    end
    local victim = alive[math.random(1, #alive)]
    local name = victim.GetName and victim:GetName() or apT("deathlink.crew.unnamed")
    victim:Kill(true)
    return "deathlink.effect.crew", { name = tostring(name) }
end

EFFECTS.hull_damage = function(player)
    local hull = player.ship.hullIntegrity
    local amount = math.min(3, hull.first - 1)
    if amount <= 0 then
        return nil
    end
    player:DamageHull(amount, true)
    return "deathlink.effect.hull", { n = amount }
end

EFFECTS.boarding = function(player)
    if #aliveCrew(player) < 2 then
        return nil
    end
    local room = _G.apRandomRoomId and _G.apRandomRoomId(player) or nil
    if room == nil then
        return nil
    end
    local ok = pcall(function()
        player:AddCrewMemberFromString("", "mantis", true, room, false, true)
    end)
    if not ok then
        return nil
    end
    return "deathlink.effect.boarding"
end

EFFECTS.fire = function(player)
    local room = _G.apRandomRoomId and _G.apRandomRoomId(player) or nil
    if room == nil then
        return nil
    end
    player:StartFire(room)
    return "deathlink.effect.fire"
end

local FALLBACK_ORDER = { "hull_damage", "fire", "crew_member" }

local function applyEffect(player, wanted)
    local order = { wanted }
    for _, name in ipairs(FALLBACK_ORDER) do
        if name ~= wanted then
            order[#order + 1] = name
        end
    end
    for _, name in ipairs(order) do
        local effect = EFFECTS[name]
        if effect ~= nil then
            local ok, key, params = pcall(effect, player)
            if ok and key ~= nil then
                return key, params
            end
        end
    end
    return nil
end

function apDeathLinkReceive(source, cause)
    local config = _G.apDeathLink
    if not config.enabled then
        return false
    end

    state.received = state.received + 1
    state.lastReceivedAt = state.ticks

    local world = Hyperspace.App.world
    local player = Hyperspace.ships.player
    if world == nil or not world.bStartedGame or player == nil or player.bDestroyed then
        deathLog("death received outside a run, ignored (" .. tostring(source) .. ")")
        return false
    end

    local wanted = config.effect
    if wanted == "varied" then
        local names = { "crew_member", "fire", "hull_damage", "boarding" }
        wanted = names[math.random(1, #names)]
    end

    state.applying = true
    local key, params = applyEffect(player, wanted)
    state.applying = false

    if key == nil then
        deathLog("no effect applicable for the death of " .. tostring(source))
        if _G.apNotifyTrap then
            (_G.apNotifyAlert or _G.apNotifyTrap)(apT("deathlink.fizzled"))
        end
        return false
    end

    deathLog(string.format("death received from %s (%s) -> %s", tostring(source), tostring(cause), key))
    if _G.apNotifyAlert then
        local who = (source and source ~= "") and source or apT("deathlink.someone")
        _G.apNotifyAlert(apT("deathlink.received",
                            { who = who, effect = apT(key, params) }))
    end
    return true
end

-- Repair and boarding drones walk the ship like crew: switched off or shot down, they are not a death.
local function isDrone(member)
    local ok, drone = pcall(function() return member:IsDrone() end)
    return ok and drone == true
end

-- Temporary crew (Multiverse holograms and projections, technician drones, weapon clones) vanish on their own:
-- a spawn with a lifetime gets a death timer, a hologram without one takes no crew slot. So do pets like the
-- gnome: none of them is a crew member lost.
local function isTemporary(member)
    local ok, temporary = pcall(function()
        local extend = member.extend
        return extend.deathTimer ~= nil or extend.noSlot == true
    end)
    return ok and temporary == true
end

-- Hyperspace gives each crew member an id that stays when the player renames them; the name is the fallback.
local function crewKey(member, name)
    local ok, id = pcall(function() return member.extend.selfId end)
    if ok and id ~= nil and id >= 0 then
        return "id" .. tostring(id)
    end
    return "name:" .. name
end

-- Our crew on both ships: the living, and those already marked dead.
local function livingCrew()
    local living, dead = {}, {}
    for _, ship in ipairs({ Hyperspace.ships.player, Hyperspace.ships.enemy }) do
        if ship ~= nil then
            local crew = ship.vCrewList
            for i = 0, crew:size() - 1 do
                local member = crew[i]
                if member ~= nil and member.iShipId == 0 and not isDrone(member) and not isTemporary(member) then
                    local name = tostring(member.GetName and member:GetName() or ("crew" .. i))
                    local key = crewKey(member, name)
                    local health = member.health and tonumber(member.health.first) or 1
                    if member.bDead then
                        dead[key] = health
                    else
                        living[key] = { name = name, species = member.species or "crew", health = health,
                                        onEnemy = member.currentShipId == 1 }
                    end
                end
            end
        end
    end
    return living, dead
end

local CLONE_BAY = 13

-- Dead crew the Clone Bay may bring back: those in its queue, and those just dead aboard, who only join the
-- queue on the next frame the game runs (not at all while it is paused).
local function cloneQueue(dead)
    local queued = {}
    pcall(function()
        if not Hyperspace.ships.player:HasSystem(CLONE_BAY) then
            return
        end
        for key in pairs(dead) do
            queued[key] = true
        end
        local list = Hyperspace.CrewFactory:GetCloneReadyList(true)
        for i = 0, list:size() - 1 do
            local member = list[i]
            queued[crewKey(member, tostring(member:GetName()))] = true
        end
    end)
    return queued
end

local CREW_SCREEN_SECONDS = 2

-- A crew member who dies lies a few seconds at zero health before FTL marks them dead. One dismissed from
-- the crew screen is marked dead at once, without that moment: the player's choice, not a death. An event
-- can also kill at once, so it only counts as dismissed with the crew screen just shown.
local function dismissed(key, dead)
    local crewScreenRecent = state.crewScreenAt ~= nil
        and state.ticks - state.crewScreenAt <= CREW_SCREEN_SECONDS * TICKS_PER_SECOND
    return crewScreenRecent and dead[key] ~= nil and dead[key] <= 0 and not state.dying[key]
end

-- Events take crew away without killing them (the Engi virus, a Multiverse crew member turned into another
-- race): they leave the list at once. A death shows first, marked dead or lying at zero health. Crew left on
-- the enemy ship die with it, or when we jump away, without that moment.
local function seenDying(key, last, dead)
    return dead[key] ~= nil or state.dying[key] == true or last.onEnemy == true
end

-- Crew teleporting are on neither ship for a moment. Leaving the enemy ship, that looks like dying there.
local AWAY_SECONDS = 4

local function maybeTeleporting(key, last, dead)
    return last.onEnemy == true and dead[key] == nil and state.dying[key] ~= true
end

local function crewLost(key, last, dead, queued)
    if queued[key] then
        deathLog(tostring(last.name) .. " waits for the Clone Bay")
        state.cloning[key] = last
    else
        apDeathLinkCrewDied(last.name, last.species)
    end
end

-- The hangar keeps bStartedGame on while you browse ships, and each ship shown comes with its own crew.
local function runInProgress()
    local ok, started = pcall(function()
        local app = Hyperspace.App
        return app.world.bStartedGame == true and app.menu.shipBuilder.bOpen ~= true
    end)
    return ok and started == true
end

local function sampleCrew()
    if not triggerCoversCrew() then
        state.knownCrew = nil
        return
    end

    if not runInProgress() then
        state.knownCrew = nil
        return
    end

    local ok, current, dead = pcall(livingCrew)
    if not ok then
        return
    end

    local queued = _G.apDeathLink.cloned and {} or cloneQueue(dead)
    for key, away in pairs(state.away) do
        if current[key] ~= nil then
            deathLog(tostring(away.last.name) .. " came back: no DeathLink")
            state.away[key] = nil
        elseif dead[key] ~= nil or state.ticks - away.since >= AWAY_SECONDS * TICKS_PER_SECOND then
            state.away[key] = nil
            crewLost(key, away.last, dead, queued)
        end
    end
    for key, last in pairs(state.cloning) do
        if current[key] ~= nil then
            deathLog(tostring(last.name) .. " came back from the Clone Bay: no DeathLink")
            state.cloning[key] = nil
        elseif not queued[key] then
            state.cloning[key] = nil
            apDeathLinkCrewDied(last.name, last.species)
        end
    end

    -- A run loaded with someone already in the Clone Bay: they are waited for like the others.
    if state.knownCrew == nil then
        pcall(function()
            local list = Hyperspace.CrewFactory:GetCloneReadyList(true)
            for i = 0, list:size() - 1 do
                local member = list[i]
                local name = tostring(member:GetName())
                local key = crewKey(member, name)
                if current[key] == nil then
                    state.cloning[key] = { name = name, species = member.species or "crew" }
                end
            end
        end)
    end

    if state.knownCrew ~= nil then
        for key, last in pairs(state.knownCrew) do
            if current[key] == nil then
                if dismissed(key, dead) then
                    deathLog(tostring(last.name) .. " was dismissed: no DeathLink")
                elseif not seenDying(key, last, dead) then
                    deathLog(tostring(last.name) .. " left the crew without dying (an event or a new race): no DeathLink")
                elseif maybeTeleporting(key, last, dead) then
                    deathLog(tostring(last.name) .. " left the enemy ship: a teleport, or lost with it?")
                    state.away[key] = { last = last, since = state.ticks }
                else
                    crewLost(key, last, dead, queued)
                end
                state.dying[key] = nil
            end
        end
    end
    for key, member in pairs(current) do
        state.dying[key] = member.health <= 0 or nil
    end
    state.knownCrew = current
end

local previousOnRunEnd = _G.apOnRunEnd
_G.apOnRunEnd = function(cause, detail)
    if previousOnRunEnd then
        apTry(TAG, previousOnRunEnd, cause, detail)
    end
    apTry(TAG, apDeathLinkOnRunEnd, cause, detail)
end

local sampleDivider = 0

script.on_internal_event(Defines.InternalEvents.ON_TICK, function()
    state.ticks = state.ticks + 1
    sampleDivider = (sampleDivider + 1) % 30
    if sampleDivider == 0 and _G.apDeathLink.enabled then
        sampleCrew()
    end
end)

if Defines.RenderEvents.TABBED_WINDOW ~= nil then
    script.on_render_event(Defines.RenderEvents.TABBED_WINDOW, function() end, function(tab)
        if tab == "crew" then
            state.crewScreenAt = state.ticks
        end
    end)
end

script.on_init(function()
    state.knownCrew = nil
    state.dying = {}
    state.cloning = {}
    state.away = {}
    state.crewScreenAt = nil
    state.lastSentAt = nil
    state.lastReceivedAt = nil
end)

function apDeathLinkStatus()
    local config = _G.apDeathLink
    deathLog(string.format("DeathLink %s | trigger=%s effect=%s grace=%ss",
        config.enabled and "active" or "inactive", config.trigger, config.effect,
        tostring(config.graceSeconds)))
    deathLog(string.format("  sent=%d received=%d ignored=%d%s",
        state.sent, state.received, state.ignored,
        inGracePeriod() and " (grace period active)" or ""))
end

deathLog("DeathLink module loaded (console: LUA apDeathLinkStatus())")

]=], "@deathlink.lua", "t", _ENV)
  if chunk == nil then
    print("SYNTAX ERROR in deathlink.lua: " .. tostring(err))
    _G.__syntaxErrors = (_G.__syntaxErrors or 0) + 1
  else
    local ok, runErr = pcall(chunk)
    if not ok then
      print("LOAD ERROR in deathlink.lua: " .. tostring(runErr))
      _G.__loadErrors = (_G.__loadErrors or 0) + 1
    end
  end
end

do
  local chunk, err = load([=[
local TAG = "[AP-traplink] "

local function trapLog(message)
    log(TAG .. message)
end

_G.apTrapLink = _G.apTrapLink or { enabled = false }

local state = {
    sent = 0,
    unsent = 0,
    received = 0,
    ignored = 0,
    -- Seconds since the last trap from another slot, nil when none came since connecting. Archipelago never says who
    -- is on the link: a trap that came in recently is the only sign someone still is.
    partnerAge = nil,
    -- FTL clients on the link, by slot: seconds since each one was last heard.
    partners = {},
}

local PARTNER_WINDOW = 600

_G.apTrapLinkState = state

local OUR_EFFECTS = { "fire", "breach", "fuel_leak", "system_damage", "fleet_advance", "hull_damage" }

local KEYWORDS = {
    { "oxygen", "o2_drain" },
    { "suffocat", "o2_drain" },
    { "vacuum", "o2_drain" },
    { "ice", "system_damage" },
    { "frost", "system_damage" },
    { "freeze", "system_damage" },
    { "cold", "system_damage" },
    { "breach", "breach" },
    { "leak", "fuel_leak" },
    { "fire", "fire" },
    { "burn", "fire" },
    { "flame", "fire" },
    { "fuel", "fuel_leak" },
    { "gas", "fuel_leak" },
    { "system", "system_damage" },
    { "jam", "system_damage" },
    { "stun", "system_damage" },
    { "paralys", "system_damage" },
    { "confus", "system_damage" },
    { "blind", "system_damage" },
    { "reverse", "system_damage" },
    { "damage", "hull_damage" },
    { "bomb", "hull_damage" },
    { "explos", "hull_damage" },
    { "hurt", "hull_damage" },
    { "poison", "hull_damage" },
    { "hull", "hull_damage" },
    { "chase", "fleet_advance" },
    { "timer", "fleet_advance" },
    { "speed", "fleet_advance" },
    { "slow", "fleet_advance" },
}

function apTrapLinkTranslate(trapName)
    local lowered = string.lower(tostring(trapName or ""))
    for _, entry in ipairs(KEYWORDS) do
        if lowered:find(entry[1], 1, true) then
            return entry[2], "keyword '" .. entry[1] .. "'"
        end
    end
    return OUR_EFFECTS[math.random(1, #OUR_EFFECTS)], "no keyword matched, random pick"
end

function apTrapLinkReceive(source, trapName)
    if not _G.apTrapLink.enabled then
        return false
    end
    state.received = state.received + 1
    state.partnerAge = 0

    local effect, why = apTrapLinkTranslate(trapName)
    trapLog(string.format("trap from %s: '%s' -> %s (%s)",
        tostring(source), tostring(trapName), effect, why))

    return apQueueItem({
        kind = "trap",
        eff = effect,
        display = apT("trap.from", { trap = tostring(trapName), slot = tostring(source or "?") }),
        fromLink = true,
    })
end

-- A trap the mod makes (a pact, the surge from another world) only goes out once a trap from another slot showed
-- someone else is on the link this session: alone on it, the trap would vanish, so it hits the player instead.
function apTrapLinkPartnerSeen()
    return _G.apTrapLink ~= nil and _G.apTrapLink.enabled == true and state.partnerAge ~= nil
end

-- Another FTL on TrapLink announced itself: a partner without waiting for a trap. A first announce gets an answer,
-- so the newcomer learns about us too.
function apTrapLinkPartner(source, isReply, slot)
    if not _G.apTrapLink.enabled then
        return false
    end
    if state.partnerAge == nil then
        trapLog("TrapLink partner: " .. tostring(source))
    end
    state.partnerAge = 0
    if tonumber(slot) ~= nil and tonumber(slot) > 0 then
        state.partners[math.floor(tonumber(slot))] = 0
    end
    if not isReply and _G.apNetAnnounceTrapLink then
        pcall(_G.apNetAnnounceTrapLink, true)
    end
    return true
end

-- Called on a disconnect: whoever was on the link may be gone by the time we are back.
function apTrapLinkForgetPartner()
    state.partnerAge = nil
    state.partners = {}
end

-- A pact or a surge lands on one player, not on the whole link: a random FTL client when one is known. Other games
-- can only be reached through the link itself, and each of them gets it.
function apTrapLinkSendToOne(name)
    if not apTrapLinkPartnerSeen() then
        return false
    end
    local slots = {}
    for slot in pairs(state.partners) do
        slots[#slots + 1] = slot
    end
    if #slots > 0 and _G.apNetSendTrapTo then
        table.sort(slots)
        local slot = slots[math.random(1, #slots)]
        local ok, result = pcall(_G.apNetSendTrapTo, slot, name)
        if ok and result ~= nil then
            trapLog(string.format("'%s' sent to slot %d alone", tostring(name), slot))
            return result ~= false
        end
    end
    local ok, result = pcall(_G.apNetSendTrap, name)
    return ok and result ~= false
end

function apTrapLinkAgePartner(seconds)
    for slot, age in pairs(state.partners) do
        state.partners[slot] = age + seconds <= PARTNER_WINDOW and age + seconds or nil
    end
    if state.partnerAge == nil then
        return
    end
    state.partnerAge = state.partnerAge + seconds
    if state.partnerAge > PARTNER_WINDOW then
        state.partnerAge = nil
        trapLog("no trap from another slot for " .. PARTNER_WINDOW .. " s: no partner assumed any more")
    end
end

-- Every five minutes, a reminder to the other FTLs on the link: they keep counting us inside their window.
local REMIND_EVERY = 300
local sinceReminder = 0

script.on_internal_event(Defines.InternalEvents.ON_TICK, function()
    local ok, factor = pcall(function() return Hyperspace.FPS.SpeedFactor end)
    factor = ok and tonumber(factor) or nil
    local seconds = (factor ~= nil and factor > 0) and math.min(factor * 0.0625, 0.25) or 1 / 60
    apTrapLinkAgePartner(seconds)
    sinceReminder = sinceReminder + seconds
    if sinceReminder >= REMIND_EVERY then
        sinceReminder = 0
        if _G.apTrapLink.enabled and _G.apNetAnnounceTrapLink then
            pcall(_G.apNetAnnounceTrapLink, true)
        end
    end
end)

function apTrapLinkOnTrap(descriptor)
    if not _G.apTrapLink.enabled then
        return false
    end
    if descriptor.fromLink then
        state.ignored = state.ignored + 1
        return false
    end

    local name = descriptor.display or descriptor.eff

    local sent = false
    if _G.apNetSendTrap then
        local ok, result = pcall(_G.apNetSendTrap, name)
        if not ok then
            trapLog("broadcast failed: " .. tostring(result))
            return false
        end
        sent = result ~= false
    end

    if sent then
        state.sent = state.sent + 1
    else
        state.unsent = (state.unsent or 0) + 1
        trapLog("(offline) the trap was not broadcast to anyone: " .. tostring(name))
    end
    return sent
end

function apTrapLinkStatus()
    trapLog("TrapLink " .. (_G.apTrapLink.enabled and "active" or "inactive")
        .. string.format(" | sent=%d unsent=%d received=%d ignored=%d",
            state.sent, state.unsent or 0, state.received, state.ignored))
end

trapLog("TrapLink module loaded (console: LUA apTrapLinkStatus())")

