do
  local chunk, err = load([=[
local TAG = "[AP-events] "

local function eventLog(message)
    log(TAG .. message)
end

_G.apEventLog = {}

-- event_beacons: which Archipelago events say ARCHIPELAGO on the map. The AP STORE beacons always do. "important"
-- keeps the label on the events that carry a package (the relay and the pirates); the tolls, the Slug's hints and
-- the surge from another world then look like any beacon. Seeds from before the option keep every label.
local IMPORTANT_EVENTS = { "AP_EVT_PACKAGE", "AP_EVT_HIJACK", "AP_HIJACK_YIELD", "AP_HIJACK_WON", "AP_HIJACK_DEADCREW" }
local OTHER_EVENTS = {
    "AP_EVT_ZOLTAN_TITHE", "AP_EVT_ZOLTAN_TITHE_LINK", "AP_EVT_ZOLTAN_TOLL", "AP_EVT_SLUG_WHISPER",
    "AP_EVT_ANOTHER_WORLD", "AP_EVT_ANOTHER_WORLD_LINK", "AP_EVT_ANOTHER_WORLD_PLAIN",
    "AP_EVT_OVERCLOCK", "AP_EVT_ARMS_DEALER",
}

local beaconsMode = "marked"
local sectorEventShown = nil

function apApplyEventBeacons(mode)
    mode = mode or "marked"
    beaconsMode = mode
    sectorEventShown = nil
    if _G.apNetHideBeaconLabel == nil then return end
    for _, name in ipairs(IMPORTANT_EVENTS) do apNetHideBeaconLabel(name, mode == "hidden") end
    for _, name in ipairs(OTHER_EVENTS) do apNetHideBeaconLabel(name, mode ~= "marked") end
    eventLog("event beacons: " .. mode)
end

local function record(name, detail)
    _G.apEventLog[#_G.apEventLog + 1] = { event = name, detail = detail }
    eventLog(name .. " : " .. detail)
end

local function feedTheLink(eventName, fuel)
    if _G.apEnergyLinkDeposit == nil then
        record(eventName, "energy link missing, nothing deposited")
        return
    end
    local joules = fuel * (_G.apEnergyLinkJoulesPerFuel or 1000000)
    local ok, deposited = pcall(_G.apEnergyLinkDeposit, joules, true)
    local sent = ok and tonumber(deposited) ~= nil and tonumber(deposited) > 0
    record(eventName, sent and ("deposited to the link: " .. joules .. " J") or "nothing deposited to the link")
    if sent and _G.apNotifyStatus then
        _G.apNotifyStatus(apT("event.link.fed"))
    end
end

local function drainTheLink(eventName)
    if _G.apEnergyLinkRequestFuel == nil then
        record(eventName, "energy link missing, nothing drawn")
        return
    end
    -- The answer comes later, through apEnergyLinkGranted.
    local ok, asked = pcall(_G.apEnergyLinkRequestFuel, 5)
    if not ok or asked ~= true then
        record(eventName, "no request possible, the shared pool is out of reach")
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("event.link.empty"))
        end
        return
    end
    record(eventName, "5 fuel units asked from the link")
end

local function sendTrapOutward(eventName)
    local sent = _G.apTrapLinkSendToOne ~= nil and apTrapLinkSendToOne("Archipelago Signal Surge")
    if sent then
        record(eventName, "trap sent to another player")
    else
        -- No one seen on the link: the surge comes back, like a pact.
        local effects = { "fire", "breach", "fuel_leak", "system_damage", "hull_damage" }
        local effect = effects[math.random(1, #effects)]
        record(eventName, "no one out there to receive it, the trap hits us (" .. effect .. ")")
        if _G.apQueueItem then
            _G.apQueueItem({ kind = "trap", eff = effect, display = apT("event.trap.own"), fromLink = true })
        end
    end
    if _G.apNotifyStatus then
        _G.apNotifyStatus(apT(sent and "event.trap.sent" or "event.trap.nobody"))
    end
end


local offeredPackages = { a = nil, b = nil }
local PRICE = { ["AP_EVT_PACKAGE"] = 15, ["AP_EVT_SLUG_WHISPER"] = 20, ["AP_EVT_HIJACK"] = 20 }
local scrapBefore = {}

local function scrap()
    local ok, value = pcall(function() return Hyperspace.ships.player.currentScrap end)
    return ok and tonumber(value) or nil
end

local function refund(eventName)
    local before = scrapBefore[eventName]
    scrapBefore[eventName] = nil
    if before == nil then
        return 0
    end
    local refunded = math.min(PRICE[eventName] or 0, math.max(0, math.floor(before)))
    if refunded > 0 then
        pcall(function() Hyperspace.ships.player:ModifyScrapCount(refunded, false) end)
    end
    return refunded
end

local function buyHint(eventName)
    if _G.apHintPurchase and _G.apHintPurchase() then
        scrapBefore["AP_EVT_SLUG_WHISPER"] = nil
        record(eventName, _G.apSoloEnabled and "hint given from the solo seed" or "hint requested from server")
        if _G.apNotifyStatus and not _G.apSoloEnabled then
            _G.apNotifyStatus(apT("event.hint.asked"))
        end
        return
    end
    local refunded = refund("AP_EVT_SLUG_WHISPER")
    record(eventName, "no hint possible, " .. refunded .. " scrap refunded")
    if _G.apNotifyStatus then
        _G.apNotifyStatus(apT("event.hint.nothing", { scrap = refunded }))
    end
end

-- event_checks: the events' own checks ("event:1"...) hand out their packages before the Archipelago shop's.
local MAX_EVENT_CHECKS = 20

local function eventPackages(count)
    local found = {}
    if not (_G.apLocationNameFor and _G.apCheckAlreadySent) then
        return found
    end
    for n = 1, MAX_EVENT_CHECKS do
        local key = "event:" .. n
        if apLocationNameFor(key) ~= nil and not apCheckAlreadySent(key) then
            local scouted = (_G.apNetScoutedItem and apNetScoutedItem(key)) or {}
            found[#found + 1] = { location = key, event = true, item = scouted.item or apT("gift.something"),
                                  slot = scouted.slot or apT("gift.someone"), kind = scouted.kind,
                                  mine = scouted.mine == true }
            if #found >= count then
                break
            end
        end
    end
    return found
end

local function peekPackages(count)
    local packages = eventPackages(count)
    if #packages < count and _G.apShopGiftPeekMany then
        for _, package in ipairs(apShopGiftPeekMany(count - #packages) or {}) do
            packages[#packages + 1] = package
        end
    end
    return packages
end

local function giveEventPackage(package)
    if not (_G.apSendCheck and apSendCheck(package.location, apLocationNameFor(package.location))) then
        return nil
    end
    return package
end

local function givePackage(package)
    if package ~= nil and package.event then
        local sent = giveEventPackage(package)
        if sent ~= nil then
            return sent
        end
    end
    local first = eventPackages(1)[1]
    if (package == nil or package.event) and first ~= nil then
        local sent = giveEventPackage(first)
        if sent ~= nil then
            return sent
        end
    end
    local sent = nil
    if package ~= nil and not package.event and _G.apShopGiftGiveAt ~= nil then
        sent = _G.apShopGiftGiveAt(package.location)
    end
    if sent == nil and _G.apShopGiftGiveNext ~= nil then
        sent = _G.apShopGiftGiveNext()
    end
    return sent
end

local function announceSent(eventName, sent)
    record(eventName, "package routed: " .. tostring(sent.item) .. " -> "
        .. (sent.mine and "the player" or tostring(sent.slot)))
    if _G.apNotifyStatus and not sent.mine then
        _G.apNotifyStatus(apT("event.gift.sent",
            { item = tostring(sent.item), slot = tostring(sent.slot) }))
    end
end

function routePackage(eventName, package, priceEvent)
    priceEvent = priceEvent or "AP_EVT_PACKAGE"
    local sent = givePackage(package)
    if sent == nil then
        local refunded = refund(priceEvent)
        record(eventName, "nothing to send, " .. refunded .. " scrap refunded")
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("event.gift.nothing", { scrap = refunded }))
        end
        return
    end
    scrapBefore[priceEvent] = nil
    announceSent(eventName, sent)
end

-- The pirates' package: preferably one for another player, since freeing it is the point. Won in a fight, it
-- goes out for free; with no package left, the fight only gives its usual reward.
local hijacked = nil

local function pickHijacked()
    local packages = peekPackages(3)
    for _, package in ipairs(packages) do
        if not package.mine then
            return package
        end
    end
    return packages[1]
end

local HIJACK_HINTS = {
    progression = "event.hijack.hint.progression", useful = "event.hijack.hint.useful",
    filler = "event.hijack.hint.filler", trap = "event.hijack.hint.trap",
}

local function writeHijackText(event)
    hijacked = pickHijacked()
    if hijacked == nil then
        return
    end
    local key = hijacked.mine and "event.hijack.self" or "event.hijack.text"
    local text = apT(key, { slot = tostring(hijacked.slot), item = tostring(hijacked.item) })
    -- A vague word on what the package is worth, so a player can walk away from a trap.
    if HIJACK_HINTS[hijacked.kind] then
        text = text .. " " .. apT(HIJACK_HINTS[hijacked.kind])
    end
    event.text.data = text
    event.text.isLiteral = true
end

local function freeHijacked(eventName)
    local sent = givePackage(hijacked)
    hijacked = nil
    if sent == nil then
        record(eventName, "fight won, no package left to free")
        return
    end
    announceSent(eventName, sent)
end

local function writePackageChoices(event)
    offeredPackages.a, offeredPackages.b = nil, nil
    local packages = peekPackages(2)
    if packages[1] == nil then
        return
    end
    local choices = event:GetChoices()
    if choices == nil or choices:size() < 2 then
        return
    end

    local function setChoice(index, chosenPackage)
        if chosenPackage.mine then
            choices[index].text.data = apT("event.package.self", { item = tostring(chosenPackage.item) })
        else
            choices[index].text.data = apT("event.package.route",
                { slot = tostring(chosenPackage.slot), item = tostring(chosenPackage.item) })
        end
        choices[index].text.isLiteral = true
    end

    offeredPackages.a = packages[1]
    setChoice(0, packages[1])
    if packages[2] ~= nil then
        offeredPackages.b = packages[2]
        setChoice(1, packages[2])
    else
        -- Only one package waiting: the second answer ships it too, so it says so instead of "the second one".
        setChoice(1, packages[1])
    end
end

local BRANCH_EFFECTS = {
    AP_EVT_ZOLTAN_TITHE_A = function(name) feedTheLink(name, 1) end,
    AP_EVT_ZOLTAN_TITHE_B = function(name) drainTheLink(name) end,
    AP_EVT_PACKAGE_A = function(name) routePackage(name, offeredPackages.a) end,
    AP_EVT_PACKAGE_B = function(name) routePackage(name, offeredPackages.b) end,
    AP_EVT_SLUG_WHISPER_A = function(name) buyHint(name) end,
    AP_EVT_ANOTHER_WORLD_B = function(name) sendTrapOutward(name) end,
    AP_EVT_HIJACK_B = function(name)
        local package = hijacked
        hijacked = nil
        routePackage(name, package, "AP_EVT_HIJACK")
    end,
    AP_HIJACK_WON = function(name) freeHijacked(name) end,
    AP_HIJACK_DEADCREW = function(name) freeHijacked(name) end,
    AP_HIJACK_YIELD = function(name) freeHijacked(name) end,
}

_G.apEventBranchEffects = BRANCH_EFFECTS

for branch, effect in pairs(BRANCH_EFFECTS) do
