local TAG = "[AP-contract] "

local function contractLog(message)
    log(TAG .. message)
end

local AP_CONTRACT_MIN = 1
local AP_CONTRACT_MAX = 3

_G.apContractRange = { min = AP_CONTRACT_MIN, max = AP_CONTRACT_MAX }

local state = {
    connected = false,
    contract = nil,
    refusal = nil,
    unknownItems = 0,
    unknownKinds = {},
    itemDescriptors = {},
}

_G.apContractState = state

local function missingKinds(kinds)
    local missing = {}
    for _, kind in ipairs(kinds or {}) do
        if not (_G.apSupportedKinds or {})[kind] then
            missing[#missing + 1] = kind
        end
    end
    return missing
end

local function refuse(reason)
    state.refusal = reason
    state.connected = false
    contractLog("SEED REFUSED: " .. reason)
    state.refusalToast = apT("contract.refused", { reason = reason })
    if _G.apNotifyStatus then
        _G.apNotifyStatus(state.refusalToast)
    end
    return false
end

local function seedsDifferent(before, after)
    if before == nil then
        return false
    end
    if before.hash ~= nil and after.hash ~= nil and before.hash ~= after.hash then
        return true
    end
    if before.slot ~= nil and after.slot ~= nil and before.slot ~= after.slot then
        return true
    end
    return false
end

local function seedIdentity(slotData, slotName)
    local hash = slotData.seed_hash or slotData.seed_name
    local slot = slotName
    if slot == "" then slot = nil end
    return { hash = hash and tostring(hash) or nil, slot = slot and tostring(slot) or nil }
end

function apApplySlotData(slotData, slotName, solo)
    if type(slotData) ~= "table" then
        return refuse(apT("contract.reason.nodata"))
    end

    local identity = seedIdentity(slotData, slotName)

    local onServer = _G.apNetConnected and _G.apNetConnected()
    if onServer or solo then
        local stored = _G.apNetSeedTag and _G.apNetSeedTag() or 0
        local incoming = apSeedFingerprint(identity)
        contractLog(string.format("seed fingerprint: stored %d, incoming %d, hash %s",
            stored, incoming, tostring(identity.hash)))
        -- With save profiles, a save that already belongs to a seed asks on any other seed, progress or not:
        -- the answer gives that seed its own save. Without them, only a profile with ships has something to lose.
        local bound = _G.apSavesSupported ~= nil and apSavesSupported() and stored ~= 0
        -- Two slots of one seed share its fingerprint, but not their progress: each has its own save.
        local otherSlot = incoming == stored and _G.apSavesOtherSlot ~= nil and apSavesOtherSlot(identity.slot)
        if otherSlot or (incoming ~= stored
            and (bound or (_G.apProfileHasShips and _G.apProfileHasShips()))) then
            state.seedChangedWithUnlocks = true
            state.seedChangeReason = stored == 0 and "foreign" or "seedchange"
            state.refusedFingerprint = incoming
            state.refusedSlot = identity.slot
            if onServer and _G.apNetDisconnect then pcall(_G.apNetDisconnect) end
            if state.seedChangeReason == "foreign" then
                return refuse(apT("contract.reason.foreign"))
            end
            return refuse(apT("contract.reason.seedchange"))
        end
    end

    -- After a disconnect the seed is unloaded, but its items are still in memory: compare with it too.
    local before = state.identity or state.lastIdentity
    if seedsDifferent(before, identity) then
        contractLog(string.format("seed change: %s/%s -> %s/%s",
            tostring(before.hash), tostring(before.slot),
            tostring(identity.hash), tostring(identity.slot)))
        -- On a server or in solo the fingerprint check above already asked the player; asking again after
        -- they answered would put the same question back up.
        local slotChanged = before.slot ~= nil and identity.slot ~= nil
            and before.slot ~= identity.slot
        if not (onServer or solo) or slotChanged then
            state.seedChangedWithUnlocks = #((_G.apInventory or {}).ships or {}) > 0
                or (_G.apCheckCount and (_G.apCheckCount().sent or 0) > 0) or false
        end

        if _G.apChecksForgetSeed then pcall(_G.apChecksForgetSeed) end
        if _G.apInventoryClear then pcall(_G.apInventoryClear) end
        if _G.apFillerForgetSeed then pcall(_G.apFillerForgetSeed) end
        if _G.apShopGiftsForgetSeed then pcall(_G.apShopGiftsForgetSeed) end
        if _G.apShopForgetSeed then pcall(_G.apShopForgetSeed) end
        if _G.apHintsForgetSeed then pcall(_G.apHintsForgetSeed) end

    end
    state.identity = {
        hash = identity.hash or (state.identity and state.identity.hash) or nil,
        slot = identity.slot or (state.identity and state.identity.slot) or nil,
    }

    local earlierRefusal = state.refusalToast
    state.refusal = nil
    state.refusalToast = nil
    state.unknownItems = 0
    state.unknownKinds = {}

    if _G.apLangResolve then
        apLangResolve(slotData.language)
    end

    local contract = slotData.contract
    if type(contract) ~= "number" then
        return refuse(apT("contract.reason.nonumber"))
    end
    state.contract = contract
    if contract > AP_CONTRACT_MAX then
        return refuse(apT("contract.reason.toonew",
            { seed = contract, mod = AP_CONTRACT_MAX }))
    end
    if contract < AP_CONTRACT_MIN then
        return refuse(apT("contract.reason.tooold",
            { seed = contract, mod = AP_CONTRACT_MIN }))
    end

    for _, field in ipairs({ "kinds", "kinds_required", "items", "loc", "caps", "goal", "shop",
                             "links", "options" }) do
        local value = slotData[field]
        if value ~= nil and type(value) ~= "table" then
            return refuse(apT("contract.reason.malformed", { field = field }))
        end
    end

    local required = missingKinds(slotData.kinds_required)
    if #required > 0 then
        return refuse(apT("contract.reason.kinds", { list = table.concat(required, ", ") }))
    end
    local optional = missingKinds(slotData.kinds)
    if #optional > 0 then
        contractLog("WARNING: kind(s) not implemented, their items will have no effect: "
            .. table.concat(optional, ", "))
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("contract.partial", { list = table.concat(optional, ", ") }))
        end
    end

    state.goal = slotData.goal
    state.startShip = slotData.start_ship
    if _G.apApplyEventBeacons then apApplyEventBeacons(slotData.event_beacons) end
    if _G.apCrewNamesConfigure then apCrewNamesConfigure(slotData.crew_names, slotData.players) end
    state.layouts = nil
    if type(slotData.layouts) == "table" then
        state.layouts = {}
        for _, blueprint in ipairs(slotData.layouts) do
            state.layouts[blueprint] = true
        end
    end
    state.seedName = slotData.seed_name
    state.options = slotData.options or {}
    if _G.apApplySectorEvent then apApplySectorEvent() end
    state.logic = type(slotData.logic) == "table" and slotData.logic or nil
    state.kestrelLocked = slotData.kestrel_locked == true
    state.receivedByIndex = {}

    state.itemDescriptors = slotData.items or {}
    state.capTotals = slotData.caps or {}
    state.systemCapsActive = slotData.system_caps ~= false
    state.blueprintsActive = slotData.system_blueprints ~= false
    state.locNames = slotData.loc or {}
    state.locKeys = {}
    for key, name in pairs(state.locNames) do
        state.locKeys[name] = key
    end


    local failed = {}
    local function configure(name, fn, arg)
        local ok, err = pcall(fn, arg)
        if not ok then
            failed[#failed + 1] = name
            contractLog("CONFIGURATION FAILED (" .. name .. "): " .. tostring(err))
        end
        return ok
    end

    if slotData.shop and _G.apShopConfigure then
        configure("shop", _G.apShopConfigure, slotData.shop)
        if type(slotData.shop.slots) == "number" then
            _G.apShopSlotCount = math.floor(slotData.shop.slots)
        end
    end
    -- Solo has no one to share with, and a link the seed does not mention must not stay on from the last seed.
    local links = solo and {} or (slotData.links or {})
    local off = { enabled = false }
    if _G.apDeathLinkConfigure then
        local death = { cloned = false }
        for key, value in pairs(links.death or off) do
            death[key] = value
        end
        configure("DeathLink", _G.apDeathLinkConfigure, death)
    end
    if _G.apEnergyLinkConfigure then
        configure("EnergyLink", _G.apEnergyLinkConfigure, links.energy or off)
    end
    _G.apTrapLink = _G.apTrapLink or {}
    _G.apTrapLink.enabled = links.trap ~= nil and links.trap.enabled == true

    local descriptorCount = 0
    for _ in pairs(state.itemDescriptors) do
        descriptorCount = descriptorCount + 1
    end

    state.connected = true
    contractLog(string.format("seed accepted: contract %d, %d item descriptor(s)",
        contract, descriptorCount))
    if earlierRefusal ~= nil and _G.apNotifyWithdraw then
        _G.apNotifyWithdraw(earlierRefusal)
    end
    state.refusal = nil
    if not solo and _G.apSoloLeave then
        _G.apSoloLeave()
    end

    if #failed > 0 then
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("contract.partial", { list = table.concat(failed, ", ") }))
        end
    end
    return true
end

-- Its Archipelago class, for the journal's colours. A seed made before 0.5 does not say: guessed from the kind.
local GUESSED_CLASS = { trap = "t", filler = "f", ship = "p", cap = "p", archive = "p" }
local function itemClass(descriptor)
    if descriptor.c == "p" or descriptor.c == "u" or descriptor.c == "t" or descriptor.c == "f" then
        return descriptor.c
    end
    return GUESSED_CLASS[descriptor.k] or "u"
end

local function announceLostItem(itemName)
    if _G.apNotifyStatus then
        _G.apNotifyStatus(apT("item.unknown", { name = tostring(itemName) }))
    end
end

-- The "in logic" marker (seeds from 0.6 on): a light copy of the logic, what each layout needs and how many
-- system blueprints each check needs, against the items received so far. Power and system needs are left out.
local function receivedCounts()
    local counts = {}
    for _, name in pairs(state.receivedByIndex or {}) do
        counts[name] = (counts[name] or 0) + 1
    end
    -- Progressive Unlocks the System: a Progressive item held counts as its blueprint, once.
    local credited = {}
    for source, blueprint in pairs(((state.logic or {}).unlocks) or {}) do
        if (counts[source] or 0) > 0 and not credited[blueprint] then
            credited[blueprint] = true
            counts[blueprint] = (counts[blueprint] or 0) + 1
        end
    end
    return counts
end

local function hasAll(counts, names)
    local wanted = {}
    for _, name in ipairs(names or {}) do
        wanted[name] = (wanted[name] or 0) + 1
    end
    for name, count in pairs(wanted) do
        if (counts[name] or 0) < count then
            return false
        end
    end
    return true
end

function apInLogic(checkKey)
    local logic = state.logic
    if logic == nil or logic.checks == nil then
        return nil
    end
    local entry = logic.checks[checkKey]
    if entry == nil then
        return nil
    end
    local counts = receivedCounts()
    local have = 0
    for _, name in ipairs(logic.blueprint_items or {}) do
        have = have + (counts[name] or 0)
    end
    if have < (entry.bp or 0) then
        return false
    end
    -- With shop_per_ship, a deep shop slot is only sold aboard its owner: only the owner's passes open it.
    -- Seeds made before this fix list every layout, so the owner is worked out here.
    local owner, perClass
    local slot = tonumber(tostring(checkKey):match("^shop:(%d+)$"))
    local config = _G.apShopConfig or {}
    if slot ~= nil and (entry.pass or 0) > 0 and config.owners ~= nil then
        owner = config.owners[math.floor((slot - 1) / (config.sectors or 1)) % #config.owners + 1]
        perClass = config.per == "per_class"
    end
    -- One layout of the seed, received, past the sectors this check asks, with the systems it needs.
    for _, way in ipairs(entry.ways or {}) do
        local passName = (logic.passes or {})[way.l]
        local needs = (logic.layouts or {})[way.l]
        local aboard = owner == nil or way.l == owner or (perClass and way.l:gsub("_[23]$", "") == owner)
        if needs ~= nil and aboard and hasAll(counts, needs) and hasAll(counts, way.i)
            and ((entry.pass or 0) == 0 or (passName ~= nil and (counts[passName] or 0) >= entry.pass)) then
            return true
        end
    end
    return false
end

function apNoteReceived(itemName, index)
    if index ~= nil and index >= 0 and state.receivedByIndex ~= nil then
        state.receivedByIndex[index] = tostring(itemName)
    end
end

function apReceiveItem(itemName, sender, isReplay, index)
    apNoteReceived(itemName, index)
    -- A refused seed still sends its items; they come again once it is accepted.
    if state.refusal ~= nil then
        contractLog("item ignored, the seed is refused: " .. tostring(itemName))
        return false
    end
    local descriptor = state.itemDescriptors[itemName]
    if descriptor == nil then
        state.unknownItems = state.unknownItems + 1
        contractLog("item received without descriptor: " .. tostring(itemName))
        announceLostItem(itemName)
        return false
    end

    local kind = descriptor.k
    if not (_G.apSupportedKinds or {})[kind] then
        state.unknownKinds[kind] = (state.unknownKinds[kind] or 0) + 1
        contractLog("kind not implemented: " .. tostring(kind) .. " (item " .. tostring(itemName) .. ")")
        announceLostItem(itemName)
        return false
    end

    if _G.apQueueItem == nil then
        contractLog("delivery queue unavailable, item ignored: " .. tostring(itemName))
        return false
    end

    if not isReplay and _G.apRecordReceived then
        apRecordReceived(itemName, sender, index, itemClass(descriptor))
    end

    -- A bundle is several shop items at once; it counts as received once its last one is through.
    if kind == "bundle" then
        local blueprints = descriptor.bps or {}
        local names = descriptor.names or {}
        for position, blueprint in ipairs(blueprints) do
            apQueueItem({
                kind = "shop",
                bp = blueprint,
                display = names[position] or blueprint,
                sender = sender,
                isReplay = isReplay == true,
                index = position == #blueprints and index or nil,
            })
        end
        return #blueprints > 0
    end

    return apQueueItem({
        -- A layout that needs no key is received like any ship: apShipReceived knows the seed is independent.
        -- A progressive ship key is a ship too: "bps" says which layout each copy gives.
        kind = (kind == "layout" or kind == "progressive_ship") and "ship" or kind,
        bp = descriptor.bp,
        bps = kind == "progressive_ship" and descriptor.bps or nil,
        sys = descriptor.sys,
        ship = descriptor.ship,
        res = descriptor.res,
        eff = descriptor.eff,
        race = descriptor.race,
        skill = descriptor.skill,
        tiers = descriptor.tiers,
        n = descriptor.n or 1,
        ub = descriptor.ub == true or nil,
        display = itemName,
        sender = sender,
        isReplay = isReplay == true,
        index = index,
    })
end

local function copy(value)
    if type(value) ~= "table" then
        return value
    end
    local result = {}
    for key, inner in pairs(value) do
        result[key] = copy(inner)
    end
    return result
end

local SEED_GLOBALS = { "apInventory", "apDeathLink", "apEnergyLink", "apTrapLink" }

function apRunIsolated(fn)
    local before = {}
    for _, name in ipairs(SEED_GLOBALS) do
        before[name] = copy(_G[name])
    end
    local ok, err = pcall(fn)
    for _, name in ipairs(SEED_GLOBALS) do
        local current = _G[name]
        if type(current) == "table" and type(before[name]) == "table" then
            for key in pairs(current) do
                current[key] = nil
            end
            for key, value in pairs(before[name]) do
                current[key] = copy(value)
            end
        else
            _G[name] = copy(before[name])
        end
    end
    apContractResetForTesting()
    return ok, err
end

function apSeedFingerprint(identity)
    local hash = tostring((identity or state.identity or {}).hash or "")
    local fingerprint = 0
    for index = 1, #hash do
        fingerprint = (fingerprint * 31 + hash:byte(index)) % 2147483647
    end
    return fingerprint
end

function apGoal()
    return state.goal
end

function apSeedOption(name)
    return (state.options or {})[name]
end

-- Older seeds do not list their layouts: all of them are in.
function apLayoutInSeed(blueprint)
    return state.layouts == nil or state.layouts[blueprint] == true
end

function apSeedKestrelLocked()
    return state.kestrelLocked == true
end

function apSeedStartShip()
    return state.startShip
end

-- With layout_unlocks: items the seed has a Type B or C among its items; with vanilla it has none, and
-- FTL unlocks them itself. Read from the items so older seeds, which do not send that option, work too.
-- With independent, those items come as "layout": a Type B or C then needs no key.
local layoutItemsFor, layoutItems, layoutsIndependent = nil, false, false

local function readLayoutItems()
    local descriptors = state.itemDescriptors or {}
    if layoutItemsFor == descriptors then
        return
    end
    layoutItemsFor, layoutItems, layoutsIndependent = descriptors, false, false
    for _, descriptor in pairs(descriptors) do
        if type(descriptor) == "table" and descriptor.k == "progressive_ship" then
            layoutItems = true
        elseif type(descriptor) == "table" and type(descriptor.bp) == "string" and descriptor.bp:match("_[23]$") then
            if descriptor.k == "layout" then
                layoutItems, layoutsIndependent = true, true
            elseif descriptor.k == "ship" then
                layoutItems = true
            end
        end
    end
end

function apSeedHasLayoutItems()
    readLayoutItems()
    return layoutItems
end

function apSeedLayoutsIndependent()
    readLayoutItems()
    return layoutsIndependent
end

function apSeedChangeLeftovers()
    return state.seedChangedWithUnlocks == true
end

function apSeedChangeAcknowledged()
    state.seedChangedWithUnlocks = false
end

function apSeedChangeReason()
    return state.seedChangeReason or "seedchange"
end

function apSeedChangeFingerprint()
    return state.refusedFingerprint
end

function apSeedChangeSlot()
    return state.refusedSlot
end

function apOwnSlotName()
    return (state.identity or {}).slot
end

function apSlotNumber(slot)
    local number = 0
    slot = tostring(slot)
    for index = 1, #slot do
        number = (number * 31 + slot:byte(index)) % 2147483647
    end
    return number
end

-- Two slots of one seed share its fingerprint, not their progress: what is kept per seed is kept per slot too.
function apSlotSuffix()
    local slot = apOwnSlotName()
    if slot == nil or slot == "" then
        return ""
    end
    return "_" .. tostring(apSlotNumber(slot))
end

function apSeedLoaded()
    return state.connected == true
end

function apSeedSummary()
    if not state.connected then
        return nil
    end
    return {
        ship = state.startShip,
        name = state.seedName,
        goal = state.goal,
        options = state.options or {},
        links = {
            death = _G.apDeathLink and _G.apDeathLink.offered or false,
            energy = _G.apEnergyLink and _G.apEnergyLink.enabled or false,
            trap = _G.apTrapLink and _G.apTrapLink.enabled or false,
        },
    }
end

function apLocationNameFor(checkKey)
    return (state.locNames or {})[checkKey]
end

function apSystemCapsActive()
    return state.systemCapsActive ~= false
end

function apSystemBlueprintsActive()
    return state.blueprintsActive ~= false
end

function apSystemCapTotal(system)
    return (state.capTotals or {})[system]
end

function apSeedKnowsLocations()
    return next(state.locNames or {}) ~= nil
end

function apCheckKeyFor(locationName)
    return (state.locKeys or {})[locationName] or locationName
end

function apContractResetForTesting()
    state.connected = false
    state.contract = nil
    state.refusal = nil
    state.unknownItems = 0
    state.unknownKinds = {}
    state.itemDescriptors = {}
    state.capTotals = {}
    state.locNames = {}
    state.locKeys = {}
    state.goal = nil
    state.layouts = nil
    state.layoutList = nil
    state.startShip = nil
    state.seedName = nil
    state.options = {}
    state.logic = nil
    state.kestrelLocked = false
    state.receivedByIndex = {}
    state.identity = nil
    state.lastIdentity = nil
    state.systemCapsActive = true
    state.blueprintsActive = true
end

function apContractUnload()
    if _G.apApplyEventBeacons then apApplyEventBeacons("marked") end
    local identity = state.identity or state.lastIdentity
    apContractResetForTesting()
    state.lastIdentity = identity
    contractLog("seed unloaded")
end

function apContractStatus()
    if state.refusal then
        contractLog("seed REFUSED: " .. state.refusal)
        return
    end
    if not state.connected then
        contractLog("no seed applied (offline)")
        return
    end
    contractLog("contract " .. tostring(state.contract) .. ", seed accepted")
    if state.unknownItems > 0 then
        contractLog("  " .. state.unknownItems .. " item(s) received without descriptor")
    end
    for kind, count in pairs(state.unknownKinds) do
        contractLog("  kind not implemented \"" .. kind .. "\": " .. count .. " item(s) with no effect")
    end
end

script.on_internal_event(Defines.InternalEvents.MAIN_MENU, function()
    if state.unknownItems > 0 or next(state.unknownKinds) ~= nil then
        apContractStatus()
    end
end)

contractLog("contract module loaded (console: LUA apContractStatus())")

]=], "@contract.lua", "t", _ENV)
  if chunk == nil then
    print("SYNTAX ERROR in contract.lua: " .. tostring(err))
    _G.__syntaxErrors = (_G.__syntaxErrors or 0) + 1
  else
    local ok, runErr = pcall(chunk)
    if not ok then
      print("LOAD ERROR in contract.lua: " .. tostring(runErr))
      _G.__loadErrors = (_G.__loadErrors or 0) + 1
    end
  end
end

do
  local chunk, err = load([=[
local TAG = "[AP-check] "

local function checkLog(message)
    log(TAG .. message)
end

local sent = {}
local lastSector = nil

local unsent = {}

local SENT, PENDING, NO_LOCATION = "sent", "pending", "no_location"

local function pushToServer(id)
    if _G.apNetSendCheck == nil or _G.apLocationNameFor == nil then
        return PENDING
    end
    local name = _G.apLocationNameFor(id)
    if name == nil then
        if _G.apSeedKnowsLocations and _G.apSeedKnowsLocations() then
            return NO_LOCATION
        end
        return PENDING
    end
    local ok, accepted = pcall(_G.apNetSendCheck, name)
    if ok and accepted ~= false then
        return SENT
    end
    return PENDING
end

function apResendPendingChecks()
    if #unsent == 0 then
        return 0
    end
    local still = {}
    local sentCount = 0
    for _, id in ipairs(unsent) do
        local issue = pushToServer(id)
        if issue == SENT then
            sentCount = sentCount + 1
        elseif issue == PENDING then
            still[#still + 1] = id
        end
    end
    unsent = still
    if sentCount > 0 then
        checkLog(sentCount .. " pending check(s) resent, " .. #unsent .. " remaining")
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("check.resent", { n = sentCount }))
        end
    end
    return sentCount
end

function apPendingCheckCount()
    return #unsent
end

local tutorialWarned = false
local outOfSeed = {}

-- A run only counts for a seed that was loaded when it started, and still is: a run played without one
-- has none of the seed's limits. The seed is written in the run's own save, so Continue cannot bring
-- back a run from another seed.
local runSeed = nil
local runFromSave = false
local seedlessWarned = false

local function seedLoaded()
    local contract = _G.apContractState
    return contract ~= nil and contract.connected == true
end

local function currentSeed()
    return seedLoaded() and (_G.apSeedFingerprint and apSeedFingerprint() or 0) or nil
end

local function savedRunSeed()
    local ok, value = pcall(function() return Hyperspace.playerVariables.ap_run_seed end)
    if ok and type(value) == "number" and value ~= 0 then
        return value
    end
    return nil
end

local function saveRunSeed(seed)
    pcall(function() Hyperspace.playerVariables.ap_run_seed = seed or 0 end)
end

local function seedMatches()
    if runFromSave then
        runSeed = savedRunSeed()
    end
    local seed = currentSeed()
    local started = runSeed == seed or (_G.apRunStartCheckForTesting == false and seed ~= nil)
    return seed ~= nil and started
end

local function currentLayout()
    local ok, name = pcall(function()
        return Hyperspace.ships.player.myBlueprint.blueprintName
    end)
    if ok and name and name ~= "" then
        return name
    end
    return nil
end

-- The run's ship must have come from Archipelago too: FTL unlocks ships by itself and cannot lock them
-- again. A refusal is written in the run's save, so it holds after a restart or once the key comes in.
-- Until the inventory is complete nothing is decided, and checks made meanwhile are held, not lost.
local SHIP_REFUSALS = { [1] = "not_received", [2] = "not_in_seed" }
local SHIP_CODES = { not_received = 1, not_in_seed = 2 }
local SHIP_MESSAGES = { not_received = "check.run_ship_not_received", not_in_seed = "check.run_ship_not_in_seed" }
local shipRefusal = nil
-- The layout already judged fine in this run: a key or a layout received later (waiting in the queue a moment)
-- must not make it "unknown" again, or a purchase made meanwhile would be refused.
local shipAccepted = nil
local shipWarned = false
local held, heldIds, heldVictory = {}, {}, nil

local function savedShipRefusal()
    local ok, value = pcall(function() return Hyperspace.playerVariables.ap_run_ship_refused end)
    return ok and SHIP_REFUSALS[value] or nil
end

local function saveShipRefusal(code)
    pcall(function() Hyperspace.playerVariables.ap_run_ship_refused = code end)
end

-- The hangar keeps bStartedGame on and shows each ship browsed as the player's: only a run is judged.
local function inRun()
    local ok, running = pcall(function()
        local app = Hyperspace.App
        return app.world.bStartedGame == true and app.menu.bOpen ~= true and app.menu.shipBuilder.bOpen ~= true
    end)
    return ok and running == true
end

local function shipStatus()
    if _G.apShipCheckForTesting == false then
        return "ok"
    end
    if not inRun() then
        return "unknown"
    end
    shipRefusal = shipRefusal or savedShipRefusal()
    if shipRefusal ~= nil then
        return shipRefusal
    end
    if shipAccepted ~= nil and shipAccepted == currentLayout() then
        return "ok"
    end
    if not (_G.apInventorySynced and apInventorySynced()) then
        return "unknown"
    end
    local layout = currentLayout()
    if layout == nil then
        return "unknown"
    end
    local status = _G.apShipReceived and apShipReceived(layout) or "ok"
    if status == "ok" then
        shipAccepted = layout
    end
    if SHIP_CODES[status] then
        shipRefusal = status
        saveShipRefusal(SHIP_CODES[status])
        checkLog("this run's ship (" .. layout .. ") is " .. status .. ": nothing it does counts")
    end
    return status
end

-- nil when the run counts, else "seed", "unknown" (not decided yet), "not_received" or "not_in_seed".
local function runRefusal()
    if not seedMatches() then
        return "seed"
    end
    local status = shipStatus()
    if status == "ok" then
        return nil
    end
    return status
end

function apRunRefusal()
    return runRefusal()
end

-- For items: a run not decided yet keeps them as before, it is only refused once its ship is known.
function apRunMatchesSeed()
    local refusal = runRefusal()
    return refusal == nil or refusal == "unknown"
end

local function warnShip(refusal)
    if shipWarned then
        return
    end
    shipWarned = true
    local layout = currentLayout()
    local ship = layout and ((_G.apShipLabel and _G.apShipLabel(layout)) or layout) or "?"
    if _G.apNotifyWarning then
        _G.apNotifyWarning(apT(SHIP_MESSAGES[refusal], { ship = ship }))
    end
end

function apRunCounts()
    local refusal = runRefusal()
    if refusal == nil then
        return true
    end
    if refusal == "seed" then
        if not seedlessWarned then
            seedlessWarned = true
            checkLog("this run was not started with the current seed loaded: nothing it does counts")
            if _G.apNotifyWarning then
                _G.apNotifyWarning(apT("check.run_without_seed"))
            end
        end
    elseif refusal ~= "unknown" then
        warnShip(refusal)
    end
    return false, refusal
end

-- A shop package stays on sale instead: holding it would sell it twice.
local function hold(id, label)
    if heldIds[id] or tostring(id):sub(1, 5) == "shop:" then
        return
    end
    if _G.apLocationNameFor and apLocationNameFor(id) == nil
        and _G.apSeedKnowsLocations and apSeedKnowsLocations() then
        return
    end
    heldIds[id] = true
    held[#held + 1] = { id = id, label = label }
    checkLog("held until the inventory is complete: " .. tostring(id))
end

local function releaseHeld()
    if #held == 0 and heldVictory == nil then
        return
    end
    if runRefusal() == "unknown" then
        return
    end
    local waiting, victory = held, heldVictory
    held, heldIds, heldVictory = {}, {}, nil
    checkLog(#waiting .. " held check(s) decided now that the inventory is complete")
    for _, entry in ipairs(waiting) do
        apSendCheck(entry.id, entry.label)
    end
    if victory then
        apVictoryWith(victory)
    end
end

function apHeldCheckCount()
    return #held + (heldVictory and 1 or 0)
end

function apSendCheck(id, label)
    if sent[id] then
        return false
    end

    local counts, refusal = apRunCounts()
    if not counts then
        if refusal == "unknown" then
            hold(id, label)
        end
        return false
    end

    if _G.apTutorialRunning and _G.apTutorialRunning() then
        if not tutorialWarned then
            tutorialWarned = true
            checkLog("tutorial in progress: no check is sent to the server")
        end
        return false
    end

    local name = _G.apLocationNameFor and _G.apLocationNameFor(id) or nil
    local onServer = (_G.apNetConnected and _G.apNetConnected()) or _G.apSoloEnabled
    if name == nil and onServer and _G.apSeedKnowsLocations and _G.apSeedKnowsLocations() then
        if not outOfSeed[id] then
            outOfSeed[id] = true
            checkLog("out of seed, nothing announced or sent: " .. tostring(id))
        end
        return false
    end

    sent[id] = true
    checkLog("CHECK " .. id .. (label and ("  (" .. label .. ")") or ""))

    if pushToServer(id) == PENDING then
        unsent[#unsent + 1] = id
    end

    if _G.apNotifyCheck then
        -- A shop package already says where it goes.
        local found = tostring(id):sub(1, 5) ~= "shop:" and _G.apNetScoutedItem and apNetScoutedItem(id) or nil
        _G.apNotifyCheck(name or label or id, found)
    end
    return true
end

function apCheckAlreadySent(id)
    return sent[id] == true
end

-- Only this slot's own locations count, each once: a key done offline that the seed does not have, or two keys
-- for the same location, would push the share past 100 %.
function apCheckCount()
    local names = (_G.apContractState and _G.apContractState.locNames) or {}
    local total = 0
    for _ in pairs(names) do
        total = total + 1
    end

    local done = {}
    local sentCount = 0
    for key in pairs(sent) do
        local name = names[key]
        if name ~= nil and not done[name] then
            done[name] = true
            sentCount = sentCount + 1
        end
    end

    return { sent = math.min(sentCount, total), total = total }
end

function apAdoptCheckedLocations(names)
    if type(names) ~= "table" then
        return 0
    end
    local adopted = 0
    for _, name in ipairs(names) do
        local key = _G.apCheckKeyFor and _G.apCheckKeyFor(name) or nil
        if key ~= nil and _G.apLocationNameFor and _G.apLocationNameFor(key) ~= nil
            and not sent[key] then
            sent[key] = true
            adopted = adopted + 1
        end
    end

    local still = {}
    for _, id in ipairs(unsent) do
        local known = false
        for _, name in ipairs(names) do
            if _G.apLocationNameFor and _G.apLocationNameFor(id) == name then
                known = true
                break
            end
        end
        if not known then still[#still + 1] = id end
    end
    local already = #unsent - #still
    unsent = still
    if already > 0 then
        checkLog(already .. " pending check(s) the server already knew about: not resent")
    end

    if adopted > 0 then
        checkLog(adopted .. " check(s) recovered from the server")
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("check.adopted", { n = adopted }))
        end
    end
    return adopted
end

function apForgetChecks()
    sent = {}
    unsent = {}
    outOfSeed = {}
end

function apRestoreSentChecks(keys)
    for _, key in ipairs(keys) do
        sent[key] = true
    end
end

function apForgetChecksForTesting()
    sent = {}
    unsent = {}
    tutorialWarned = false
    outOfSeed = {}
    checkLog("checks forgotten (tests)")
end

local function watchedAchievements(layout)
    local data = _G.apGameData
    if data == nil then
        return {}
    end

    local watched = {}
    for _, ach in ipairs(data.generalAchievements) do
        watched[#watched + 1] = ach
    end

    local base = layout and layout:gsub("_[23]$", "") or nil
    if base and data.shipAchievements[base] then
        for _, ach in ipairs(data.shipAchievements[base]) do
            watched[#watched + 1] = ach
        end
    end
    return watched
end

-- FTL keeps its own achievements apart: Hyperspace's tracker only holds the ones mods add (Multiverse's).
-- Both are read; an older module that cannot read FTL's leaves only the second, and says so once.
local achievementModuleWarned = false

local function achievementStatus(tracker, ach)
    local status = -1
    local vanilla = _G.apNetAchievementStatus and apNetAchievementStatus(ach) or nil
    if vanilla ~= nil then
        status = vanilla
    elseif not achievementModuleWarned then
        achievementModuleWarned = true
        checkLog("this Hyperspace build cannot read FTL's achievements: only custom ones are seen")
    end
    local ok, custom = pcall(function() return tracker:GetAchievementStatus(ach) end)
    if ok and type(custom) == "number" and custom > status then
        status = custom
    end
    return status
end

local function pollAchievements(layout)
    local tracker = Hyperspace.CustomAchievementTracker.instance
    for _, ach in ipairs(watchedAchievements(layout)) do
        local status = achievementStatus(tracker, ach)
        if status >= 0 then
            apSendCheck("ach:" .. ach,
                apT("check.label.achievement", { name = apAchievementLabel(ach) }))
        end
    end
end

local function pollSystems(layout)
    local player = Hyperspace.ships.player
    if player == nil then
        return
    end
    local ship = layout and layout:gsub("_[23]$", "") or nil
    local systems = player.vSystemList
    for index = 0, systems:size() - 1 do
        local system = systems[index]
        local name = Hyperspace.ShipSystem.SystemIdToName(system.iSystemType)
        if name ~= nil and name ~= "" then
            local label = (_G.apSystemLabel and _G.apSystemLabel(name)) or name
            apSendCheck("sys:" .. name, apT("check.label.system", { name = label }))
            local perShip = ship and (ship .. ":sys:" .. name) or nil
            if perShip and _G.apLocationNameFor and apLocationNameFor(perShip) ~= nil then
                apSendCheck(perShip, apT("check.label.system", { name = label }))
            end
            local level = system.powerState and system.powerState.second or 1
            for tier = 2, level do
                apSendCheck("sys:" .. name .. ":" .. tier,
                    apT("check.label.system.level", { name = label, n = tier }))
            end
        end
    end
end

-- The crew aboard when the run started, one by one: a human who joins the Kestrel's human crew is still a
-- recruit, so the check goes by who joined, not by which species was already there.
local startingCrew = nil

local function crewKey(member)
    local ok, id = pcall(function() return member.extend.selfId end)
    if ok and id ~= nil and id >= 0 then
        return "id" .. tostring(id)
    end
    return "name:" .. tostring(member.name) .. ":" .. tostring(member.species)
end

-- Our living crew, not counting drones or boarders: who -> species.
local function crewAboard()
    local crew = {}
    local player = Hyperspace.ships.player
    if player == nil then
        return nil
    end
    local list = player.vCrewList
    for index = 0, list:size() - 1 do
        local member = list[index]
        local drone = false
        if member.IsDrone ~= nil then
            local ok, result = pcall(function() return member:IsDrone() end)
            drone = ok and result == true
        end
        if member.iShipId == 0 and not member.bDead and not drone then
            local species = tostring(member.species or "")
            if species ~= "" then
                crew[crewKey(member)] = species
            end
        end
    end
    return crew
end

-- Multiverse splits species into kinds (engi_separatist, human_soldier, zoltan_monk...): each counts as its race.
local RACE_FAMILY = {
    human = "human", engi = "engi", energy = "energy", zoltan = "energy", mantis = "mantis",
    rock = "rock", slug = "slug", anaerobic = "anaerobic", lanius = "anaerobic", crystal = "crystal",
    -- Multiverse's own races, each with its variants (orchid_vampweed, phantom_goul...).
    orchid = "orchid", shell = "shell", leech = "leech", phantom = "phantom", spider = "spider",
    lizard = "lizard", cognitive = "cognitive", siren = "siren", pony = "pony", obelisk = "obelisk",
}

function apRaceFamily(species)
    species = tostring(species or "")
    return RACE_FAMILY[species] or RACE_FAMILY[species:match("^(%a+)_") or ""] or species
end

local function pollCrew()
    local present = crewAboard()
    if present == nil then
        return
    end
    if startingCrew == nil then
        startingCrew = present
        return
    end
    for key, species in pairs(present) do
        if startingCrew[key] == nil then
            local race = apRaceFamily(species)
            local label = (_G.apRaceLabel and _G.apRaceLabel(race)) or race
            apSendCheck("crew:" .. race, apT("check.label.crew", { name = label }))
        end
    end
end

script.on_internal_event(Defines.InternalEvents.ON_TICK, function()
    if startingCrew == nil then
        pcall(function()
            startingCrew = crewAboard()
        end)
    end
    apTry(TAG, function()
        releaseHeld()
        -- Said as the run starts, not at its first check: the player can still go back to the hangar.
        if not shipWarned and seedMatches() then
            local status = shipStatus()
            if SHIP_CODES[status] then
                warnShip(status)
            end
        end
    end)
end)

script.on_internal_event(Defines.InternalEvents.JUMP_ARRIVE, function(shipManager)
    if shipManager.iShipId ~= 0 then
        return
    end

    apTry(TAG, function()
        local layout = currentLayout()
        local starMap = Hyperspace.App.world.starMap
        local sector = math.floor(starMap.worldLevel) + 1

        if layout and sector ~= lastSector then
            lastSector = sector
            apSendCheck(layout .. ":sector:" .. sector,
                apT("check.label.sector",
                    { n = sector, ship = (_G.apShipLabel and _G.apShipLabel(layout)) or layout }))
        end

        pollAchievements(layout)
        pollSystems(layout)
        pollCrew()
    end)
end)

local previousOnRunEnd = apOnRunEnd

-- Victory Collects the Layout set to everything: the ship's own achievements, per-ship system checks and
-- fight checks.
local function collectShipChecks(layout)
    local ship = tostring(layout):gsub("_[23]$", "")
    local data = _G.apGameData or {}
    for _, achievement in ipairs((data.shipAchievements or {})[ship] or {}) do
        local key = "ach:" .. achievement
        if _G.apLocationNameFor and apLocationNameFor(key) ~= nil then
            apSendCheck(key, apT("check.label.achievement", {
                name = (_G.apAchievementLabel and apAchievementLabel(achievement)) or achievement }))
        end
    end
    for _, kind in ipairs({ ":sys:", ":fight:" }) do
        local prefix = ship .. kind
        for key, name in pairs(((_G.apContractState or {}).locNames) or {}) do
            if tostring(key):sub(1, #prefix) == prefix then
                apSendCheck(key, tostring(name))
            end
        end
    end
end

function apOnRunEnd(cause, detail)
    if previousOnRunEnd then
        previousOnRunEnd(cause, detail)
    end
    if cause ~= "victory" then
        return
    end
    apTry(TAG, function()
        local layout = currentLayout()
        local collect = tonumber(apSeedOption("victory_collects_layout") or 0) or 0
        if layout and collect >= 1 then
            local ship = (_G.apShipLabel and _G.apShipLabel(layout)) or layout
            for sector = 1, 8 do
                local key = layout .. ":sector:" .. sector
                if _G.apLocationNameFor and apLocationNameFor(key) ~= nil then
                    apSendCheck(key, apT("check.label.sector", { n = sector, ship = ship }))
                end
            end
        end
        if layout and collect >= 2 then
            collectShipChecks(layout)
        end
        if layout then
            apSendCheck(layout .. ":victory",
                apT("check.label.victory",
                    { ship = (_G.apShipLabel and _G.apShipLabel(layout)) or layout }))
            apVictoryWith(layout)
        else
            checkLog("victory detected but unknown ship")
            if _G.apNotifyStatus then
                _G.apNotifyStatus(apT("check.victory.unknown_ship"))
            end
        end
    end)
end

-- Hyperspace loads the run's variables after on_init, so a continued run reads its seed later.
script.on_init(function(newGame)
    lastSector = nil
    startingCrew = nil
    seedlessWarned = false
    shipRefusal = nil
    shipAccepted = nil
    shipWarned = false
    held, heldIds, heldVictory = {}, {}, nil
    runFromSave = newGame == false
    if runFromSave then
        runSeed = nil
    else
        runSeed = currentSeed()
        saveRunSeed(runSeed)
        saveShipRefusal(0)
    end
end)

-- Solo started during a run that had no seed: the run takes this one.
function apRunAdoptSeed()
    if runFromSave then
        runSeed = savedRunSeed()
    end
    if runSeed == nil then
        runSeed = currentSeed()
        runFromSave = false
        saveRunSeed(runSeed)
    end
end

function apRunSeedForTesting(value)
    runSeed = value
    runFromSave = false
    seedlessWarned = false
    shipRefusal = nil
    shipAccepted = nil
    shipWarned = false
    held, heldIds, heldVictory = {}, {}, nil
end

local victories = {}
local goalAnnounced = false
local victoriesFor = nil

local function victoryKey(layout)
    return apNetSlotKey("ap_goalwin_" .. tostring(_G.apSeedFingerprint and apSeedFingerprint() or 0) .. "_" .. layout)
end

local function allLayouts()
    local layouts = {}
    local data = _G.apGameData or {}
    for _, ship in ipairs(data.ships or {}) do
        for index = 0, (ship.layouts or 1) - 1 do
            layouts[#layouts + 1] = ship.name .. ((data.variantSuffix or {})[index] or "")
        end
    end
    return layouts
end

-- Victories that counted are kept per seed, so a goal of several wins can span several sessions.
local function loadVictories()
    local contract = _G.apContractState
    if contract == nil or contract.connected ~= true or not _G.apNetRecall then
        return
    end
    local seed = apSeedFingerprint()
    if victoriesFor == seed then
        return
    end
    victoriesFor = seed
    for _, layout in ipairs(allLayouts()) do
        if apNetRecall(victoryKey(layout)) == 1 then
            victories[layout] = true
        end
    end
end

local LEVELS = { any = 0, normal = 1, hard = 2 }

local function gameDifficulty()
    local ok, value = pcall(function()
        return Hyperspace.Settings.difficulty
    end)
    return (ok and tonumber(value)) or 0
end

function apAdvancedEditionOff()
    local ok, active = pcall(function()
        return Hyperspace.Settings.bDlcEnabled
    end)
    return ok and active == false
end

local function difficultyEnough()
    local goal = _G.apGoal and _G.apGoal() or nil
    local required = LEVELS[(goal or {}).difficulty or "any"] or 0
    if required == 0 then
        return true, required
    end
    return gameDifficulty() >= required, required
end

local DIFFICULTY_NAME = { [0] = "difficulty.easy", [1] = "difficulty.normal", [2] = "difficulty.hard" }

function apGoalArchives()
    local goal = _G.apGoal and _G.apGoal() or nil
    local requested = (goal or {}).archives or 0
    if requested <= 0 then
        return nil
    end
    return requested
end

function apReceivedArchives()
    return ((_G.apInventory or {}).archives) or 0
end

function apGoalDifficulty()
    local goal = _G.apGoal and _G.apGoal() or nil
    local requested = (goal or {}).difficulty or "any"
    if requested == "any" then
        return nil
    end
    return apT(DIFFICULTY_NAME[LEVELS[requested]] or "difficulty.normal")
end

local function archivesMissing()
    local archives = apGoalArchives()
    if archives == nil then
        return 0
    end
    return math.max(0, archives - apReceivedArchives())
end

function apGoalArchivesMissing()
    return archivesMissing()
end

local function goalIsReached()
    loadVictories()
    local goal = _G.apGoal and _G.apGoal() or nil
    if type(goal) ~= "table" or goal.kind ~= "victories" then
        return false, 0
    end

    local archives = apGoalArchives()
    if archives ~= nil and apReceivedArchives() < archives then
        local counted = 0
        if goal.layouts ~= nil then
            for _, blueprint in ipairs(goal.layouts) do
                if victories[blueprint] then counted = counted + 1 end
            end
        else
            for _ in pairs(victories) do counted = counted + 1 end
        end
        return false, counted
    end

    local counted = 0
    if goal.layouts ~= nil then
        for _, blueprint in ipairs(goal.layouts) do
            if victories[blueprint] then
                counted = counted + 1
            end
        end
        return counted >= #goal.layouts, counted
    end

    for _ in pairs(victories) do
        counted = counted + 1
    end
    return counted >= (goal.count or 1), counted
end

function apGoalWonWith()
    loadVictories()
    local won = {}
    for layout in pairs(victories) do
        won[#won + 1] = layout
    end
    table.sort(won)
    return won
end

function apGoalProgress()
    local goal = _G.apGoal and _G.apGoal() or nil
    if type(goal) ~= "table" or goal.kind ~= "victories" then
        return nil
    end
    local reached, counted = goalIsReached()
    return {
        done = counted,
        total = goal.layouts and #goal.layouts or (goal.count or 1),
        reached = reached,
    }
end

function apVictoryWith(layout)
    loadVictories()
    if layout == nil or victories[layout] then
        return
    end
    local counts, refusal = apRunCounts()
    if not counts then
        if refusal == "unknown" then
            heldVictory = layout
        end
        return
    end
    if not apLayoutInSeed(layout) then
        checkLog("victory with " .. layout .. ", which is not in the seed: not counted")
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("goal.layout_outside"))
        end
        return
    end

    local enough, required = difficultyEnough()
    if not enough then
        checkLog(string.format("victory at difficulty %d, the goal requires %d: not counted",
            gameDifficulty(), required))
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("goal.too_easy", { difficulty = apGoalDifficulty() or "" }))
        end
        return
    end

    victories[layout] = true
    if _G.apNetRemember then apNetRemember(victoryKey(layout), 1) end

    local reached, counted = goalIsReached()
    local goal = _G.apGoal and _G.apGoal() or nil
    local needed = goal and (goal.layouts and #goal.layouts or goal.count) or nil

    if needed then
        checkLog(string.format("victory %d/%d towards the goal", counted, needed))
    end

    if not reached or goalAnnounced then
        if needed and _G.apNotifyStatus then
            local missing = archivesMissing()
            if counted >= needed and missing > 0 then
                _G.apNotifyStatus(apT("goal.archives_missing", { n = missing, done = counted, total = needed }))
            else
                _G.apNotifyStatus(apT("goal.progress", { done = counted, total = needed }))
            end
        end
        return
    end

    checkLog("GOAL REACHED: declaring to the server")
    apDeclareGoal()
end

function apDeclareGoal()
    if goalAnnounced then
        return true
    end
    local reached = goalIsReached()
    if not reached then
        return false
    end

    local goalSent = false
    if _G.apNetSendGoal then
        local ok, result = pcall(_G.apNetSendGoal)
        goalSent = ok and result ~= false
    end

    if goalSent then
        goalAnnounced = true
        checkLog("goal declared to the server")
    else
        checkLog("goal NOT declared: no connection, will retry on reconnect")
    end
    local notify = _G.apNotifyKept or _G.apNotifyStatus
    if notify then
        notify(apT(goalSent and "goal.reached" or "goal.not_sent"))
    end
    return goalSent
end

function apChecksForgetSeed()
    sent = {}
    unsent = {}
    outOfSeed = {}
    victories = {}
    victoriesFor = nil
    goalAnnounced = false
    lastSector = nil
    checkLog("new seed: checks, victories and goal reset")
end

function apVictoriesResetForTesting()
    victories = {}
    victoriesFor = nil
    goalAnnounced = false
end

function apGoalStatus()
    local goal = _G.apGoal and _G.apGoal() or nil
    if goal == nil then
        checkLog("no known goal (offline)")
        return
    end
    local reached, counted = goalIsReached()
    local needed = goal.layouts and #goal.layouts or goal.count
    checkLog(string.format("goal: %d/%s victory(ies)%s", counted, tostring(needed),
        reached and " - REACHED" or ""))
    if goal.layouts then
        for _, blueprint in ipairs(goal.layouts) do
            checkLog("  " .. blueprint .. (victories[blueprint] and ": done" or ": pending"))
        end
    end
end

local function isOpenLead(key)
    if sent[key] then
        return false
    end
    return _G.apLocationNameFor and _G.apLocationNameFor(key) ~= nil
end

function apNextLeads(limit)
    limit = limit or 3
    local leads = {}

    local function add(key)
        if #leads < limit and isOpenLead(key) then
            leads[#leads + 1] = { key = key, name = _G.apLocationNameFor(key) }
        end
    end

    local ok = pcall(function()
        local layout = currentLayout()
        local starMap = Hyperspace.App.world.starMap
        local sector = math.floor(starMap.worldLevel) + 1

        if layout then
            for ahead = 0, 3 do
                add(layout .. ":sector:" .. (sector + ahead))
            end
        end

        for slot = 1, (_G.apShopSlotCount or 0) do
            add("shop:" .. slot)
        end

        if layout then
            add(layout .. ":victory")
        end
    end)

    if not ok then
        return {}
    end
    return leads
end

function apCheckStatus()
    local count = 0
    for _ in pairs(sent) do
        count = count + 1
    end
    checkLog(count .. " checks sent since the game started:")
    for id in pairs(sent) do
        checkLog("  " .. id)
    end
end

checkLog("check detection module loaded")

-- sector_skip: a layout that already reached the next sector in an earlier run may skip sectors 1 to 4. Their
-- first beacon becomes an exit: jump on at once for some scrap and one more pick in the start-of-run menu, or
-- explore as usual. Each layout's deepest sector
-- is kept in the profile.
local SKIP_LAST_SECTOR = 4
local SKIP_SCRAP = 60

local function skipOn()
    local value = _G.apSeedOption and apSeedOption("sector_skip")
    return value == 1 or value == true
end

local function runVariable(name)
    local ok, value = pcall(function() return Hyperspace.playerVariables[name] end)
    return ok and math.floor(tonumber(value) or 0) or 0
end

-- The offered beacon is known by its place on the map: FTL rebuilds the location objects, and during a jump
-- currentLoc is already the destination.
local function locKey(loc)
    local ok, x, y = pcall(function() return loc.loc.x, loc.loc.y end)
    if not ok or x == nil then
        return nil
    end
    return math.floor(x) * 10000 + math.floor(y)
end

local function isOfferedBeacon(loc)
    local key = locKey(loc)
    return key ~= nil and key == runVariable("ap_skip_loc") - 1
end

-- Refused (another beacon was chosen): the offered beacon stops being an exit for the rest of the sector.
local function withdrawOffer()
    Hyperspace.playerVariables.ap_skip_offered = 0
    pcall(function()
        local locations = Hyperspace.App.world.starMap.locations
        for i = 0, locations:size() - 1 do
            if isOfferedBeacon(locations[i]) then
                locations[i].beacon = false
            end
        end
    end)
    checkLog("sector skip refused: the offered beacon is no exit any more")
end

local function deepestReached(layout)
    local ok, value = pcall(function() return Hyperspace.metaVariables["ap_reached_" .. layout] end)
    return ok and math.floor(tonumber(value) or 0) or 0
end

function apSectorSkipArrive()
    local layout = currentLayout()
    if layout == nil then
        return
    end
    local sector = math.floor(Hyperspace.App.world.starMap.worldLevel) + 1
    if sector > deepestReached(layout) then
        Hyperspace.metaVariables["ap_reached_" .. layout] = sector
    end
    local previous = runVariable("ap_skip_sector")
    if sector == previous then
        Hyperspace.playerVariables.ap_skip_jumps = runVariable("ap_skip_jumps") + 1
        if runVariable("ap_skip_offered") == sector then
            withdrawOffer()
        end
        return
    end
    -- A new sector: the last one was skipped if the exit was taken from its first beacon.
    if runVariable("ap_skip_offered") == previous and previous > 0 and runVariable("ap_skip_jumps") == 0 then
        Hyperspace.ships.player:ModifyScrapCount(SKIP_SCRAP, false)
        _G.apLoadoutExtraPick = true
        checkLog("sector " .. previous .. " skipped, reward: " .. SKIP_SCRAP)
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("sector_skip.done", { n = previous, scrap = SKIP_SCRAP }))
        end
    end
    Hyperspace.playerVariables.ap_skip_sector = sector
    Hyperspace.playerVariables.ap_skip_jumps = 0
    if not skipOn() or sector > SKIP_LAST_SECTOR then
        return
    end
    local done = deepestReached(layout) > sector
        or apCheckAlreadySent(layout .. ":sector:" .. (sector + 1))
    if not done then
        return
    end
    local here = Hyperspace.App.world.starMap.currentLoc
    here.beacon = true
    Hyperspace.playerVariables.ap_skip_offered = sector
    -- Its place is taken on the next ticks: on arrival FTL has not laid out the new sector's map yet.
    Hyperspace.playerVariables.ap_skip_loc = 0
    checkLog("sector " .. sector .. " can be skipped: its first beacon is an exit")
    if _G.apNotifyStatus then
        _G.apNotifyStatus(apT("sector_skip.offered", { n = sector, scrap = SKIP_SCRAP }))
    end
end

script.on_internal_event(Defines.InternalEvents.JUMP_ARRIVE, function(shipManager)
    if shipManager.iShipId == 0 then
        apTry(TAG, apSectorSkipArrive)
    end
end)

-- A new run starts at its first beacon without a jump: that beacon is judged once the run is under way.
local skipStartTicks = 0
script.on_internal_event(Defines.InternalEvents.ON_TICK, function()
    skipStartTicks = (skipStartTicks + 1) % 30
    if skipStartTicks ~= 0 or not inRun() then
        return
    end
    if runVariable("ap_skip_sector") == 0 then
        apTry(TAG, apSectorSkipArrive)
        return
    end
    -- While the offer stands (no jump yet in this sector), its beacon stays an exit: FTL builds the start beacon
    -- again as the run settles, which took the exit back.
    apTry(TAG, function()
        local sector = math.floor(Hyperspace.App.world.starMap.worldLevel) + 1
        local here = Hyperspace.App.world.starMap.currentLoc
        if here == nil or runVariable("ap_skip_offered") ~= sector or runVariable("ap_skip_sector") ~= sector
            or runVariable("ap_skip_jumps") ~= 0 or Hyperspace.ships.player.bJumping then
            return
        end
        if runVariable("ap_skip_loc") == 0 then
            Hyperspace.playerVariables.ap_skip_loc = (locKey(here) or -1) + 1
        end
        if here.beacon ~= true and isOfferedBeacon(here) then
            here.beacon = true
        end
    end)
end)

-- sector_locks: the exit of sector 4 (or 7) stays shut for a layout without its first (or second) Sector Pass,
-- and opens as soon as the pass comes in.
local lockedExit, lockedNeed, lockedLayout = nil, 0, nil

local function locksOn()
    local value = _G.apSeedOption and apSeedOption("sector_locks")
    return value == 1 or value == true
end

local function passesFor(layout)
    return (((_G.apInventory or {}).passes or {})[layout]) or 0
end

function apSectorLockArrive()
    lockedExit = nil
    if not locksOn() then
        return
    end
    local layout = currentLayout()
    local sector = math.floor(Hyperspace.App.world.starMap.worldLevel) + 1
    local need = sector == 4 and 1 or (sector == 7 and 2 or 0)
    local here = Hyperspace.App.world.starMap.currentLoc
    if layout == nil or need == 0 or here == nil or here.beacon ~= true or passesFor(layout) >= need then
        return
    end
    here.beacon = false
    lockedExit, lockedNeed, lockedLayout = here, need, layout
    checkLog("sector " .. sector .. " exit shut: " .. layout .. " needs Sector Pass " .. need)
    if _G.apNotifyWarning then
        _G.apNotifyWarning(apT("sector_locks.closed", { n = need, sector = sector }))
    end
end

local lockTicks = 0
script.on_internal_event(Defines.InternalEvents.ON_TICK, function()
    lockTicks = (lockTicks + 1) % 60
    if lockTicks ~= 0 or lockedExit == nil then
        return
    end
    if passesFor(lockedLayout) >= lockedNeed then
        lockedExit.beacon = true
        lockedExit = nil
        checkLog("sector exit opened: the pass came in")
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("sector_locks.open"))
        end
    end
end)

script.on_internal_event(Defines.InternalEvents.JUMP_ARRIVE, function(shipManager)
    if shipManager.iShipId == 0 then
        apTry(TAG, apSectorLockArrive)
    end
end)

-- A run that does not count says so for as long as it lasts, in the same few words as the hangar's marks.
local REFUSED_MARKS = { not_received = "run.refused.no_key", not_in_seed = "run.refused.not_in_seed" }

local function drawRefusedRun()
    if _G.apDashboardOpen and apDashboardOpen() then
        return
    end
    local key = inRun() and REFUSED_MARKS[shipRefusal or savedShipRefusal() or ""]
    if not key then
        return
    end
    local label = apT(key)
    local width = apUi.width(14, label) + 32
    local x = (1280 - width) / 2
    apUi.rect(x, 90, width, 40, "window", 0.95)
    apUi.outline(x, 90, width, 40, "warn", 2)
    apUi.textCenter(14, 640, 98, width - 16, "warn", label)
end

script.on_render_event(Defines.RenderEvents.GUI_CONTAINER, function() end, function()
    apTry(TAG, drawRefusedRun)
end)

