do
  local chunk, err = load([=[
local TAG = "[AP-crewnames] "

local function namesLog(message)
    log(TAG .. message)
end

-- crew_names: a crew member who joins during a run takes the name of another player of the multiworld, then
-- (multiworld_and_team) of someone who made or tested the mod. Once every name is aboard, FTL's own stay.
local TEAM = { "Liloji", "Trapper", "Eto", "File Missing", "Yunus", "Rhythm", "Duck", "Fletchy", "Mongolico",
               "Studkid", "Simba", "Astron" }

local config = { mode = "vanilla", players = {} }

-- FTL's fonts only draw plain ASCII: a slot name with anything else would show holes.
local function drawable(name)
    return type(name) == "string" and name:match("^[ -~]+$") ~= nil and name:match("%S") ~= nil
end

function apCrewNamesConfigure(mode, players)
    config.mode = (mode == "multiworld" or mode == "multiworld_and_team") and mode or "vanilla"
    config.players = {}
    for _, name in ipairs(type(players) == "table" and players or {}) do
        if drawable(name) then
            config.players[#config.players + 1] = name
        end
    end
    namesLog(string.format("mode %s, %d player name(s)", config.mode, #config.players))
end

function apCrewNamesPool()
    local pool = {}
    if config.mode == "vanilla" then
        return pool
    end
    for _, name in ipairs(config.players) do
        pool[#pool + 1] = name
    end
    if config.mode == "multiworld_and_team" then
        for _, name in ipairs(TEAM) do
            pool[#pool + 1] = name
        end
    end
    return pool
end

local function memberIs(member, method)
    local ok, result = pcall(function() return member[method](member) end)
    return ok and result == true
end

-- Holograms, projections, pets and other crew without a crew slot keep FTL's name: see deathlink.lua.
local function temporary(member)
    local ok, result = pcall(function()
        local extend = member.extend
        return extend.deathTimer ~= nil or extend.noSlot == true
    end)
    return ok and result == true
end

local function crewKey(member)
    local ok, id = pcall(function() return member.extend.selfId end)
    if ok and id ~= nil and id >= 0 then
        return "id" .. tostring(id)
    end
    return "name:" .. tostring(member:GetName())
end

local function runInProgress()
    local ok, started = pcall(function()
        local app = Hyperspace.App
        return app.world.bStartedGame == true and app.menu.shipBuilder.bOpen ~= true
    end)
    return ok and started == true
end

-- Our own crew aboard, alive: what gets a name.
local function ownCrew()
    local crew = {}
    local list = Hyperspace.ships.player.vCrewList
    for i = 0, list:size() - 1 do
        local member = list[i]
        if member ~= nil and member.iShipId == 0 and not member.bDead and not memberIs(member, "IsDrone")
            and not temporary(member) then
            crew[#crew + 1] = member
        end
    end
    return crew
end

local function rename(member, name)
    local ok, err = pcall(function()
        local text = Hyperspace.TextString()
        text.data = name
        text.isLiteral = true
        member:SetName(text, true)
    end)
    if not ok then
        namesLog("rename failed: " .. tostring(err))
    end
    return ok
end

-- The crew aboard when a run starts or is continued is known: only those who join later get a new name.
local known = nil

local function sample()
    if not runInProgress() or Hyperspace.ships.player == nil then
        known = nil
        return
    end
    local crew = ownCrew()
    if known == nil then
        known = {}
        for _, member in ipairs(crew) do
            known[crewKey(member)] = true
        end
        return
    end
    local pool = apCrewNamesPool()
    for _, member in ipairs(crew) do
        local key = crewKey(member)
        if not known[key] then
            known[key] = true
            if #pool > 0 then
                local used = {}
                for _, other in ipairs(crew) do
                    used[tostring(other:GetName())] = true
                end
                for _, name in ipairs(pool) do
                    if not used[name] then
                        local before = tostring(member:GetName())
                        if rename(member, name) then
                            namesLog(before .. " joins as " .. name)
                        end
                        break
                    end
                end
            end
        end
    end
end

local divider = 0
script.on_internal_event(Defines.InternalEvents.ON_TICK, function()
    divider = (divider + 1) % 30
    if divider == 0 then
        apTry(TAG, sample)
    end
end)

script.on_init(function()
    known = nil
end)

script.on_internal_event(Defines.InternalEvents.MAIN_MENU, function()
    known = nil
end)

namesLog("crew names module loaded")

]=], "@crewnames.lua", "t", _ENV)
  if chunk == nil then
    print("SYNTAX ERROR in crewnames.lua: " .. tostring(err))
    _G.__syntaxErrors = (_G.__syntaxErrors or 0) + 1
  else
    local ok, runErr = pcall(chunk)
    if not ok then
      print("LOAD ERROR in crewnames.lua: " .. tostring(runErr))
      _G.__loadErrors = (_G.__loadErrors or 0) + 1
    end
  end
end

do
  local chunk, err = load([=[
local TAG = "[AP-json] "

local ESCAPES = {
    ['"'] = '"', ["\\"] = "\\", ["/"] = "/",
    b = "\b", f = "\f", n = "\n", r = "\r", t = "\t",
}

local decodeValue

local function skipBlanks(text, i)
    local _, stop = text:find("^[ \t\r\n]*", i)
    return stop + 1
end

local function toUtf8(code)
    if code < 0x80 then
        return string.char(code)
    elseif code < 0x800 then
        return string.char(0xC0 + math.floor(code / 0x40), 0x80 + code % 0x40)
    elseif code < 0x10000 then
        return string.char(0xE0 + math.floor(code / 0x1000),
                           0x80 + math.floor(code / 0x40) % 0x40,
                           0x80 + code % 0x40)
    end
    return string.char(0xF0 + math.floor(code / 0x40000),
                       0x80 + math.floor(code / 0x1000) % 0x40,
                       0x80 + math.floor(code / 0x40) % 0x40,
                       0x80 + code % 0x40)
end

local function decodeString(text, i)
    local parts = {}
    local j = i + 1
    while true do
        local c = text:sub(j, j)
        if c == "" then
            return nil, j, "unterminated string"
        elseif c == '"' then
            return table.concat(parts), j + 1
        elseif c == "\\" then
            local escNext = text:sub(j + 1, j + 1)
            if escNext == "u" then
                local hex = text:sub(j + 2, j + 5)
                local code = tonumber(hex, 16)
                if code == nil then
                    return nil, j, "invalid \\u escape"
                end
                if code >= 0xD800 and code <= 0xDBFF and text:sub(j + 6, j + 7) == "\\u" then
                    local low = tonumber(text:sub(j + 8, j + 11), 16)
                    if low and low >= 0xDC00 and low <= 0xDFFF then
                        code = 0x10000 + (code - 0xD800) * 0x400 + (low - 0xDC00)
                        j = j + 6
                    end
                end
                parts[#parts + 1] = toUtf8(code)
                j = j + 6
            else
                local replacement = ESCAPES[escNext]
                if replacement == nil then
                    return nil, j, "unknown escape: \\" .. escNext
                end
                parts[#parts + 1] = replacement
                j = j + 2
            end
        else
            local _, stop = text:find('^[^"\\]+', j)
            parts[#parts + 1] = text:sub(j, stop)
            j = stop + 1
        end
    end
end

local function decodeArray(text, i)
    local result = {}
    local j = skipBlanks(text, i + 1)
    if text:sub(j, j) == "]" then
        return result, j + 1
    end
    while true do
        local value, next_, err = decodeValue(text, j)
        if err then return nil, next_, err end
        result[#result + 1] = value
        j = skipBlanks(text, next_)
        local c = text:sub(j, j)
        if c == "]" then
            return result, j + 1
        elseif c ~= "," then
            return nil, j, "expected comma or closing bracket"
        end
        j = skipBlanks(text, j + 1)
    end
end

local function decodeObject(text, i)
    local result = {}
    local j = skipBlanks(text, i + 1)
    if text:sub(j, j) == "}" then
        return result, j + 1
    end
    while true do
        if text:sub(j, j) ~= '"' then
            return nil, j, "expected key"
        end
        local key, next_, err = decodeString(text, j)
        if err then return nil, next_, err end
        j = skipBlanks(text, next_)
        if text:sub(j, j) ~= ":" then
            return nil, j, "expected colon"
        end
        j = skipBlanks(text, j + 1)
        local value, next2, err2 = decodeValue(text, j)
        if err2 then return nil, next2, err2 end
        result[key] = value
        j = skipBlanks(text, next2)
        local c = text:sub(j, j)
        if c == "}" then
            return result, j + 1
        elseif c ~= "," then
            return nil, j, "expected comma or closing brace"
        end
        j = skipBlanks(text, j + 1)
    end
end

decodeValue = function(text, i)
    local c = text:sub(i, i)
    if c == "{" then
        return decodeObject(text, i)
    elseif c == "[" then
        return decodeArray(text, i)
    elseif c == '"' then
        return decodeString(text, i)
    elseif text:sub(i, i + 3) == "true" then
        return true, i + 4
    elseif text:sub(i, i + 4) == "false" then
        return false, i + 5
    elseif text:sub(i, i + 3) == "null" then
        return false, i + 4
    end
    local _, stop = text:find("^%-?%d+%.?%d*[eE]?[-+]?%d*", i)
    if stop == nil or stop < i then
        return nil, i, "unexpected value: '" .. text:sub(i, i + 12) .. "'"
    end
    local number = tonumber(text:sub(i, stop))
    if number == nil then
        return nil, i, "invalid number"
    end
    return number, stop + 1
end

function apJsonDecode(text)
    if type(text) ~= "string" or text == "" then
        return nil, "nothing to decode"
    end
    local i = skipBlanks(text, 1)
    local value, next_, err = decodeValue(text, i)
    if err then
        return nil, err .. " (position " .. tostring(next_) .. ")"
    end
    local stop = skipBlanks(text, next_)
    if stop <= #text then
        return nil, "extra text after value (position " .. tostring(stop) .. ")"
    end
    return value
end

log(TAG .. "JSON reader loaded")

]=], "@json.lua", "t", _ENV)
  if chunk == nil then
    print("SYNTAX ERROR in json.lua: " .. tostring(err))
    _G.__syntaxErrors = (_G.__syntaxErrors or 0) + 1
  else
    local ok, runErr = pcall(chunk)
    if not ok then
      print("LOAD ERROR in json.lua: " .. tostring(runErr))
      _G.__loadErrors = (_G.__loadErrors or 0) + 1
    end
  end
end

do
  local chunk, err = load([=[
local TAG = "[AP-net] "

local function netLog(message)
    log(TAG .. message)
end

local RETRY_DELAYS = { 5, 10, 20, 40, 60 }

local state = {
    available = false,
    connecting = false,
    connected = false,
    lastConnection = nil,
    retries = 0,
    retryAt = nil,
    ticks = 0,
    lastItemIndex = -1,
    consumedUntil = -1,
    delivered = {},
    itemNames = {},
    scoutsPending = false,
    scouted = {},
}

_G.apNetState = state

function apNetResetForTesting()
    state.connecting = false
    state.connected = false
    state.everConnected = false
    state.lastConnection = nil
    state.retries = 0
    state.retryAt = nil
    state.ticks = 0
    state.lastItemIndex = -1
    state.consumedUntil = -1
    state.delivered = {}
    state.itemNames = {}
    state.scoutsPending = false
    state.scouted = {}
    state.checkItems = {}
    state.ownAlias = nil
    state.scoutRetries = 0
    state.scoutRetryAt = nil
    state.seedRefused = false
    state.refusal = nil
    state.refusalReasons = nil
    state.replayClean = false
    state.itemsInBatch = false
    if _G.apNetForgetDurableStore then _G.apNetForgetDurableStore() end
end

local function client()
    local ok, instance = pcall(function()
        return Hyperspace.Archipelago and Hyperspace.Archipelago.Instance()
    end)
    if ok and instance ~= nil then
        return instance
    end
    return nil
end

local adoptServerChecks

local function whenConnected(action)
    local ap = client()
    if ap == nil or not state.connected then
        return false
    end
    return action(ap)
end

function apNetConnect(uri, slot, password)
    local ap = client()
    if ap == nil then
        netLog("network module missing: the mod stays in local mode")
        return false
    end
    state.connecting = true
    state.refusal = nil
    state.refusalReasons = nil
    state.unreachableShown = false
    state.unreachableSince = nil
    -- After a refused seed, take every item again, from an empty inventory so nothing is counted twice.
    if state.seedRefused then
        if _G.apInventoryClear then pcall(_G.apInventoryClear) end
        state.lastItemIndex = -1
    end
    state.seedRefused = false
    -- lastItemIndex is kept: the server sends every item again on connect, and those already applied must
    -- not be applied twice. It starts over only with another seed or slot (apNetForgetItems).
    state.lastConnection = { uri = uri, slot = slot, password = password or "" }
    state.retries = 0
    state.retryAt = nil
    -- The Multiverse build is its own Archipelago game (apGameName comes with its data).
    if _G.apGameName and ap.SetGame ~= nil then
        pcall(function() ap:SetGame(tostring(apGameName)) end)
    end
    netLog("connecting to " .. tostring(uri) .. " (slot " .. tostring(slot) .. ")")
    return ap:Connect(uri, slot, password or "")
end

function apNetLastConnection()
    local ap = client()
    if ap == nil then
        return nil
    end
    local ok, uri, slot = pcall(function()
        return tostring(ap:LastUri()), tostring(ap:LastSlot())
    end)
    if not ok or uri == nil or uri == "" then
        return nil
    end
    return { uri = uri, slot = slot ~= "" and slot or nil }
end

function apNetRequestProfileReset()
    local ap = client()
    if ap == nil then
        return false
    end
    local ok, requested = pcall(function() return ap:RequestProfileReset() end)
    return ok and requested ~= false
end

function apNetRelaunchWhenClosed()
    local ap = client()
    if ap == nil then
        return false
    end
    local ok, planned = pcall(function() return ap:RelaunchWhenClosed() end)
    return ok and planned == true
end

function apNetProfileResetRequested()
    local ap = client()
    if ap == nil then
        return false
    end
    local ok, requested = pcall(function() return ap:ProfileResetRequested() end)
    return ok and requested == true
end

function apNetDisconnect()
    local ap = client()
    if ap ~= nil then
        ap:Disconnect()
    end
    state.connected = false
    state.lastConnection = nil
    state.retryAt = nil
    state.retries = 0
end

local function scheduleRetry()
    if state.lastConnection == nil then
        return
    end
    state.retries = state.retries + 1
    local delay = RETRY_DELAYS[math.min(state.retries, #RETRY_DELAYS)]
    state.retryAt = state.ticks + delay * 60
    netLog(string.format("reconnecting in %d s (attempt %d)", delay, state.retries))
    if _G.apNotifyStatus then
        _G.apNotifyStatus(apT("net.retrying", { n = delay }))
    end
end

local UNREACHABLE_DELAY = 6 * 60

local function announceIfStillUnreachable()
    if state.unreachableSince == nil then
        return
    end
    if state.connected then
        state.unreachableSince = nil
        return
    end
    if state.ticks - state.unreachableSince < UNREACHABLE_DELAY then
        return
    end
    state.unreachableSince = nil
    state.unreachableShown = true
    netLog("server still unreachable, the player has been warned")
    if _G.apNotifyStatus then
        -- After a link that worked, the address is not the problem: say what happens to the checks instead.
        _G.apNotifyStatus(apT(state.everConnected and "net.error.unreachable.lost" or "net.error.unreachable"))
    end
end

local function retryIfDue()
    if state.retryAt == nil or state.connected or state.ticks < state.retryAt then
        return
    end
    state.retryAt = nil
    local target = state.lastConnection
    if target == nil then
        return
    end
    local ap = client()
    if ap == nil then
        return
    end
    netLog("new connection attempt")
    state.connecting = true
    local ok = pcall(function()
        return ap:Connect(target.uri, target.slot, target.password)
    end)
    if not ok then
        scheduleRetry()
    end
end

function apNetAnnounceTags()
    return whenConnected(function(ap)
        local tags = Hyperspace.vector_string()
        if _G.apDeathLink and _G.apDeathLink.enabled then tags:push_back("DeathLink") end
        if _G.apTrapLink and _G.apTrapLink.enabled then tags:push_back("TrapLink") end
        local ok, sent = pcall(function() return ap:SetTags(tags) end)
        return ok and sent == true
    end)
end

-- reply: an answer to another FTL's announce, or a reminder; only a first announce asks the others to answer.
-- A library from before 0.6 beta.7 cannot announce: TrapLink then waits for a trap, as before.
function apNetAnnounceTrapLink(reply)
    return whenConnected(function(ap)
        if ap.AnnounceTrapLink == nil then
            return false
        end
        local ok, sent = pcall(function() return ap:AnnounceTrapLink(reply == true) end)
        return ok and sent == true
    end)
end

function apNetHintLocation(name)
    return whenConnected(function(ap)
        local ok, sent = pcall(function() return ap:HintLocation(name) end)
        return ok and sent == true
    end)
end

function apNetSendCheck(checkId)
    return whenConnected(function(ap) return ap:SendCheck(checkId) end)
end

function apNetSendDeath(cause)
    return whenConnected(function(ap) return ap:SendDeath(tostring(cause or "died")) end)
end

function apNetSendTrap(trapName)
    return whenConnected(function(ap) return ap:SendTrap(tostring(trapName or "Trap")) end)
end

-- nil when the library predates it (0.6 beta.17): the caller goes back to the whole link.
function apNetSendTrapTo(slot, trapName)
    local ap = client()
    if ap == nil or ap.SendTrapTo == nil then
        return nil
    end
    return whenConnected(function(linked) return linked:SendTrapTo(slot, tostring(trapName or "Trap")) end)
end

function apNetEnergyLinkDeposit(joules)
    return whenConnected(function(ap) return ap:EnergyDeposit(math.floor(joules)) end)
end

function apNetEnergyLinkRequest(joules)
    return whenConnected(function(ap) return ap:EnergyRequest(math.floor(joules)) end)
end

function apNetSendGoal()
    return whenConnected(function(ap)
        netLog("goal reached: StatusUpdate(GOAL)")
        return ap:SendGoal()
    end)
end

local UNKNOWN = "Unknown"

local CONSUMED_KEY = "ap_items_done"
local SEED_KEY_BASE = "ap_seed_tag"

-- Each save profile remembers its own seed: a save made for one seed asks again when another one connects.
-- The first save ("main", the only one before 0.6) keeps the old key.
local function seedKeyOf(profile)
    if profile == "main" then
        return SEED_KEY_BASE
    end
    return SEED_KEY_BASE .. "@" .. profile
end

local function seedKey()
    return seedKeyOf(_G.apSavesSupported and apSavesSupported() and apSavesCurrent() or "main")
end

local durableStore = nil

local function store()
    if durableStore ~= nil then
        return durableStore or nil
    end
    local ap = client()
    if ap == nil then return nil end
    local ok = pcall(function() return ap:RecallState(SEED_KEY_BASE) end)
    durableStore = ok and ap or false
    if not ok then
        netLog("network module has no durable memory: falling back to the FTL profile")
    end
    return durableStore or nil
end

function apNetForgetDurableStore()
    durableStore = nil
end

local function meta(key)
    local ap = store()
    if ap ~= nil then
        local ok, value = pcall(function() return ap:RecallState(key) end)
        if ok and value ~= nil and value ~= "" then return tonumber(value) or 0 end
    end
    local ok, value = pcall(function() return Hyperspace.metaVariables[key] end)
    return ok and tonumber(value) or 0
end

local function writeMeta(key, value)
    local ap = store()
    if ap ~= nil then
        pcall(function() ap:RememberState(key, tostring(value)) end)
    end
    pcall(function() Hyperspace.metaVariables[key] = value end)
end

function apNetSeedTag()
    return meta(seedKey())
end

function apNetSeedTagOf(profile)
    return meta(seedKeyOf(profile))
end

function apNetRecall(key)
    return meta(key)
end

function apNetRemember(key, value)
    writeMeta(key, value)
end

function apNetRememberText(key, value)
    local ap = store()
    if ap ~= nil then
        pcall(function() ap:RememberState(key, tostring(value)) end)
    end
end

function apNetRecallText(key)
    local ap = store()
    if ap == nil then return "" end
    local ok, value = pcall(function() return ap:RecallState(key) end)
    return ok and value ~= nil and tostring(value) or ""
end

-- The key of something kept per seed, for this slot. What an older version kept under the seed alone moves to the
-- slot of the save that played it, once: a slot on a save of its own never takes it.
function apNetSlotKey(base)
    local suffix = _G.apSlotSuffix and apSlotSuffix() or ""
    if suffix == "" then
        return base
    end
    local key = base .. suffix
    if _G.apSavesPredatesSlots and not apSavesPredatesSlots() then
        return key
    end
    local ap = store()
    if ap ~= nil then
        local ok, old = pcall(function() return ap:RecallState(base) end)
        if ok and old ~= nil and old ~= "" and old ~= "0" then
            if tostring(ap:RecallState(key) or "") == "" then
                ap:RememberState(key, old)
            end
            ap:RememberState(base, "")
            pcall(function() Hyperspace.metaVariables[base] = 0 end)
        end
    else
        local ok, old = pcall(function() return Hyperspace.metaVariables[base] end)
        if ok and tonumber(old) and tonumber(old) > 0 then
            if meta(key) == 0 then writeMeta(key, tonumber(old)) end
            writeMeta(base, 0)
        end
    end
    return key
end

-- Each seed keeps its own count of consumed items, so coming back to a seed played before does not hand out
-- its scrap and traps a second time.
local function consumedKey(fingerprint)
    return apNetSlotKey(CONSUMED_KEY .. "_" .. tostring(fingerprint or 0))
end

-- Older versions kept one count for whichever seed was current: it moves to that seed's own count.
local function migrateOldCount()
    local old = meta(CONSUMED_KEY)
    if old <= 0 then
        return
    end
    local tag = meta(seedKey())
    if meta(consumedKey(tag)) == 0 then
        writeMeta(consumedKey(tag), old)
    end
    writeMeta(CONSUMED_KEY, 0)
end

local function consumedFor(fingerprint)
    migrateOldCount()
    return meta(consumedKey(fingerprint))
end

-- Items delivered past the first one still waiting (a weapon held back for a few jumps) are kept too, or
-- the next session would hand out their scrap and traps again.
local function deliveredKey(fingerprint)
    return apNetSlotKey("ap_delivered_" .. tostring(fingerprint or 0))
end

local function saveDelivered(fingerprint)
    local list = {}
    for index in pairs(state.delivered) do
        list[#list + 1] = tostring(index)
    end
    -- Nothing held back is the usual case: write only when there is something, or when it just emptied.
    if #list == 0 and not state.deliveredSaved then
        return
    end
    table.sort(list)
    apNetRememberText(deliveredKey(fingerprint), table.concat(list, ","))
    state.deliveredSaved = #list > 0
end

local function loadDelivered(fingerprint)
    local delivered = {}
    for index in tostring(apNetRecallText(deliveredKey(fingerprint))):gmatch("%d+") do
        delivered[tonumber(index)] = true
    end
    state.deliveredSaved = next(delivered) ~= nil
    return delivered
end

function apNetRememberSeed(fingerprint)
    state.consumedUntil = consumedFor(fingerprint) - 1
    writeMeta(seedKey(), fingerprint or 0)
    state.delivered = loadDelivered(fingerprint)
    netLog("seed fingerprint recorded: " .. tostring(fingerprint))
end

function apNetForgetItems()
    state.lastItemIndex = -1
    state.itemNames = {}
end

function apNetForgetProgress(incoming)
    local current = meta(seedKey())
    writeMeta(consumedKey(current), 0)
    apNetRememberText(deliveredKey(current), "")
    if _G.apShopForgetOwed then apShopForgetOwed(current) end
    if incoming ~= nil then
        writeMeta(consumedKey(incoming), 0)
        apNetRememberText(deliveredKey(incoming), "")
        if _G.apShopForgetOwed then apShopForgetOwed(incoming) end
    end
    writeMeta(seedKey(), 0)
    writeMeta(CONSUMED_KEY, 0)
    state.consumedUntil = -1
    state.delivered = {}
    state.deliveredSaved = false
    netLog("Archipelago progress forgotten: the next seed starts from zero")
end

local function reloadConsumed()
    local fingerprint = _G.apSeedFingerprint and _G.apSeedFingerprint() or 0
    state.itemNames = {}
    state.consumedUntil = consumedFor(fingerprint) - 1
    state.delivered = loadDelivered(fingerprint)
    if meta(seedKey()) ~= fingerprint then
        writeMeta(seedKey(), fingerprint)
        if state.consumedUntil < 0 then
            netLog("new seed: resources already received start over from zero")
            return
        end
    end
    if state.consumedUntil >= 0 then
        netLog(string.format("%d resource(s) already consumed in previous sessions",
            state.consumedUntil + 1))
    end
end

local SCOUT_RETRY_TICKS = 3 * 60
local SCOUT_RETRIES = 20
-- A big multiworld can take minutes to send its data package: past the quick retries, ask again slowly, never
-- leaving the shop empty for good.
local SCOUT_SLOW_RETRY_TICKS = 30 * 60

local function scheduleRescout(message)
    if state.scoutRetryAt ~= nil then
        return
    end
    state.scoutRetries = (state.scoutRetries or 0) + 1
    local slow = state.scoutRetries > SCOUT_RETRIES
    state.scoutRetryAt = state.ticks + (slow and SCOUT_SLOW_RETRY_TICKS or SCOUT_RETRY_TICKS)
    if not slow or state.scoutRetries % 10 == 0 then
        netLog(message)
    end
end

-- The shop is still waiting for the server to say what it sells.
function apShopWaiting()
    return state.connected == true and (state.scoutsPending == true or state.scoutRetryAt ~= nil)
end

local function requestShopScouts()
    if not (_G.apShopSlotKeys and _G.apLocationNameFor) then
        return
    end
    local names = {}
    for _, key in ipairs(_G.apShopSlotKeys()) do
        local name = _G.apLocationNameFor(key)
        if name then
            names[#names + 1] = name
        end
    end
    local shopCount = #names
    -- A seed without a shop: what the shop held before (solo, the demo, another seed) must go.
    if shopCount == 0 and _G.apShopGiftsConfigure then
        pcall(_G.apShopGiftsConfigure, {})
    end
    -- The other checks too, so a check can say what it sends. A scout is not a hint: nobody else sees it.
    local others = {}
    for key, name in pairs((_G.apContractState or {}).locNames or {}) do
        if tostring(key):sub(1, 5) ~= "shop:" then
            others[#others + 1] = name
        end
    end
    table.sort(others)
    for _, name in ipairs(others) do
        names[#names + 1] = name
    end
    local ap = client()
    if #names == 0 or ap == nil then
        return
    end
    state.scoutsPending = shopCount > 0
    state.scouted = {}
    state.checkItems = {}
    local vector = Hyperspace.vector_string()
    for _, name in ipairs(names) do
        vector:push_back(name)
    end
    -- On a first connection to a seed the module does not know the location names yet: nothing goes out.
    local ok, accepted = pcall(function() return ap:ScoutLocations(vector) end)
    if not ok or accepted == false then
        scheduleRescout("shop not scouted, the data packet is not in yet: asked again in a few seconds")
        return
    end
    netLog(shopCount .. " shop slot(s) and " .. #others .. " other check(s) to scout")
end

local function onConnected(event)
    local wasRetrying = state.retries > 0
    state.connected = true
    state.everConnected = true
    state.connecting = false
    state.retries = 0
    state.retryAt = nil
    state.unreachableSince = nil
    netLog("connected as \"" .. tostring(event.name) .. "\"")
    state.ownAlias = tostring(event.name)
    state.seedRefused = false
    state.replayClean = false

    local slotData = event.extra
    if type(slotData) == "string" and _G.apJsonDecode then
        local decoded, err = _G.apJsonDecode(slotData)
        if decoded ~= nil then
            netLog("slot_data decoded: " .. #slotData .. " bytes of JSON")
            slotData = decoded
        else
            netLog("slot_data UNREADABLE (" .. #slotData .. " bytes): " .. tostring(err))
        end
    end

    if type(slotData) == "table" then
        netLog("slot_data received as a table")
        if _G.apApplySlotData then
            local accepted = _G.apApplySlotData(slotData, event.name)
            netLog(accepted ~= false and "seed accepted" or "SEED REFUSED (see [AP-contract])")
            state.seedRefused = accepted == false
        end
    else
        netLog("slot_data received as TEXT (" .. #tostring(event.extra) .. " bytes): "
            .. "the C++ module must turn it into a Lua table, nothing was applied")
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("net.slot_data_unreadable"))
        end
    end

    -- Said after the seed check: "nothing was lost" followed by a refusal would contradict itself.
    if _G.apNotifyStatus and not state.seedRefused then
        _G.apNotifyStatus(apT(wasRetrying and "net.reconnected" or "net.connected",
                              { slot = tostring(event.name) }))
    end

    if _G.apOnSlotData then
        pcall(_G.apOnSlotData, event.extra)
    end

    if not state.seedRefused then
        reloadConsumed()
        -- The save in use is this seed's: the Saves menu names it at once.
        if _G.apSavesDescribe then pcall(_G.apSavesDescribe) end
    end

    if not state.seedRefused then
        apNetAnnounceTags()
        if _G.apTrapLink and _G.apTrapLink.enabled then apNetAnnounceTrapLink(false) end
    end

    adoptServerChecks(true)

    if _G.apResendPendingChecks then
        pcall(_G.apResendPendingChecks)
    end
    if _G.apCombatCatchUp and not state.seedRefused then
        pcall(_G.apCombatCatchUp)
    end

    if _G.apDeclareGoal then
        pcall(_G.apDeclareGoal)
    end

    state.scoutRetries = 0
    state.scoutRetryAt = nil
    requestShopScouts()
end

local function classify(flags)
    flags = math.floor(flags or 0)
    if flags % 8 >= 4 then return "trap" end
    if flags % 2 == 1 then return "progression" end
    if flags % 4 >= 2 then return "useful" end
    return "filler"
end

local function onScout(event)
    -- Before the data package, names come as "Unknown" and the reply cannot be read: ask again a bit later.
    if tostring(event.name) == UNKNOWN or tostring(event.extra) == UNKNOWN then
        scheduleRescout("shop scouted before the data packet, asked again in a few seconds")
        return
    end
    local key = _G.apCheckKeyFor and _G.apCheckKeyFor(event.name) or event.name
    if tostring(key):sub(1, 5) ~= "shop:" then
        state.checkItems = state.checkItems or {}
        state.checkItems[key] = { item = tostring(event.extra), slot = tostring(event.sender),
                                  mine = state.ownAlias ~= nil and tostring(event.sender) == state.ownAlias,
                                  kind = classify(event.value) }
        return
    end
    state.scouted[#state.scouted + 1] = {
        location = key,
        slot = event.sender,
        item = event.extra,
        kind = classify(event.value),
        sphere = nil,
    }
end

-- Checks done elsewhere on this slot (another client, an admin) reach the client's list as the server
-- tells it: read it again now and then, not only when connecting.
adoptServerChecks = function(verbose)
    if not _G.apAdoptCheckedLocations then
        return
    end
    local ap = client()
    if ap == nil or ap.CheckedLocations == nil then
        return
    end
    local ok, names = pcall(function() return ap:CheckedLocations() end)
    if ok and names ~= nil then
        local list = {}
        for i = 0, names:size() - 1 do
            local name = tostring(names[i])
            if name ~= UNKNOWN then
                list[#list + 1] = name
            end
        end
        pcall(_G.apAdoptCheckedLocations, list)
    elseif verbose then
        netLog("CheckedLocations unavailable: the check counter starts over from zero")
    end
end

local CHECKED_POLL_TICKS = 10 * 60

-- The items already consumed are counted by seed and slot. A server whose list does not start with those
-- same items is another game on that seed name (a seed generated again with a fixed number, or hosted
-- again): its items would all pass for replays and its scrap, fuel and the like would be lost. The names of
-- the consumed items are kept as a signature and checked each time the server sends its list from the start.
local forgetStaleItems

local function signatureKey(fingerprint)
    return apNetSlotKey("ap_items_sig_" .. tostring(fingerprint or 0))
end

local function hashNames(names, count)
    local hash = 0
    for index = 0, count - 1 do
        local name = names[index]
        if name == nil then
            return nil
        end
        for position = 1, #name do
            hash = (hash * 31 + name:byte(position)) % 2147483647
        end
        hash = (hash * 31 + 7) % 2147483647
    end
    return hash
end

local function readSignature(fingerprint)
    local text = tostring(apNetRecallText(signatureKey(fingerprint)) or "")
    local count, hash = text:match("^(%d+):(%d+)$")
    return tonumber(count), tonumber(hash)
end

local function writeSignature(fingerprint, count)
    local hash = hashNames(state.itemNames, count)
    apNetRememberText(signatureKey(fingerprint), hash and (count .. ":" .. hash) or "")
end

-- The rest of the list from index 0, as it came in this batch: nil while a name is still unknown.
local function batchNames()
    local names = {}
    local expected = 0
    for position = state.batchPos or 1, #(state.batch or {}) do
        local event = state.batch[position]
        if tostring(event.kind) == "item" then
            if event.index ~= expected then break end
            if tostring(event.name) == UNKNOWN then return nil end
            names[expected] = tostring(event.name)
            expected = expected + 1
        end
    end
    return names, expected
end

forgetStaleItems = function()
    if state.consumedUntil < 0 or not _G.apNetRecallText then
        return
    end
    local names, count = batchNames()
    if names == nil then
        return
    end
    local fingerprint = _G.apSeedFingerprint and _G.apSeedFingerprint() or 0
    local consumed = state.consumedUntil + 1
    local storedCount, storedHash = readSignature(fingerprint)
    local stale = count < consumed
    if not stale and storedCount ~= nil and storedCount <= consumed and storedCount <= count then
        stale = hashNames(names, storedCount) ~= storedHash
    end
    if not stale then
        -- Saves from before the signature get one now, from the server's own list.
        if storedCount ~= consumed then
            for index = 0, consumed - 1 do state.itemNames[index] = names[index] end
            writeSignature(fingerprint, consumed)
        end
        return
    end
    netLog(string.format("the server's items do not match the %d already consumed for this seed and slot "
        .. "(server has %d): another game on the same seed name, its items start over from zero", consumed, count))
    writeMeta(consumedKey(fingerprint), 0)
    apNetRememberText(deliveredKey(fingerprint), "")
    apNetRememberText(signatureKey(fingerprint), "")
    if _G.apShopForgetOwed then apShopForgetOwed(fingerprint) end
    if _G.apJournalForget then pcall(_G.apJournalForget) end
    state.consumedUntil = -1
    state.delivered = {}
    state.deliveredSaved = false
    state.lastItemIndex = -1
end

local function onItem(event)
    -- The server sends the whole list again from index 0 on each connection: once a full list came in with
    -- every name, the inventory holds everything received so far.
    state.itemsInBatch = true
    if event.index == 0 then
        state.replayClean = true
    end
    if tostring(event.name) == UNKNOWN then
        state.replayClean = false
    end
    -- Every name counts for the "in logic" marker, also those already applied before a reconnect.
    if event.index >= 0 and tostring(event.name) ~= UNKNOWN and _G.apNoteReceived then
        _G.apNoteReceived(event.name, event.index)
    end
    if event.index >= 0 and tostring(event.name) ~= UNKNOWN then
        state.itemNames[event.index] = tostring(event.name)
    end
    if event.index == 0 and not state.seedRefused then
        forgetStaleItems()
    end
    if event.index >= 0 and event.index <= state.lastItemIndex then
        return
    end
    if tostring(event.name) == UNKNOWN then
        netLog("item received before the data packet, asked again once it is in")
        return
    end
    if event.index >= 0 then
        state.lastItemIndex = event.index
    end

    local isReplay = event.index >= 0 and (event.index <= state.consumedUntil or state.delivered[event.index] == true)

    if _G.apReceiveItem then
        local sender = tostring(event.sender)
        if sender == "" then
            sender = nil
        end
        _G.apReceiveItem(event.name, sender, isReplay, event.index)
    end
end

function apNetItemDelivered(index)
    index = tonumber(index)
    if index == nil or index < 0 or index <= state.consumedUntil then
        return false
    end
    state.delivered[index] = true
    local advanced = false
    while state.delivered[state.consumedUntil + 1] do
        state.consumedUntil = state.consumedUntil + 1
        state.delivered[state.consumedUntil] = nil
        advanced = true
    end
    local fingerprint = _G.apSeedFingerprint and _G.apSeedFingerprint() or 0
    if advanced then
        writeMeta(consumedKey(fingerprint), state.consumedUntil + 1)
        writeSignature(fingerprint, state.consumedUntil + 1)
    end
    saveDelivered(fingerprint)
    return advanced
end

local REFUSAL_KEYS = {
    InvalidSlot = "net.refused.slot",
    InvalidGame = "net.refused.game",
    InvalidPassword = "net.refused.password",
    IncompatibleVersion = "net.refused.version",
    InvalidItemsHandling = "net.refused.items",
}

local function onRefused(event)
    state.connecting = false
    state.connected = false
    state.unreachableSince = nil
    state.retryAt = nil
    state.retries = 0
    state.lastConnection = nil

    local reasons = tostring(event.extra or "")
    netLog("connection refused by the server: " .. (reasons ~= "" and reasons or "no reason given"))

    local said = {}
    for reason in reasons:gmatch("[^,]+") do
        reason = reason:match("^%s*(.-)%s*$")
        local key = REFUSAL_KEYS[reason]
        if key ~= nil then
            said[#said + 1] = apT(key)
        elseif reason ~= "" then
            said[#said + 1] = apT("net.refused.other", { reason = reason })
        end
    end
    if #said == 0 then
        said[1] = apT("net.refused.unknown")
    end
    state.refusal = said[1]
    state.refusalReasons = reasons
    if _G.apNotifyStatus then
        for _, line in ipairs(said) do
            _G.apNotifyStatus(line)
        end
    end
end

local ERROR_KEYS = {
    socket = "net.error.socket",
    location = "net.error.location",
    unreachable = "net.error.unreachable",
}

local HANDLERS = {
    connected = onConnected,
    refused = onRefused,
    item = onItem,
    scout = onScout,
    hint = function(event)
        if _G.apHintReceived then
            _G.apHintReceived({
                item = tostring(event.name),
                receiver = tostring(event.sender),
                finder = tostring(event.other),
                location = tostring(event.extra),
                found = tonumber(event.value) == 1,
                known = tonumber(event.index) == 1,
            })
        end
    end,

    disconnected = function()
        local wasConnected = state.connected
        state.connected = false
        state.connecting = false
        netLog("disconnected")
        if _G.apTrapLinkForgetPartner then apTrapLinkForgetPartner() end
        if wasConnected and _G.apNotifyStatus then
            _G.apNotifyStatus(apT("net.disconnected"))
        end
        scheduleRetry()
    end,

    -- A package bought with no room left aboard: the module kept it off the ship, the shop collects it.
    package_bought = function(event)
        if _G.apShopPackageBought then
            _G.apShopPackageBought(tostring(event.name))
        end
    end,

    -- FTL tried to unlock a ship by itself and the lock refused it.
    unlock_denied = function(event)
        if _G.apShipUnlockDenied then
            _G.apShipUnlockDenied(tostring(event.name))
        end
    end,

    death = function(event)
        if _G.apDeathLinkReceive then
            _G.apDeathLinkReceive(event.sender, event.name)
        end
    end,

    trap = function(event)
        if _G.apTrapLinkReceive then
            _G.apTrapLinkReceive(event.sender, event.name)
        end
    end,

    trap_partner = function(event)
        if _G.apTrapLinkPartner then
            _G.apTrapLinkPartner(event.sender, event.index == 1, event.value)
        end
    end,

    -- A reply to our own request carries what was taken (0 when the pool was empty); updates from others carry -1.
    -- A look at the pool (adding 0) also comes back with index 0: only a pending request is answered as one.
    -- Every reply carries the pool's new value, written last.
    energy = function(event)
        local state = _G.apEnergyLinkState
        local asked = state ~= nil and (state.pendingRequest or 0) > 0
        if event.index and event.index >= 0 and (event.index > 0 or asked) and _G.apEnergyLinkGranted then
            _G.apEnergyLinkGranted(event.index)
        end
        if _G.apEnergyLinkSync then
            _G.apEnergyLinkSync(event.value)
        end
    end,

    -- A line the module wants in the log (the CA bundle used, why TLS failed).
    log = function(event)
        netLog(tostring(event.extra))
    end,

    error = function(event)
        local token = tostring(event.name)
        if token == "unreachable" then
            netLog("unreachable for now: " .. tostring(event.extra))
            if not state.unreachableShown and state.unreachableSince == nil then
                state.unreachableSince = state.ticks
            end
            return
        end
        netLog("ERROR: " .. token
            .. (event.extra ~= "" and (" - " .. tostring(event.extra)) or ""))
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT(ERROR_KEYS[token] or "net.error.unknown"))
        end
    end,
}

local function drain()
    local ap = client()
    if ap == nil then
        return
    end

    local events = ap:TakeEvents()
    local count = events:size()
    if count == 0 then
        return
    end

    state.itemsInBatch = false
    state.batch = {}
    for i = 0, count - 1 do
        state.batch[i + 1] = events[i]
    end
    for i = 0, count - 1 do
        local event = events[i]
        state.batchPos = i + 1
        local handler = HANDLERS[tostring(event.kind)]
        if handler then
            local ok, err = pcall(handler, event)
            if not ok then
                netLog("error handling \"" .. tostring(event.kind) .. "\": " .. tostring(err))
            end
        end
    end
    if state.itemsInBatch and state.replayClean and state.connected and not state.seedRefused
        and _G.apInventoryMarkSynced then
        apInventoryMarkSynced()
    end

    if state.scoutsPending and #state.scouted > 0 then
        state.scoutsPending = false
        if _G.apShopGiftsScouted then
            local ok, err = pcall(_G.apShopGiftsScouted, state.scouted)
            if not ok then
                netLog("shop not configured after scouting: " .. tostring(err))
            end
        end
    end
end

local function rescoutIfDue()
    if state.scoutRetryAt ~= nil and state.ticks >= state.scoutRetryAt then
        state.scoutRetryAt = nil
        if state.connected then
            requestShopScouts()
            -- Checks made before the data packet could not go out either.
            if _G.apResendPendingChecks then
                pcall(_G.apResendPendingChecks)
            end
        end
    end
end

script.on_internal_event(Defines.InternalEvents.ON_TICK, function()
    state.ticks = state.ticks + 1
    drain()
    rescoutIfDue()
    retryIfDue()
    announceIfStillUnreachable()
    if state.connected and not state.seedRefused and state.ticks % CHECKED_POLL_TICKS == 0 then
        adoptServerChecks(false)
    end
end)

-- The module of an older build has none of these: they answer nil and the mod carries on as before.
local function moduleCall(method, ...)
    local ap = client()
    if ap == nil or ap[method] == nil then
        return nil
    end
    local args = { ... }
    local ok, result = pcall(function() return ap[method](ap, table.unpack(args)) end)
    if not ok then
        netLog(method .. " failed: " .. tostring(result))
        return nil
    end
    return result
end

-- Save profiles (module from 0.6 on): nil when the module is older and has none.
function apNetProfileCall(method, ...)
    return moduleCall(method, ...)
end

-- A library from before 0.6 beta.16 cannot grey out a store box: the rarities still do most of the work.
-- What the mod asked the module to keep out of the stores, for the self-test.
_G.apShopLocked = _G.apShopLocked or {}

function apNetShopLock(name, locked)
    apShopLocked[name] = (locked == true) or nil
    local ap = client()
    if ap == nil or ap.SetShopLock == nil then
        return false
    end
    moduleCall("SetShopLock", name, locked == true)
    return true
end

function apNetShopLockTip()
    local ap = client()
    if ap ~= nil and ap.SetShopLockTip ~= nil then
        moduleCall("SetShopLockTip", apT("shop.locked.tip"))
    end
end

function apNetClearShopLocks()
    local ap = client()
    if ap ~= nil and ap.ClearShopLocks ~= nil then
        moduleCall("ClearShopLocks")
    end
end

-- Whether the module can lock at all.
function apNetShipLock(on)
    local ap = client()
    if ap == nil or ap.SetShipLock == nil then
        return false
    end
    moduleCall("SetShipLock", on == true)
    return true
end

-- Unlocks a ship the lock lets through; nil when the module cannot.
function apNetUnlockShip(blueprint, silent)
    return moduleCall("UnlockShip", tostring(blueprint), silent == true)
end

function apNetLockShips(blueprints)
    local vector = Hyperspace.vector_string()
    for _, blueprint in ipairs(blueprints) do
        vector:push_back(blueprint)
    end
    return moduleCall("LockShips", vector)
end

-- FTL's own achievements: difficulty earned on, -1 if not, nil when the module cannot tell.
-- Hides or shows again an event's map label. Nil with a library older than 0.5.1.
function apNetHideBeaconLabel(eventName, hidden)
    return moduleCall("HideBeaconLabel", tostring(eventName), hidden == true)
end

function apNetAchievementStatus(name)
    return moduleCall("AchievementStatus", tostring(name))
end

-- The ship shown in the hangar ("" elsewhere), nil with a library that cannot tell.
function apNetHangarShip()
    return moduleCall("HangarShip")
end

-- The hangar button under the mouse ("start", "left", "right", "random", "list" or ""); nil with an older library.
function apNetHangarHover()
    return moduleCall("HangarHover")
end

-- Shows another ship in the hangar (its blueprint name), as the arrows would. Nil with an older library.
function apNetSwitchHangarShip(blueprint)
    return moduleCall("SwitchHangarShip", tostring(blueprint))
end

-- The system clipboard's first line, "" when empty or when the module cannot read it.
function apNetClipboard()
    local text = moduleCall("Clipboard")
    return text ~= nil and tostring(text) or ""
end

-- "windows" or "linux"; nil with a library older than 0.5.
function apNetPlatform()
    return moduleCall("Platform")
end

-- What a check sends, once the server answered the scout: { item, slot, mine }, or nil.
function apNetScoutedItem(key)
    return (state.checkItems or {})[key]
end

function apNetConnected()
    return state.connected == true
end

function apNetStatus()
    if client() == nil then
        netLog("network module MISSING (Hyperspace without the Archipelago patch)")
        return
    end
    netLog(string.format("network: %s | last item #%d | %d location(s) scouted",
        state.connected and "connected" or "offline",
        state.lastItemIndex, #state.scouted))
    if state.retryAt ~= nil then
        netLog(string.format("  reconnection scheduled in %.0f s (attempt %d)",
            math.max(0, state.retryAt - state.ticks) / 60, state.retries))
    end
end

state.available = client() ~= nil
-- From the very start: only Archipelago unlocks ships in this profile.
if apNetShipLock(true) then
    netLog("ship lock on: FTL's own ship unlocks are refused")
end
netLog(state.available
    and "network module present (console: LUA apNetStatus())"
    or "network module missing: the mod runs locally, everything else works")

]=], "@network.lua", "t", _ENV)
  if chunk == nil then
    print("SYNTAX ERROR in network.lua: " .. tostring(err))
    _G.__syntaxErrors = (_G.__syntaxErrors or 0) + 1
