do
  local chunk, err = load([=[
local TAG = "[AP-dash] "


local WINDOW = { x = 140, y = 56, w = 1000, h = 608 }
local HEADER_H = 46
local TAB_Y, TAB_H = 52, 30
local CONTENT_Y = 96
local FOOTER_H = 30
local PAD = 20
