do
  local chunk, err = load([=[
-- Set while FTL closes itself: nothing on the menu answers any more.
local quitting = nil

local TAG = "[AP-connect] "

local function connectLog(message)
    log(TAG .. message)
end

local ui = apUi

local PANEL = { x = 24, w = 372, bottom = 682 }
local PAD = 16
local ROW_H = 28
local LABEL_W = 100
local BUTTON_H = 28
local STATUS_H = 162
local QUESTION = { x = 320, y = 200, w = 640, h = 220 }
local QUESTION_BUTTON_H = 34

local FIELDS = {
    { key = "uri", label = "connect.field.address", value = "archipelago.gg", max = 40 },
    { key = "port", label = "connect.field.port", value = "38281", max = 5, digitsOnly = true },
    { key = "slot", label = "connect.field.slot", value = "", max = 24 },
    { key = "password", label = "connect.field.password", value = "", max = 24, masked = true },
}

local DEFAULTS = {}
for index, field in ipairs(FIELDS) do DEFAULTS[index] = field.value end

local FOCUS_INITIAL = 3
local focus = FOCUS_INITIAL
local message = nil
local attempt = nil
local messageTone = "dim"
local shiftHeld = false
local ctrlHeld = false
-- Fields the last refusal blames, drawn in red until they are edited.
local blamed = {}
-- Editing: the cursor of the focused field (nil = at the end), Ctrl+A's selection of the whole field, and
-- Backspace held down, which repeats like in any text box.
local selectAll = false
local backspaceFrames = nil
local BACKSPACE_DELAY, BACKSPACE_EVERY = 24, 3

local function cursorOf(field)
    if field.cursor == nil or field.cursor > #field.value then
        return #field.value
    end
    return field.cursor
end

local function insertText(field, text)
    if selectAll then
        field.value, field.cursor, selectAll = "", 0, false
    end
    local at = cursorOf(field)
    text = text:sub(1, math.max(0, field.max - #field.value))
    field.value = field.value:sub(1, at) .. text .. field.value:sub(at + 1)
    field.cursor = at + #text
end

local function deleteBack(field)
    if selectAll then
        field.value, field.cursor, selectAll = "", 0, false
        return
    end
    local at = cursorOf(field)
    if at > 0 then
        field.value = field.value:sub(1, at - 1) .. field.value:sub(at + 1)
        field.cursor = at - 1
    end
end

local function deleteForward(field)
    if selectAll then
        field.value, field.cursor, selectAll = "", 0, false
        return
    end
    local at = cursorOf(field)
    field.value = field.value:sub(1, at) .. field.value:sub(at + 2)
    field.cursor = at
end

local function setFocus(index)
    focus = index
    selectAll = false
    backspaceFrames = nil
end

local onMenu = false

local AUTO_KEY = "ap_autoconnect"
-- The password typed before a seed change relaunches FTL, kept for that one relaunch only.
local RELAUNCH_PASSWORD_KEY = "relaunch_password"
-- The player picked that seed's save: the next launch connects to it, automatic connection or not.
local RELAUNCH_CONNECT_KEY = "ap_relaunch_connect"
local autoTried = false
local soloTried = false

local function autoActive()
    if _G.apNetRecall then
        return _G.apNetRecall(AUTO_KEY) == 1
    end
    local ok, value = pcall(function()
        return Hyperspace.metaVariables[AUTO_KEY]
    end)
    return ok and value == 1
end

local soloQuestion = false

-- With save profiles, solo plays in its own save: starting it from another save asks first.
local soloProfileQuestion = false

local function soloNeedsItsSave()
    if not (_G.apSavesSupported and apSavesSupported()) or apSavesCurrent() == "solo" then
        return false
    end
    soloProfileQuestion = true
    _G.apSoloPending = true
    connectLog("solo asked from another save: its own save is offered")
    return true
end

local function toggleSolo()
    if not _G.apSoloEnabled and soloNeedsItsSave() then
        return
    end
    if _G.apSoloEnabled then
        connectLog("solo mode stopped from the panel")
        if _G.apSoloStop then _G.apSoloStop() end
    elseif _G.apSoloSaved and _G.apSoloSaved() then
        soloQuestion = true
    else
        connectLog("solo mode started from the panel")
        if _G.apSoloStart then _G.apSoloStart() end
    end
end

local function continueSolo()
    soloQuestion = false
    connectLog("saved solo run resumed from the panel")
    if _G.apSoloResume then _G.apSoloResume() end
end

local function restartSolo()
    soloQuestion = false
    connectLog("solo run restarted from the panel")
    if _G.apSoloStart then _G.apSoloStart(true) end
end

local function seedActive()
    return _G.apContractState ~= nil and _G.apContractState.connected == true
end

local function leaveSeed()
    message, messageTone = nil, "dim"
    if _G.apSoloEnabled then
        toggleSolo()
        return
    end
    connectLog("disconnected from the panel")
    if _G.apNetDisconnect then pcall(_G.apNetDisconnect) end
    if _G.apContractUnload then apContractUnload() end
end

local function toggleAuto()
    local newValue = autoActive() and 0 or 1
    if _G.apNetRemember then
        _G.apNetRemember(AUTO_KEY, newValue)
    else
        pcall(function()
            Hyperspace.metaVariables[AUTO_KEY] = newValue
        end)
    end
    connectLog("automatic connection: " .. (newValue == 1 and "enabled" or "disabled"))
end

local resetAsked = false

local function profilesOn()
    return _G.apSavesSupported ~= nil and apSavesSupported()
end

local function resetQuestionText()
    if profilesOn() then
        return apT(_G.apSoloPending and "reset.question.profile.solo" or "reset.question.profile")
    end
    local reason = _G.apSeedChangeReason and _G.apSeedChangeReason() or "seedchange"
    if reason == "foreign" then
        return apT("reset.question.foreign")
    end
    return apT("reset.question.seedchange")
end

local function resetQuestionOpen()
    if soloProfileQuestion then
        return true
    end
    if resetAsked then
        return false
    end
    if _G.apNetProfileResetRequested and _G.apNetProfileResetRequested() then
        return false
    end
    return _G.apSeedChangeLeftovers ~= nil and _G.apSeedChangeLeftovers() == true
end

local function acceptReset()
    resetAsked = true
    soloProfileQuestion = false
    local solo = _G.apSoloPending
    _G.apSoloPending = false
    local autoBefore = autoActive()
    local done
    if profilesOn() then
        -- Its own save for this seed (or for solo): the current one stays as it is, swapped at the next launch.
        local fingerprint = _G.apSeedChangeFingerprint and apSeedChangeFingerprint() or nil
        done = apSavesSwitch(apSavesIdFor(fingerprint, solo, _G.apSeedChangeSlot and apSeedChangeSlot() or nil))
    else
        done = _G.apNetRequestProfileReset and _G.apNetRequestProfileReset()
        if done and _G.apNetForgetProgress then
            _G.apNetForgetProgress(_G.apSeedChangeFingerprint and apSeedChangeFingerprint() or nil)
        end
        if done and solo and _G.apSoloForgetProgress then _G.apSoloForgetProgress(true) end
    end
    if autoBefore and _G.apNetRemember then _G.apNetRemember(AUTO_KEY, 1) end
    if done and not solo and _G.apNetRemember then _G.apNetRemember(RELAUNCH_CONNECT_KEY, 1) end
    if _G.apSeedChangeAcknowledged then _G.apSeedChangeAcknowledged() end
    if done then
        local relaunch = _G.apNetRelaunchWhenClosed and _G.apNetRelaunchWhenClosed() or false
        if relaunch and FIELDS[4].value ~= "" and _G.apNetRememberText then
            _G.apNetRememberText(RELAUNCH_PASSWORD_KEY, FIELDS[4].value)
        end
        local closingKey = profilesOn() and (relaunch and "saves.relaunch" or "saves.restart")
            or (relaunch and "reset.relaunch" or "reset.asked")
        message, messageTone = apT(closingKey), "good"
        connectLog((profilesOn() and "save switched for the next launch" or "profile erased, dated copy kept alongside")
            .. (relaunch and ", automatic relaunch planned" or ", relaunch by hand"))
        apQuitSoon(message, relaunch)
    else
        message, messageTone = apT("reset.failed"), "warn"
        connectLog("reset failed: nothing was erased, progress is kept")
    end
end

local function declineReset()
    if soloProfileQuestion then
        soloProfileQuestion = false
        _G.apSoloPending = false
        message, messageTone = apT("reset.kept.profile"), "dim"
        return
    end
    -- With save profiles, keeping means this save stays with its own seed: the other seed is not taken in.
    if profilesOn() then
        _G.apSoloPending = false
        if _G.apSeedChangeAcknowledged then _G.apSeedChangeAcknowledged() end
        if _G.apNetDisconnect then pcall(_G.apNetDisconnect) end
        message, messageTone = apT("reset.kept.profile"), "dim"
        connectLog("the save keeps its own seed: the other seed is not loaded")
        return
    end
    if _G.apSeedChangeFingerprint and _G.apNetRememberSeed then
        local fingerprint = _G.apSeedChangeFingerprint()
        if fingerprint ~= nil then _G.apNetRememberSeed(fingerprint) end
    end
    if _G.apSeedChangeAcknowledged then _G.apSeedChangeAcknowledged() end
    message, messageTone = apT("reset.kept"), "dim"
    connectLog("the player keeps their progress despite the seed change")
    if _G.apSoloPending then
        _G.apSoloPending = false
        if _G.apSoloSaved and _G.apSoloSaved() then
            if _G.apSoloResume then _G.apSoloResume() end
        elseif _G.apSoloStart then
            _G.apSoloStart()
        end
    elseif FIELDS[3].value ~= "" then
        apConnectNow()
    end
end

local function currentQuestion()
    if soloQuestion then
        local saved = _G.apSoloSaved and _G.apSoloSaved() or { done = 0, total = 0 }
        return { title = apT("question.solo.title"), text = apT("solo.question", saved),
                 yes = "solo.continue", yesTone = "good", accept = continueSolo,
                 no = "solo.restart", noTone = "warn", decline = restartSolo }
    end
    if resetQuestionOpen() then
        -- Starting solo from another save is not a seed change: the title says what is asked.
        return { title = apT(soloProfileQuestion and "question.solo_save.title" or "question.seed.title"),
                 text = resetQuestionText(),
                 yes = profilesOn() and "reset.yes.profile" or "reset.yes",
                 yesTone = profilesOn() and "good" or "warn", accept = acceptReset,
                 no = "reset.no", noTone = "dim", decline = declineReset }
    end
    return nil
end

-- A window of the home screen is open (the seed question, the Saves menu): the title and messages step aside.
function apConnectQuestionOpen()
    return currentQuestion() ~= nil or (_G.apSavesIsOpen ~= nil and apSavesIsOpen())
end

local function hangarOpen()
    local ok, closed = pcall(function()
        return Hyperspace.App.menu.bOpen ~= true
    end)
    if ok and closed then
        return true
    end
    local open = _G.apMenuSubScreen and _G.apMenuSubScreen()
    return open == true
end

local function geometry()
    local fieldsH = #FIELDS * ROW_H
    local height = 44 + fieldsH + 24 + BUTTON_H + 78
    local top = PANEL.bottom - height
    local g = { panel = { x = PANEL.x, y = top, w = PANEL.w, h = height }, fields = {} }
    local y = top + 40
    for index = 1, #FIELDS do
        g.fields[index] = { x = PANEL.x + PAD + LABEL_W, y = y, w = PANEL.w - PAD * 2 - LABEL_W, h = 22 }
        y = y + ROW_H
    end
    g.auto = { x = PANEL.x + PAD, y = y + 2, w = PANEL.w - PAD * 2, h = 16 }
    y = y + 24
    local primaryW = math.floor((PANEL.w - PAD * 2 - 10) * 0.55)
    g.button = { x = PANEL.x + PAD, y = y, w = primaryW, h = BUTTON_H }
    g.solo = { x = PANEL.x + PAD + primaryW + 10, y = y, w = PANEL.w - PAD * 2 - primaryW - 10, h = BUTTON_H }
    g.message = { x = PANEL.x + PAD, y = y + BUTTON_H + 10, w = PANEL.w - PAD * 2 }
    g.status = { x = PANEL.x, y = PANEL.bottom - STATUS_H, w = PANEL.w, h = STATUS_H }
    g.leave = { x = PANEL.x + PAD, y = PANEL.bottom - PAD - BUTTON_H, w = PANEL.w - PAD * 2, h = BUTTON_H }
    g.question = QUESTION
    local buttonsTop = QUESTION.y + QUESTION.h - QUESTION_BUTTON_H - 18
    local buttonWidth = math.floor((QUESTION.w - 3 * 18) / 2)
    g.resetYes = { x = QUESTION.x + 18, y = buttonsTop, w = buttonWidth, h = QUESTION_BUTTON_H }
    g.resetNo = { x = QUESTION.x + 36 + buttonWidth, y = buttonsTop, w = buttonWidth, h = QUESTION_BUTTON_H }
    g.shortcuts = PANEL.bottom - 34
    g.saves = { x = PANEL.x + PANEL.w - PAD - 110, y = g.auto.y - 4, w = 110, h = 22 }
    g.savesStatus = { x = PANEL.x + PANEL.w - PAD - 110, y = PANEL.bottom - STATUS_H + 10, w = 110, h = 22 }
    return g
end

local function inside(box, x, y)
    return x >= box.x and x <= box.x + box.w
        and y >= box.y and y <= box.y + box.h
end

local function displayValue(field)
    if field.masked then
        return string.rep("*", #field.value)
    end
    return field.value
end

local function drawQuestion(question)
    local g = geometry()
    local q = g.question
    ui.shade()
    ui.window(q.x, q.y, q.w, q.h, "warn")
    ui.text(13, q.x + 24, q.y + 20, q.w - 48, "warn", question.title)
    ui.rect(q.x + 24, q.y + 46, q.w - 48, 1, "faint")
    ui.wrapped(10, q.x + 24, q.y + 60, q.w - 48, "text", question.text)
    ui.button(g.resetYes, apT(question.yes), question.yesTone == "warn" and "danger" or "primary")
    ui.button(g.resetNo, apT(question.no), "secondary")
end

local function drawForm()
    local g = geometry()
    local p = g.panel
    ui.rect(p.x, p.y, p.w, p.h, "window", 0.94)
    ui.rect(p.x, p.y, p.w, 2, "border")
    ui.text(10, p.x + PAD, p.y + 14, p.w - PAD * 2, "title", apT("connect.title"))

    for index, field in ipairs(FIELDS) do
        local box = g.fields[index]
        local focused = index == focus
        local wrong = blamed[index] == true
        ui.text(9, p.x + PAD, box.y + 5, LABEL_W - 8, wrong and "bad" or (focused and "text" or "dim"), apT(field.label))
        ui.rect(box.x, box.y, box.w, box.h, focused and "hover" or "card")
        ui.outline(box.x, box.y, box.w, box.h, wrong and "bad" or (focused and "border" or "faint"), 1)
        local value = displayValue(field)
        if focused and selectAll and value ~= "" then
            ui.rect(box.x + 6, box.y + 3, math.min(box.w - 12, ui.width(10, value) + 4), box.h - 6, "border")
        end
        ui.text(10, box.x + 8, box.y + 5, box.w - 16, focused and "title" or "text", value)
        if focused and not selectAll then
            local caret = ui.width(10, value:sub(1, cursorOf(field)))
            ui.rect(box.x + 8 + math.min(caret, box.w - 18), box.y + 4, 1, box.h - 8, "title")
        end
    end

    if profilesOn() then
        ui.button(g.saves, apT("saves.button"), "secondary")
    end
    ui.checkbox(g.auto.x, g.auto.y, autoActive(), apT("connect.auto"), g.auto.w - (profilesOn() and 120 or 0))
    ui.button(g.button, apT(attempt ~= nil and "connect.button.busy" or "connect.button"), "primary", attempt ~= nil)
    ui.button(g.solo, apT("connect.solo"), "secondary")

    -- How to paste is said once, with the other keys below.
    if message ~= nil then
        ui.wrapped(9, g.message.x, g.message.y, g.message.w, messageTone, message)
    end
    ui.wrapped(9, p.x + PAD, g.shortcuts, p.w - PAD * 2, "dim", apT("connect.keys"))
end

local function drawStatus()
    local g = geometry()
    local s = g.status
    local solo = _G.apSoloEnabled == true
    local online = _G.apNetConnected and apNetConnected()
    ui.rect(s.x, s.y, s.w, s.h, "window", 0.94)
    ui.rect(s.x, s.y, s.w, 2, solo and "good" or (online and "good" or "warn"))

    local status
    if solo then
        status = apT("dash.status.solo")
    elseif online then
        status = apT("dash.status.online", { slot = tostring(_G.apOwnSlotName and apOwnSlotName() or "?") })
    else
        status = apT("dash.status.offline")
    end
    ui.text(12, s.x + PAD, s.y + 14, s.w - PAD * 2, "title", status)

    local counts = _G.apCheckCount and apCheckCount() or { sent = 0, total = 0 }
    if counts.total > 0 then
        local line = apT("dash.checks.count", { done = counts.sent, total = counts.total })
        ui.text(10, s.x + PAD, s.y + 44, s.w - PAD * 2 - 60, "text", apT("dash.checks.title") .. "  " .. line)
        ui.textRight(10, s.x + s.w - PAD, s.y + 44, 60, "dim",
            apT("dash.percent", { n = math.floor(100 * counts.sent / counts.total) }))
        ui.bar(s.x + PAD, s.y + 62, s.w - PAD * 2, 5, counts.sent / counts.total,
            counts.sent >= counts.total and "good" or "border")
    end
    if _G.apSeedSummaryLine then
        ui.text(9, s.x + PAD, s.y + 76, s.w - PAD * 2, "dim", apSeedSummaryLine())
    end
    ui.text(9, s.x + PAD, s.y + 94, s.w - PAD * 2, "dim", apT("connect.keys.run"))
    ui.button(g.leave, apT(solo and "connect.solo.stop" or "connect.disconnect"), "secondary")
    if profilesOn() then
        ui.button(g.savesStatus, apT("saves.button"), "secondary")
    end
end

local function resumeLast()
    local kept = _G.apNetRecallText and _G.apNetRecallText(RELAUNCH_PASSWORD_KEY) or ""
    if kept ~= "" then
        FIELDS[4].value = kept
        _G.apNetRememberText(RELAUNCH_PASSWORD_KEY, "")
    end
    if _G.apNetLastConnection == nil then
        return
    end
    local ok, last = pcall(_G.apNetLastConnection)
    if not ok or last == nil then
        return
    end
    local uri = tostring(last.uri):gsub("^wss?://", "")
    local address, port = uri:match("^(.*):(%d+)$")
    if address == nil then
        address, port = uri, nil
    end
    if address ~= "" then FIELDS[1].value = address end
    if port then FIELDS[2].value = port end
    if last.slot then
        FIELDS[3].value = last.slot
        focus = 4
    end
    local place = _G.apSavesLastPlace and apSavesLastPlace() or nil
    if place ~= nil then
        FIELDS[3].value = place.slot
        focus = 4
        if place.uri ~= "" then FIELDS[1].value = place.uri end
        if place.port ~= "" then FIELDS[2].value = place.port end
    end
end

local connectedMessage = nil
local shownRefusal = nil

local function followAttempt()
    local contract = _G.apContractState
    -- A reconnection happens without a click: its outcome must replace a "connected" left from before.
    if attempt == nil then
        local refusal = contract ~= nil and contract.refusal or nil
        -- Shown once when it appears, so the answers to the question that follows are not written over.
        if refusal ~= nil and refusal ~= shownRefusal then
            message, messageTone = apT("contract.refused", { reason = refusal }), "warn"
        elseif connectedMessage ~= nil and message == connectedMessage
            and not (_G.apNetConnected and _G.apNetConnected()) then
            message, messageTone, connectedMessage = nil, "dim", nil
        end
        shownRefusal = refusal
        return
    end
    if contract ~= nil and contract.refusal ~= nil then
        message, messageTone = apT("contract.refused", { reason = contract.refusal }), "warn"
        shownRefusal = contract.refusal
        attempt = nil
    elseif _G.apNetConnected and _G.apNetConnected() and contract ~= nil and contract.connected then
        message, messageTone = apT("net.connected", { slot = attempt.slot }), "good"
        connectedMessage = message
        attempt = nil
    elseif _G.apNetState ~= nil and _G.apNetState.refusal ~= nil then
        message, messageTone = _G.apNetState.refusal, "warn"
        local reasons = tostring(_G.apNetState.refusalReasons or "")
        blamed = { [3] = reasons:find("InvalidSlot", 1, true) ~= nil or nil,
                   [4] = reasons:find("InvalidPassword", 1, true) ~= nil or nil }
        attempt = nil
    elseif _G.apNetState ~= nil and _G.apNetState.unreachableShown then
        message, messageTone = apT("net.error.unreachable"), "warn"
        blamed = { [1] = true, [2] = true }
        attempt = nil
    end
end

function apConnectResetAutoForTesting()
    autoTried = false
    onMenu = false
end

function apConnectNow()
    local values = {}
    for _, field in ipairs(FIELDS) do values[field.key] = field.value end
    -- Slot names can hold spaces, but not at either end: a stray one would only make the server refuse.
    values.uri = values.uri:match("^%s*(.-)%s*$"):gsub("/+$", "")
    values.slot = values.slot:match("^%s*(.-)%s*$")

    if values.slot == "" then
        message, messageTone = apT("connect.need_slot"), "warn"
        return false
    end

    -- The room page shows "archipelago.gg:54321": pasted whole into the address, its port wins over the field.
    local address = values.uri
    if values.port ~= "" and not address:match(":%d+$") then
        address = address .. ":" .. values.port
    end
    -- A local server has no TLS: without a scheme the secure attempt fails first, slowly enough on some
    -- machines to warn "not answering" before the plain one connects.
    local target = address
    local host = address:lower():match("^([^:/]+)") or ""
    if not address:find("://", 1, true) and (host == "localhost" or host == "127.0.0.1") then
        target = "ws://" .. address
    end

    connectLog("attempting to " .. address .. ", slot " .. values.slot)
    blamed = {}
    if _G.apContractState then
        _G.apContractState.refusal = nil
    end

    local ok = false
    if _G.apNetConnect then
        local succeeded, result = pcall(_G.apNetConnect, target, values.slot, values.password)
        ok = succeeded and result ~= false
    end

    if ok then
        message, messageTone = apT("connect.trying", { uri = address }), "good"
        attempt = { slot = values.slot }
    else
        attempt = nil
        message, messageTone = apT("connect.no_module"), "warn"
    end
    return ok
end

function apConnectResetForTesting()
    attempt = nil
    for index, field in ipairs(FIELDS) do
        field.value = DEFAULTS[index]
    end
    focus, message, messageTone, shiftHeld, ctrlHeld, blamed = FOCUS_INITIAL, nil, "dim", false, false, {}
    selectAll, backspaceFrames = false, nil
    for _, field in ipairs(FIELDS) do field.cursor = nil end
    onMenu = false
    autoTried = false
    soloTried = false
    soloQuestion = false
    resetAsked = false
end

function apConnectState()
    local state = { focus = focus, message = message, onMenu = onMenu }
    for _, field in ipairs(FIELDS) do state[field.key] = field.value end
    return state
end

local WITH_SHIFT = {
    [Defines.SDL.KEY_SPACE] = " ",
    [Defines.SDL.KEY_SEMICOLON] = ":",
    [Defines.SDL.KEY_MINUS] = "_",
    [Defines.SDL.KEY_SLASH] = "?",
    [Defines.SDL.KEY_PERIOD] = ">",
}
local WITHOUT_SHIFT = {
    [Defines.SDL.KEY_SPACE] = " ",
    [Defines.SDL.KEY_COLON] = ":",
    [Defines.SDL.KEY_KP_PERIOD] = ".",
    [Defines.SDL.KEY_KP_MINUS] = "-",
    [Defines.SDL.KEY_PERIOD] = ".",
    [Defines.SDL.KEY_MINUS] = "-",
    [Defines.SDL.KEY_SLASH] = "/",
    [Defines.SDL.KEY_SEMICOLON] = ";",
}

local function character(key)
    if key >= Defines.SDL.KEY_a and key <= Defines.SDL.KEY_z then
        local letter = string.char(key)
        return shiftHeld and letter:upper() or letter
    end
    if key >= Defines.SDL.KEY_0 and key <= Defines.SDL.KEY_9 then
        return string.char(key)
    end
    if key >= Defines.SDL.KEY_KP0 and key <= Defines.SDL.KEY_KP9 then
        return tostring(key - Defines.SDL.KEY_KP0)
    end
    local keyMap = shiftHeld and WITH_SHIFT or WITHOUT_SHIFT
    return keyMap[key]
end

-- Ctrl+V puts the clipboard in the field. An address copied with its port, or the room page's whole
-- "/connect archipelago.gg:54321", fills both fields.
local function paste()
    local text = (_G.apNetClipboard and apNetClipboard() or ""):match("^%s*(.-)%s*$")
    text = text:gsub("^/connect%s+", "")
    local empty = apT(_G.apNetPlatform and apNetPlatform() == "linux" and "connect.paste_empty.linux"
        or "connect.paste_empty")
    if text == "" then
        message, messageTone = empty, "warn"
        return
    end
    if message == apT("connect.paste_empty") or message == apT("connect.paste_empty.linux") then
        message, messageTone = nil, "dim"
    end
    local field = FIELDS[focus]
    if field.key == "uri" or field.key == "port" then
        local bare = text:gsub("^wss?://", ""):gsub("/+$", "")
        -- Whatever follows the port (a path, a password, a sentence) stays out of both fields.
        local host, port = bare:match("^([^%s:/]+):(%d+)")
        if host ~= nil then
            FIELDS[1].value, FIELDS[2].value = host:sub(1, FIELDS[1].max), port:sub(1, FIELDS[2].max)
            blamed[1], blamed[2] = nil, nil
            return
        end
        if field.key == "uri" then text = bare end
    end
    if field.digitsOnly then text = text:gsub("%D", "") end
    -- At the cursor, like any text box; with Ctrl+A first, in place of the whole field.
    insertText(field, text)
    blamed[focus] = nil
end

script.on_internal_event(Defines.InternalEvents.ON_KEY_UP, function(key)
    if key == Defines.SDL.KEY_LSHIFT or key == Defines.SDL.KEY_RSHIFT then
        shiftHeld = false
    end
    if key == Defines.SDL.KEY_LCTRL or key == Defines.SDL.KEY_RCTRL then
        ctrlHeld = false
    end
    if key == Defines.SDL.KEY_BACKSPACE then
        backspaceFrames = nil
    end
    return Defines.Chain.CONTINUE
end)

script.on_internal_event(Defines.InternalEvents.ON_KEY_DOWN, function(key)
    if quitting then
        return Defines.Chain.PREEMPT
    end
    -- A question stands until it is answered: nothing behind it answers.
    if onMenu and currentQuestion() ~= nil then
        return Defines.Chain.PREEMPT
    end
    if not onMenu or seedActive() then
        return Defines.Chain.CONTINUE
    end
    if key == Defines.SDL.KEY_LSHIFT or key == Defines.SDL.KEY_RSHIFT then
        shiftHeld = true
        return Defines.Chain.CONTINUE
    end
    if key == Defines.SDL.KEY_LCTRL or key == Defines.SDL.KEY_RCTRL then
        ctrlHeld = true
        return Defines.Chain.CONTINUE
    end
    if ctrlHeld and key == Defines.SDL.KEY_v then
        paste()
        return Defines.Chain.PREEMPT
    end
    if ctrlHeld and key == Defines.SDL.KEY_a then
        selectAll = true
        return Defines.Chain.PREEMPT
    end

    if key == Defines.SDL.KEY_TAB or key == Defines.SDL.KEY_DOWN then
        setFocus(focus % #FIELDS + 1)
        return Defines.Chain.PREEMPT
    end
    if key == Defines.SDL.KEY_UP then
        setFocus((focus - 2) % #FIELDS + 1)
        return Defines.Chain.PREEMPT
    end
    local field = FIELDS[focus]
    if key == Defines.SDL.KEY_LEFT or key == Defines.SDL.KEY_RIGHT then
        local at = selectAll and (key == Defines.SDL.KEY_LEFT and 0 or #field.value) or cursorOf(field)
        if not selectAll then
            at = at + (key == Defines.SDL.KEY_LEFT and -1 or 1)
        end
        field.cursor = math.max(0, math.min(#field.value, at))
        selectAll = false
        return Defines.Chain.PREEMPT
    end
    if key == Defines.SDL.KEY_HOME or key == Defines.SDL.KEY_END then
        field.cursor = key == Defines.SDL.KEY_HOME and 0 or #field.value
        selectAll = false
        return Defines.Chain.PREEMPT
    end
    if key == Defines.SDL.KEY_DELETE then
        blamed[focus] = nil
        deleteForward(field)
        return Defines.Chain.PREEMPT
    end
    if key == Defines.SDL.KEY_RETURN or key == Defines.SDL.KEY_KP_ENTER then
        apConnectNow()
        return Defines.Chain.PREEMPT
    end
    if key == Defines.SDL.KEY_BACKSPACE then
        blamed[focus] = nil
        deleteBack(field)
        backspaceFrames = 0
        return Defines.Chain.PREEMPT
    end

    local c = character(key)
    if c ~= nil then
        -- On a French keyboard the dot is Shift and the ";" key, which reads as ":" here. An address has no
        -- use for a colon (the port has its own field), so there it is a dot.
        if field.key == "uri" and c == ":" and key == Defines.SDL.KEY_SEMICOLON then
            c = "."
        end
        if field.digitsOnly and not c:match("%d") then
            return Defines.Chain.PREEMPT
        end
        insertText(field, c)
        blamed[focus] = nil
        return Defines.Chain.PREEMPT
    end
    return Defines.Chain.CONTINUE
end)

script.on_internal_event(Defines.InternalEvents.ON_MOUSE_L_BUTTON_DOWN, function(x, y)
    if quitting then
        return Defines.Chain.PREEMPT
    end
    if not onMenu then
        return Defines.Chain.CONTINUE
    end
    x, y = apMousePosition(x, y)
    if _G.apSavesClick and apSavesClick(x, y) then
        return Defines.Chain.PREEMPT
    end
    local g = geometry()
    local question = currentQuestion()
    if question ~= nil then
        if inside(g.resetYes, x, y) then
            question.accept()
            return Defines.Chain.PREEMPT
        end
        if inside(g.resetNo, x, y) then
            question.decline()
            return Defines.Chain.PREEMPT
        end
        return Defines.Chain.PREEMPT
    end
    if question == nil and profilesOn() and inside(seedActive() and g.savesStatus or g.saves, x, y) then
        apSavesOpen()
        return Defines.Chain.PREEMPT
    end
    if seedActive() then
        if inside(g.leave, x, y) then
            leaveSeed()
            return Defines.Chain.PREEMPT
        end
        return Defines.Chain.CONTINUE
    end
    for index, box in ipairs(g.fields) do
        if inside(box, x, y) then
            setFocus(index)
            return Defines.Chain.PREEMPT
        end
    end
    if inside(g.button, x, y) then
        apConnectNow()
        return Defines.Chain.PREEMPT
    end
    if inside(g.auto, x, y) then
        toggleAuto()
        return Defines.Chain.PREEMPT
    end
    if inside(g.solo, x, y) then
        toggleSolo()
        return Defines.Chain.PREEMPT
    end
    return Defines.Chain.CONTINUE
end)

script.on_init(function() onMenu = false end)
script.on_internal_event(Defines.InternalEvents.JUMP_ARRIVE, function()
    onMenu = false
    return Defines.Chain.CONTINUE
end)

-- FTL draws nothing more once it is told to close: the player gets the time to read why the game goes away.
local QUIT_AFTER_SECONDS = 2

local quitAfterSeconds = QUIT_AFTER_SECONDS

function apQuitDelayForTesting(seconds)
    quitAfterSeconds = seconds
end

local function frameSeconds()
    local ok, factor = pcall(function() return Hyperspace.FPS.SpeedFactor end)
    factor = ok and tonumber(factor) or nil
    return (factor and factor > 0) and math.min(factor * 0.0625, 0.25) or 1 / 60
end

local function drawQuitting()
    local w, h = 620, 96
    local x, y = math.floor((1280 - w) / 2), math.floor((720 - h) / 2)
    apUi.rect(0, 0, 1280, 720, "shade")
    apUi.rect(x, y, w, h, "window")
    apUi.outline(x, y, w, h, "border", 2)
    apUi.wrapped(12, x + 20, y + 18, w - 40, "title", quitting.text)
    if quitting.relaunch then
        apUi.text(10, x + 20, y + h - 26, w - 40, "dim", apT("restart.wait"))
    end
end

local function followQuit()
    pcall(drawQuitting)
    quitting.age = quitting.age + frameSeconds()
    if quitting.age >= quitAfterSeconds then
        if _G.apNetDisconnect then pcall(_G.apNetDisconnect) end
        local closed = pcall(function() Hyperspace.App:OnExit() end)
        connectLog(closed and "game close requested" or "close failed, do it by hand")
        quitting = nil
    end
end

function apQuitSoon(text, relaunch)
    quitting = { text = tostring(text), relaunch = relaunch == true, age = 0 }
    if quitAfterSeconds == 0 then
        followQuit()
    end
end

script.on_render_event(
    Defines.RenderEvents.MAIN_MENU,
    function() end,
    function()
        if quitting then
            followQuit()
            return
        end
        if not onMenu then
            pcall(resumeLast)

            if not soloTried then
                soloTried = true
                if _G.apSoloWasActive and _G.apSoloWasActive() and not seedActive() then
                    connectLog("solo run active at the last session: resuming")
                    pcall(_G.apSoloResume)
                end
            end

            local chosen = _G.apNetRecall ~= nil and _G.apNetRecall(RELAUNCH_CONNECT_KEY) == 1
            if chosen then _G.apNetRemember(RELAUNCH_CONNECT_KEY, 0) end
            if not autoTried and (autoActive() or chosen) and not seedActive() then
                autoTried = true
                local state = apConnectState()
                if state.slot ~= "" then
                    connectLog("automatic connection: " .. state.uri .. ":" .. state.port)
                    pcall(apConnectNow)
                end
            end
        end
        pcall(followAttempt)
        if hangarOpen() then
            onMenu = false
            return
        end
        onMenu = true

        -- Backspace held: after a short wait, one more character goes every few frames.
        if backspaceFrames ~= nil then
            backspaceFrames = backspaceFrames + 1
            if backspaceFrames >= BACKSPACE_DELAY and (backspaceFrames - BACKSPACE_DELAY) % BACKSPACE_EVERY == 0 then
                deleteBack(FIELDS[focus])
            end
        end

        local question = currentQuestion()
        if seedActive() then
            pcall(drawStatus)
        else
            pcall(drawForm)
        end
        if question ~= nil then
            pcall(drawQuestion, question)
        elseif _G.apSavesDraw then
            apSavesDraw()
        end
    end
)

connectLog("connection panel loaded (home screen)")

]=], "@connect.lua", "t", _ENV)
  if chunk == nil then
    print("SYNTAX ERROR in connect.lua: " .. tostring(err))
    _G.__syntaxErrors = (_G.__syntaxErrors or 0) + 1
  else
    local ok, runErr = pcall(chunk)
    if not ok then
      print("LOAD ERROR in connect.lua: " .. tostring(runErr))
      _G.__loadErrors = (_G.__loadErrors or 0) + 1
    end
  end
end

do
  local chunk, err = load([=[
local TAG = "[AP-menu] "

local function menuLog(message)
    log(TAG .. message)
end

local ui = apUi

local PANEL = { x = 190, y = 86, w = 900, h = 548 }
local COLUMN_GAP = 16
local COLUMN_TOP = 90
local COLUMN_BOTTOM = 70
local ROW_H = 48
local ICON_W = 64
local ROW_GAP = 6
local LIST_OFFSET = 44
local PAGER_H = 24
local DONE_BUTTON = { w = 220, h = 34 }
local CATEGORIES = { "weapon", "drone", "crew" }
-- With System Install, received systems that do not all fit get a fourth column: the player picks.
local ALL_CATEGORIES = { "weapon", "drone", "crew", "system" }
local COLUMN_KEYS = {
    weapon = "loadout.column.weapon", drone = "loadout.column.drone", crew = "loadout.column.crew",
    system = "loadout.column.system",
}
local EMPTY_KEYS = {
    weapon = "loadout.empty.weapon", drone = "loadout.empty.drone", crew = "loadout.empty.crew",
    system = "loadout.empty.system",
}
local SKILL_KEYS = {
    pilot = "crew.skill.pilot", engines = "crew.skill.engines", shields = "crew.skill.shields",
    weapons = "crew.skill.weapons", repair = "crew.skill.repair", combat = "crew.skill.combat",
}

local LOGO = "ap_logo.png"
local LOGO_SIZE = 30

local pending = false
local logoTexture = nil
local open = false
local resumed = false
local taken = {}
local pages = {}
local hoveredEntry = nil

-- Kept in the run's save, so quitting to the main menu before choosing does not lose the menu.
local function remember(key, value)
    pcall(function() Hyperspace.playerVariables["ap_loadout_" .. key] = value end)
end

local function recalled(key)
    local ok, value = pcall(function() return Hyperspace.playerVariables["ap_loadout_" .. key] end)
    return ok and value == 1
end

-- A run started under another seed gets nothing from this one.
local function runCounts()
    local contract = _G.apContractState
    if _G.apRunMatchesSeed == nil or contract == nil or contract.connected ~= true then
        return true
    end
    return apRunMatchesSeed()
end

local function blueprintTitle(name, family)
    local ok, text = pcall(function()
        local blueprints = Hyperspace.Blueprints
        local bp = family == "weapon" and blueprints:GetWeaponBlueprint(name)
            or blueprints:GetDroneBlueprint(name)
        return bp.desc.title:GetText()
    end)
    if ok and type(text) == "string" and text ~= "" then
        return text
    end
    return _G.apHumaniseId and _G.apHumaniseId(name) or tostring(name)
end

-- What the game tells about a weapon or a drone: its power, and for a weapon its damage, shots, charge time
-- and missile use, plus the store's description. Read from the blueprint, nil when it cannot be read.
local function blueprintInfo(name, family)
    local ok, info = pcall(function()
        local blueprints = Hyperspace.Blueprints
        local bp = family == "weapon" and blueprints:GetWeaponBlueprint(name) or blueprints:GetDroneBlueprint(name)
        local result = { power = math.floor(tonumber(bp.power) or 0), text = bp.desc.description:GetText() }
        if family == "weapon" then
            result.damage = math.floor(tonumber(bp.damage.iDamage) or 0)
            result.shots = math.floor(tonumber(bp.shots) or 1)
            result.cooldown = math.floor((tonumber(bp.cooldown) or 0) + 0.5)
            result.missiles = math.floor(tonumber(bp.missiles) or 0)
        end
        return result
    end)
    return ok and info or nil
end

local function statsLine(entry, family)
    local info = entry.info
    if info == nil then
        return nil
    end
    local line = apT("loadout.power", { n = info.power })
    if family == "weapon" then
        line = line .. ", " .. apT(info.missiles > 0 and "loadout.weapon.missile" or "loadout.weapon.stats",
            { damage = info.damage, shots = info.shots, cooldown = info.cooldown })
    end
    return line
end

-- On the row there is only room for the power: the rest shows on hover.
local function shortStats(entry)
    return entry.info and apT("loadout.power", { n = entry.info.power }) or nil
end

local function crewLabel(entry)
    local race = _G.apRaceLabel and _G.apRaceLabel(entry.race) or entry.race
    if entry.skill ~= nil and SKILL_KEYS[entry.skill] ~= nil then
        return race .. ", " .. apT(SKILL_KEYS[entry.skill])
    end
    return race
end

local function receivedCatalog()
    local catalog = { weapon = {}, drone = {}, crew = {}, system = {} }
    local inventory = _G.apInventory or {}
    for _, name in ipairs(_G.apSystemInstallChoices and apSystemInstallChoices() or {}) do
        local old = _G.apSystemSwapOf and apSystemSwapOf(name)
        local label = old and apT("loadout.system.swap", { name = apSystemLabel(name), old = apSystemLabel(old) })
            or apSystemLabel(name)
        catalog.system[#catalog.system + 1] = { system = name, label = label }
    end
    for name, count in pairs(inventory.shopAvailability or {}) do
        if (tonumber(count) or 0) >= 2 then
            local family = _G.apBlueprintFamily and _G.apBlueprintFamily(name)
            if family == "weapon" or family == "drone" then
                local list = catalog[family]
                list[#list + 1] = { bp = name, label = blueprintTitle(name, family),
                                    info = blueprintInfo(name, family) }
            end
        end
    end
    local seen = {}
    for race, state in pairs(inventory.crewProgress or {}) do
        if (tonumber(state.n) or 0) >= 2 then
            local entry = { race = race, skill = state.n >= 3 and state.skill or nil }
            seen[tostring(race) .. "/" .. tostring(entry.skill)] = true
            catalog.crew[#catalog.crew + 1] = {
                race = entry.race, skill = entry.skill, label = crewLabel(entry),
            }
        end
    end
    for _, entry in ipairs(inventory.crew or {}) do
        local key = tostring(entry.race) .. "/" .. tostring(entry.skill)
        if not seen[key] then
            seen[key] = true
            catalog.crew[#catalog.crew + 1] = {
                race = entry.race, skill = entry.skill, label = crewLabel(entry),
            }
        end
    end
    for _, category in ipairs(ALL_CATEGORIES) do
        table.sort(catalog[category], function(a, b) return a.label < b.label end)
    end
    return catalog
end

local function catalogEmpty(catalog)
    return #catalog.weapon == 0 and #catalog.drone == 0 and #catalog.crew == 0 and #catalog.system == 0
end

local function categoriesShown(catalog)
    if #catalog.system > 0 or taken.system then
        return ALL_CATEGORIES
    end
    return CATEGORIES
end

local function uiFree()
    local ok, free = pcall(function()
        if Hyperspace.App.world.bStartedGame ~= true then return false end
        local gui = Hyperspace.App.gui
        return not (gui.choiceBoxOpen or gui.event_pause or gui.menu_pause)
    end)
    return ok and free == true
end

local function close(reason)
    if open then
        menuLog("menu closed: " .. reason)
    end
    -- sector_skip's extra pick ends with the menu, used or not: one that cannot be made must not come back at
    -- every beacon.
    extraPick = false
    open = false
    pending = false
    remember("open", 0)
end

local function geometry(categories)
    categories = categories or CATEGORIES
    local g = { columns = {} }
    local columnW = math.floor((PANEL.w - 40 - COLUMN_GAP * (#categories - 1)) / #categories)
    local columnH = PANEL.h - COLUMN_TOP - COLUMN_BOTTOM
    local perPage = math.floor((columnH - LIST_OFFSET - PAGER_H - 16) / (ROW_H + ROW_GAP))
    for index, category in ipairs(categories) do
        local x = PANEL.x + 20 + (index - 1) * (columnW + COLUMN_GAP)
        local y = PANEL.y + COLUMN_TOP
        local pagerY = y + columnH - PAGER_H - 10
        g.columns[category] = {
            x = x, y = y, w = columnW, h = columnH,
            listY = y + LIST_OFFSET,
            previous = { x = x + 12, y = pagerY, w = 32, h = PAGER_H },
            next = { x = x + columnW - 44, y = pagerY, w = 32, h = PAGER_H },
        }
    end
    g.perPage = perPage
    g.done = {
        x = PANEL.x + math.floor((PANEL.w - DONE_BUTTON.w) / 2),
        y = PANEL.y + PANEL.h - DONE_BUTTON.h - 18,
        w = DONE_BUTTON.w, h = DONE_BUTTON.h,
    }
    return g
end

local function rowArea(column, row)
    return { x = column.x + 12, y = column.listY + (row - 1) * (ROW_H + ROW_GAP), w = column.w - 24, h = ROW_H }
end

function apLoadoutPoint(target, category, row)
    local g = geometry(categoriesShown(receivedCatalog()))
    if target == "done" then
        return g.done.x + g.done.w / 2, g.done.y + g.done.h / 2
    end
    local column = g.columns[category]
    local area = target == "row" and rowArea(column, row or 1) or column[target]
    return area.x + area.w / 2, area.y + area.h / 2
end

-- sector_skip's extra pick: this menu came back for one more pick, until a pick is made or the menu is closed.
local extraPick = false

local function roomFor(category)
    if category ~= "weapon" and category ~= "drone" then
        return true
    end
    return _G.apEquipmentHasRoom == nil or apEquipmentHasRoom(category)
end

local function take(category, entry)
    if not roomFor(category) then
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("loadout.no_room", { name = entry.label }))
        end
        return
    end
    local succeeded, reason
    if category == "system" then
        succeeded = _G.apInstallChosenSystem ~= nil and apInstallChosenSystem(entry.system)
        if succeeded then
            menuLog("installed for this run: " .. entry.label)
            if _G.apNotifyStatus then
                _G.apNotifyStatus(apT("loadout.taken", { name = entry.label }))
            end
            -- Several systems can come aboard: the column closes once no slot is left.
            if #(apSystemInstallChoices()) == 0 then
                taken.system = entry.label
            end
            return
        end
    elseif category == "crew" then
        succeeded, reason = _G.apRecruitCrew and _G.apRecruitCrew(entry.race, entry.skill)
    else
        succeeded = _G.apDeliverEquipment and _G.apDeliverEquipment(
            { kind = category, bp = entry.bp, display = entry.label, silent = true, chosen = true }) == true
    end
    if not succeeded then
        menuLog("cannot take " .. entry.label .. ": " .. tostring(reason))
        if _G.apNotifyStatus then
            _G.apNotifyStatus(apT("loadout.refused", { name = entry.label }))
        end
        return
    end
    taken[category] = entry.label
    remember(category, 1)
    extraPick = false
    menuLog("taken for this run: " .. entry.label)
    if _G.apNotifyStatus then
        _G.apNotifyStatus(apT("loadout.taken", { name = entry.label }))
    end
    local systemsLeft = _G.apSystemInstallChoices and #(apSystemInstallChoices()) or 0
    if taken.weapon and taken.drone and taken.crew and systemsLeft == 0 then
        close("all three categories are taken")
    end
end

-- The store's description of the weapon or drone under the mouse, with its numbers, next to the pointer.
local INFO_W = 300

local function drawInfo(hovered)
    local x, y = ui.mouse()
    local text = hovered.entry.info and hovered.entry.info.text or ""
    local lines = text ~= "" and ui.lines(9, text, INFO_W - 20, 12) or {}
    local h = 40 + #lines * 13 + (#lines > 0 and 8 or 0)
    x = math.min(x + 16, 1280 - INFO_W - 8)
    y = math.min(y + 16, 720 - h - 8)
    ui.window(x, y, INFO_W, h)
    ui.text(10, x + 10, y + 8, INFO_W - 20, "title", hovered.entry.label)
    ui.text(9, x + 10, y + 26, INFO_W - 20, "good", hovered.stats)
    for index, line in ipairs(lines) do
        ui.text(9, x + 10, y + 40 + (index - 1) * 13, INFO_W - 20, "text", line)
    end
end

local function draw()
    hoveredEntry = nil
    local catalog = receivedCatalog()
    local categories = categoriesShown(catalog)
    local g = geometry(categories)
    ui.hideGameTooltip()
    ui.shade()
    ui.window(PANEL.x, PANEL.y, PANEL.w, PANEL.h)
    if logoTexture == nil then
        local ok, texture = pcall(function() return Hyperspace.Resources:GetImageId(LOGO) end)
        logoTexture = (ok and texture) or false
    end
    local titleX = PANEL.x + 20
    if logoTexture then
        Graphics.CSurface.GL_BlitPixelImage(logoTexture, titleX, PANEL.y + 14, LOGO_SIZE, LOGO_SIZE,
            0, Graphics.GL_Color(1, 1, 1, 1), false)
        titleX = titleX + LOGO_SIZE + 10
    end
    ui.text(24, titleX, PANEL.y + 14, PANEL.x + PANEL.w - 20 - titleX, "title", apT("loadout.title"))
    ui.wrapped(10, PANEL.x + 20, PANEL.y + 54, PANEL.w - 40, "dim",
        apT(extraPick and "loadout.hint.extra"
            or (#categories > #CATEGORIES and "loadout.hint.systems" or "loadout.hint")))

    for _, category in ipairs(categories) do
        local column = g.columns[category]
        local list = catalog[category]
        local chosen = taken[category]
        ui.rect(column.x, column.y, column.w, column.h, "card")
        ui.rect(column.x, column.y, column.w, 2, chosen and "good" or "border")
        local badge = chosen and apT("loadout.chosen") or apT("loadout.count", { n = #list })
        if category == "system" and not chosen then
            badge = apT("loadout.free_slots", { n = apSystemFreeSlots and apSystemFreeSlots() or 0 })
        elseif #categories > #CATEGORIES and not chosen then
            -- Four columns leave no room for "N received": the number says it.
            badge = tostring(#list)
        end
        local badgeW = ui.width(9, badge)
        ui.text(13, column.x + 12, column.y + 14, column.w - 36 - badgeW, "title", apT(COLUMN_KEYS[category]))
        ui.textRight(9, column.x + column.w - 12, column.y + 18, badgeW, chosen and "good" or "dim", badge)

        if #list == 0 then
            ui.wrapped(10, column.x + 12, column.listY, column.w - 24, "dim", apT(EMPTY_KEYS[category]))
        else
            local total = math.ceil(#list / g.perPage)
            local page = math.min(pages[category] or 1, total)
            for row = 1, g.perPage do
                local entry = list[(page - 1) * g.perPage + row]
                if entry == nil then break end
                local area = rowArea(column, row)
                local isChosen = chosen ~= nil and entry.label == chosen
                local available = chosen == nil and roomFor(category)
                local over = available and ui.hovered(area)
                ui.rect(area.x, area.y, area.w, area.h, isChosen and "hover" or (over and "hover" or "window"))
                ui.rect(area.x, area.y, 3, area.h, isChosen and "good" or (over and "border" or "faint"))
                local alpha = (available or isChosen) and 1 or 0.4
                local iconX, iconY, iconH = area.x + 8, area.y + 4, area.h - 8
                if category == "weapon" then
                    ui.weaponArt(entry.bp, iconX, iconY, ICON_W, iconH, alpha)
                elseif category == "drone" then
                    ui.droneArt(entry.bp, iconX, iconY, ICON_W, iconH, alpha)
                elseif category == "system" then
                    ui.systemIcon(entry.system, iconX, iconY, ICON_W, iconH, alpha)
                else
                    ui.raceSprite(entry.race, iconX + (ICON_W - 70) / 2, area.y + (area.h - 70) / 2, 70, alpha)
                end
                local stats = (category == "weapon" or category == "drone") and statsLine(entry, category) or nil
                if stats then
                    -- A long name takes two lines: the first one rises, the stats stay where they are.
                    local labelW = area.w - ICON_W - 24
                    local tall = ui.width(10, entry.label) > labelW
                    ui.textTwoLines(10, area.x + ICON_W + 16, area.y + (tall and 10 or 9), labelW, 14,
                        isChosen and "good" or (available and "text" or "dim"), entry.label)
                    ui.text(9, area.x + ICON_W + 16, area.y + (tall and 31 or 27), labelW, "dim", shortStats(entry))
                else
                    ui.textTwoLines(10, area.x + ICON_W + 16, area.y + 17, area.w - ICON_W - 24, 14,
                        isChosen and "good" or (available and "text" or "dim"), entry.label)
                end
                if ui.hovered(area) and stats then
                    hoveredEntry = { entry = entry, stats = stats }
                end
            end
            if total > 1 then
                ui.button(column.previous, apT("loadout.previous"), "secondary", page <= 1)
                ui.button(column.next, apT("loadout.next"), "secondary", page >= total)
                ui.textCenter(9, column.x + column.w / 2, column.previous.y + 6, column.w - 100, "dim",
                    apT("loadout.page", { n = page, total = total }))
            end
        end
    end

    ui.button(g.done, apT("loadout.done"), "primary")
    if hoveredEntry then
        drawInfo(hoveredEntry)
    end
end

function apLoadoutOpen()
    return open
end

local function handleClick(x, y)
    local catalog = receivedCatalog()
    local categories = categoriesShown(catalog)
    local g = geometry(categories)
    if ui.inside(g.done, x, y) then
        close("finished by the player")
        return true
    end
    for _, category in ipairs(categories) do
        local column = g.columns[category]
        local list = catalog[category]
        local total = math.max(1, math.ceil(#list / g.perPage))
        if ui.inside(column.previous, x, y) then
            pages[category] = math.max(1, (pages[category] or 1) - 1)
            return true
        end
        if ui.inside(column.next, x, y) then
            pages[category] = math.min(total, (pages[category] or 1) + 1)
            return true
        end
        if not taken[category] then
            local page = math.min(pages[category] or 1, total)
            for row = 1, g.perPage do
                local entry = list[(page - 1) * g.perPage + row]
                if entry ~= nil and ui.inside(rowArea(column, row), x, y) then
                    take(category, entry)
                    return true
                end
            end
        end
    end
    return ui.inside(PANEL, x, y)
end

-- Said once a session: a seed starts empty for many runs, and the player only needs to learn it once.
local toldNothingYet = false
local function sayNothingYet()
    local contract = _G.apContractState
    if toldNothingYet or contract == nil or contract.connected ~= true then
        return
    end
    toldNothingYet = true
    if _G.apNotifyStatus then apNotifyStatus(apT("loadout.nothing_yet")) end
end

function apLoadoutResetToldForTesting()
    toldNothingYet = false
end

script.on_init(function(newGame)
    taken = {}
    pages = {}
    open = false
    pending = newGame == true
    resumed = newGame == false
    if newGame then
        remember("open", 1)
        for _, category in ipairs(CATEGORIES) do
            remember(category, 0)
        end
    end
end)

script.on_internal_event(Defines.InternalEvents.JUMP_ARRIVE, function(shipManager)
    if shipManager ~= nil and shipManager.iShipId ~= 0 then
        return Defines.Chain.CONTINUE
    end
    -- sector_skip: a sector skipped gives one more pick from the received items, at the next beacon.
    if _G.apLoadoutExtraPick then
        _G.apLoadoutExtraPick = false
        extraPick = true
        taken = {}
        pages = {}
        open = false
        pending = true
        remember("open", 1)
        for _, category in ipairs(CATEGORIES) do
            remember(category, 0)
        end
        menuLog("one more pick for the sector skipped")
        return Defines.Chain.CONTINUE
    end
    close("first jump of the run")
    return Defines.Chain.CONTINUE
end)

script.on_internal_event(Defines.InternalEvents.ON_MOUSE_L_BUTTON_DOWN, function(x, y)
    -- Hidden behind the pause menu or an event, the menu must not catch their clicks.
    if not open or not uiFree() then
        return Defines.Chain.CONTINUE
    end
    local ok, consumed = pcall(handleClick, apMousePosition(x, y))
    if ok and consumed then
        return Defines.Chain.PREEMPT
    end
    return Defines.Chain.CONTINUE
end)

script.on_render_event(
    Defines.RenderEvents.GUI_CONTAINER,
    function() end,
    function()
        if resumed and uiFree() then
            resumed = false
            pending = recalled("open")
            for _, category in ipairs(CATEGORIES) do
                taken[category] = recalled(category) or nil
            end
        end
        if pending and not open and uiFree() and runCounts() then
            if catalogEmpty(receivedCatalog()) then
                pending = false
                sayNothingYet()
            else
                open = true
                menuLog("start-of-run menu opened")
            end
        end
        if open and uiFree() then
            local ok, err = pcall(draw)
            if not ok then
                close("render error: " .. tostring(err))
            end
        end
    end
)

menuLog("start-of-run menu loaded")

