    sim.clearLog()
    restore = stub("apNetEnergyLinkDeposit", function() return true end)
    pcall(_G.apEnergyLinkContribute)
    restore()
    check(sim.shown(apT("energylink.sent", { what = apT("energylink.part.fuel", { n = 2 }), net = "1.5" })),
        "2 fuel given, 1.5 in the reserve")
end)

