        apQueueItem(descriptor)
        drain()
        check(sim.logged("item(s) delivered"),
              descriptor.kind .. " is actually delivered, not just accepted")
        equals(#_G.apFillerPendingForTesting(), 0,
               descriptor.kind .. " doesn't stay queued")
    end
end)

local function springTrapNow(effect)
    apQueueItem({ kind = "trap", eff = effect })
    drain()
end

test("trap: hull never drops below the floor", function()
    sim.startRun(true)
    for _, start in ipairs({ 1, 2, 3, 4, 10 }) do
        sim.player.ship.hullIntegrity.first = start
        sim.player.bDestroyed = false
        springTrapNow("hull_damage")
        check(sim.player.ship.hullIntegrity.first >= math.min(start, _G.apTrapLimits.hullFloor),
              "hull " .. start .. " -> " .. sim.player.ship.hullIntegrity.first)
        check(not sim.player.bDestroyed, "ship alive, started from " .. start)
    end
end)

test("trap: a ship at one hull point is not finished off", function()
    sim.startRun(true)
    sim.player.ship.hullIntegrity.first = 1
    springTrapNow("hull_damage")
    equals(sim.player.ship.hullIntegrity.first, 1, "the hull hasn't moved")
    check(not sim.player.bDestroyed, "and the ship is alive")
    check(#sim.player._fires > 0 or sim.player._breaches > 0 or sim.logged("trap triggered"),
          "a gentler fallback was applied")
end)

test("trap: the fuel leak leaves enough to jump", function()
    sim.startRun(true)
    for _, start in ipairs({ 0, 1, 2, 3, 8, 20 }) do
        sim.player.fuel_count = start
        springTrapNow("fuel_leak")
        check(sim.player.fuel_count >= math.min(start, _G.apTrapLimits.fuelFloor),
              "fuel " .. start .. " -> " .. sim.player.fuel_count)
    end
end)

test("O2 drain trap: waits for a quiet beacon, then every room loses its air once", function()
    sim.startRun(true)
    local oxygen = sim.player.oxygenSystem
    sim.enemy = sim.makeShip(1)
    apQueueItem({ kind = "trap", eff = "o2_drain" })
    drain()
    equals(oxygen.oxygenLevels[0], 100, "no drain during a fight")
    sim.enemy = nil
    drain()
    for room = 0, oxygen.oxygenLevels:size() - 1 do
        equals(oxygen.oxygenLevels[room], 0, "room " .. room .. " has no air left")
    end
    check(shownKey("trap.o2_drain"), "the player is told")
end)

test("O2 drain trap: never without a working oxygen system, another trap instead", function()
    sim.startRun(true)
    local oxygen = sim.player.oxygenSystem
    oxygen.healthState.first = 0
    springTrapNow("o2_drain")
    equals(oxygen.oxygenLevels[0], 100, "a broken oxygen system keeps the air in")
    sim.player.oxygenSystem = nil
    springTrapNow("o2_drain")
    check(not sim.player.bDestroyed, "a ship without oxygen system takes another trap")
end)

test("O2 drain trap: a broken oxygen system lights a fire and says why", function()
    sim.startRun(true)
    apNotifyResetForTesting()
    sim.player.oxygenSystem.healthState.first = 0
    apQueueItem({ kind = "trap", eff = "o2_drain" })
    drain()
    check(shownKey("trap.o2_drain.down"), "the player knows why it is a fire, with no room number")
end)

test("O2 drain trap: with the hull breached the rooms keep some air", function()
    sim.startRun(true)
    apNotifyResetForTesting()
    sim.hullBreaches = { {} }
    local oxygen = sim.player.oxygenSystem
    apQueueItem({ kind = "trap", eff = "o2_drain" })
    drain()
    sim.hullBreaches = nil
    equals(oxygen.oxygenLevels[0], apTrapLimits.drainAirWithBreach, "the air stops at the floor")
    check(shownKey("trap.o2_drain.breach"), "and the player is told")
end)

test("O2 drain trap: a badly hurt crew member gets air back, a healthy one does not", function()
    sim.startRun(true)
    local oxygen = sim.player.oxygenSystem
    local hurt, fine = sim.player.vCrewList[0], sim.player.vCrewList[1]
    hurt.iRoomId, fine.iRoomId = 0, 1
    hurt.health.first, hurt.health.second = 20, 100
    fine.health.first, fine.health.second = 100, 100
    apQueueItem({ kind = "trap", eff = "o2_drain" })
    drain()
    sim.tick(12)
    check(oxygen.oxygenLevels[0] >= apTrapLimits.drainGuardAir, "the hurt one has air")
    equals(oxygen.oxygenLevels[1], 0, "the other room stays empty")
end)

test("hull breach trap: not on a ship short of air, a fire instead", function()
    sim.startRun(true)
    local oxygen = sim.player.oxygenSystem
    for room = 0, oxygen.oxygenLevels:size() - 1 do
        oxygen:ModifyRoomOxygen(room, -100)
    end
    local before = sim.player.ship.breaches and #sim.player.ship.breaches or 0
    springTrapNow("breach")
    check(sim.logged("falling back to fire"), "the breach gives way to a fire")
    equals(sim.player.ship.breaches and #sim.player.ship.breaches or 0, before, "no hole in the hull")
end)

test("TrapLink: an oxygen trap from another game drains the air", function()
    equals(apTrapLinkTranslate("Oxygen Trap"), "o2_drain", "'Oxygen'")
    equals(apTrapLinkTranslate("Suffocation Trap"), "o2_drain", "'Suffocation'")
end)

test("trap: the message names the system the way the game names it", function()
    sim.startRun(true)
    sim.clearLog()
    springTrapNow("system_damage")
    check(sim.shown("Shields") or sim.shown("Engines") or sim.shown("Medbay")
          or sim.shown("Weapon Control") or sim.shown("Piloting") or sim.shown("Oxygen"),
          "a game system name is shown")
    check(not sim.shown("shields") and not sim.shown("medbay") and not sim.shown("weapons"),
          "and no blueprint id reaches the screen")
end)

test("trap: a system is damaged, never disabled", function()
    sim.startRun(true)
    local systems = sim.player.vSystemList
    for i = 0, systems:size() - 1 do
        systems[i].healthState.first = 2
    end
    for _ = 1, 10 do
        springTrapNow("system_damage")
    end
    local dead = 0
    for i = 0, systems:size() - 1 do
        if systems[i].healthState.first < _G.apTrapLimits.systemFloor then
            dead = dead + 1
        end
    end
    equals(dead, 0, "no system below the floor")
end)

test("trap: the rebel fleet isn't pushed indefinitely", function()
    sim.startRun(true)
    for _ = 1, 20 do
        springTrapNow("fleet_advance")
    end
    check(sim.pursuit <= _G.apTrapLimits.pursuitCeiling,
          "the fleet was pushed " .. sim.pursuit .. " times, cap "
          .. _G.apTrapLimits.pursuitCeiling)
end)

test("trap: the fleet cap resets to zero every run", function()
    sim.startRun(true)
    for _ = 1, 20 do
        springTrapNow("fleet_advance")
    end
    local first = sim.pursuit
    check(first > 0, "the first run did push the fleet")

    sim.reset()
    sim.startRun(true)
    springTrapNow("fleet_advance")
    equals(sim.pursuit, 1, "the new run can be pushed again")
end)

test("trap: an impossible trap falls back, it doesn't vanish", function()
    sim.startRun(true)
    sim.player.ship.hullIntegrity.first = _G.apTrapLimits.hullFloor
    sim.clearLog()
    springTrapNow("hull_damage")
    check(sim.logged("falling back to"), "the log names the fallback")
    check(shownKey("trap.sprung"), "and the player sees that something happened")
end)

test("trap: when nothing more is possible, the mod says so", function()
    sim.startRun(true)
    sim.player.ship.hullIntegrity.first = _G.apTrapLimits.hullFloor
    sim.player.fuel_count = _G.apTrapLimits.fuelFloor
    local systems = sim.player.vSystemList
    for i = 0, systems:size() - 1 do
        systems[i].healthState.first = _G.apTrapLimits.systemFloor
    end
    local failing = function() error("engine unavailable") end
    sim.player.StartFire = failing
    sim.player.DamageArea = failing
    sim.player.GetRandomRoomCenter = failing
    sim.player.ship.BreachRandomHull = failing

    sim.clearLog()
    springTrapNow("hull_damage")
    check(shownKey("trap.fizzled"),
          "the player is told the trap couldn't do anything")
    equals(sim.errors, 0, "and nothing is reported to the engine")
end)

test("trap: the player knows it comes from Archipelago, not the game", function()
    sim.startRun(true)
    sim.player.ship.hullIntegrity.first = 20
    sim.clearLog()
    springTrapNow("fire")
    check(shownKey("trap.sprung"), "the message is marked as a trap")
end)

test("trap: no trap destroys the ship, whatever the situation", function()
    for _, effect in ipairs({ "fire", "breach", "fuel_leak", "system_damage",
                              "hull_damage", "fleet_advance" }) do
        sim.reset()
        sim.startRun(true)
        sim.player.ship.hullIntegrity.first = 1
        sim.player.fuel_count = 0
        springTrapNow(effect)
        check(not sim.player.bDestroyed, effect .. " didn't destroy the ship")
        check(sim.player.ship.hullIntegrity.first >= 1, effect .. " left at least one point")
    end
end)

test("weapons, drones and augments are delivered", function()
    sim.startRun(true)
    apQueueItem({ kind = "weapon", bp = "LASER_BURST_3" })
    apQueueItem({ kind = "drone", bp = "DEFENSE_1" })
    apQueueItem({ kind = "augment", bp = "SCRAP_COLLECTOR" })
    drain()

    equals(sim.delivered(), 2, "the weapon and drone are delivered")
    equals(#sim.player._augments, 1, "the augment is installed on the ship")
end)

test("a delivered weapon is mounted if there is a slot, otherwise stored in cargo", function()
    sim.startRun(true)
    sim.slots.weapon = 1
    apQueueItem({ kind = "weapon", bp = "LASER_BURST_3" })
    apQueueItem({ kind = "weapon", bp = "BEAM_2" })
    drain()
    equals(#sim.equipped.weapon, 1, "the first takes the free slot")
    equals(#sim.cargo, 1, "the second goes to cargo, for lack of room")
end)

test("a nonexistent blueprint is REFUSED, not silently swallowed", function()
    sim.startRun(true)
    apQueueItem({ kind = "weapon", bp = "BURST_LASER_2" })
    drain()
    equals(sim.delivered(), 0, "nothing is added")
    check(sim.logged("unknown blueprint, item NOT delivered"), "and the refusal is logged")
    check(shownKey("item.unknown"), "and the player is warned on screen")
end)

test("the game is the authority on a blueprint's type", function()
    sim.startRun(true)
    apQueueItem({ kind = "weapon", bp = "DEFENSE_1" })
    drain()
    equals(sim.delivered(), 1, "the item is delivered anyway")
    check(sim.logged("kind corrected"), "and the correction is traced")
end)

test("a received item makes an unfindable object available", function()
    sim.weaponBlueprints.MISSILES_2 = 0
    sim.resetBlueprints()
    _G.apInventory = { ships = {}, shopAvailability = { MISSILES_2 = 1 } }
    apApplyShopRules()

    local desc = sim.rarityFor("MISSILES_2", 0)
    check(desc.rarity > 0, "the unfindable object can now be generated")
    check(desc.rarity >= 3, "but it stays rare on the first copy (got: " .. desc.rarity .. ")")
end)

test("an augment received with all three slots taken waits for a free slot", function()
    sim.startRun(true)
    _G.apShopConfig.deliver = true
    sim.player._augments = { "SCRAP_COLLECTOR", "SCRAP_COLLECTOR", "SCRAP_COLLECTOR" }
    sim.clearLog()
    apApplyShopItem({ kind = "shop", bp = "ENERGY_SHIELD", display = "Shield Charge Booster" })
    drain(6)
    equals(#sim.player._augments, 3, "nothing forced into a full set")
    local waiting = apT("item.waiting_augment", { name = "Shield Charge Booster" })
    local shown, logged = 0, 0
    for _, line in ipairs(sim.screen) do
        if line:find(waiting, 1, true) then shown = shown + 1 end
    end
    for _, line in ipairs(sim.log) do
        if line:find("delivery deferred for ENERGY_SHIELD", 1, true)
            or line:find("kind corrected for ENERGY_SHIELD", 1, true) then
            logged = logged + 1
        end
    end
    equals(shown, 1, "the player is told once that it waits")
    equals(logged, 2, "and the log says it once, not at every try")
    table.remove(sim.player._augments)
    sim.jumpArrive()
    drain()
    check(sim.player:HasAugmentation("ENERGY_SHIELD"), "once a slot is free, the augment comes aboard")
end)

test("the goal message stays on screen through the burst of items that follows", function()
    apNotifyResetForTesting()
    apNotifyKept(apT("goal.reached"))
    for index = 1, 8 do apNotifyStatus("line " .. index) end
    local kept = false
    for _, toast in ipairs(apToastsForTesting()) do
        if toast.text == apT("goal.reached") then kept = true end
    end
    check(kept, "still shown after eight other messages")
    equals(#apToastsForTesting(), 4, "and the screen still holds four at most")
end)

test("many augments waiting at once make one line, not a flood", function()
    local names = { "REPAIR_ARM", "ION_ARMOR", "FIRE_EXTINGUISHERS", "O2_MASKS" }
    for _, name in ipairs(names) do sim.augBlueprints[name] = sim.augBlueprints[name] or 3 end
    sim.resetBlueprints()
    _G.apRunStartCheckForTesting = false
    sim.startRun(true)
    _G.apShopConfig.deliver = true
    sim.player._augments = { "SCRAP_COLLECTOR", "SCRAP_COLLECTOR", "SCRAP_COLLECTOR" }
    sim.clearLog()
    for _, name in ipairs(names) do
        apApplyShopItem({ kind = "shop", bp = name, display = name })
    end
    drain()
    check(sim.shown(apT("item.waiting_augment.many", { n = 4 })), "one line counts them")
    check(not sim.shown(apT("item.waiting_augment", { name = "REPAIR_ARM" })), "instead of one line each")
end)

test("with slots and cargo full, only a few weapons per beacon go to the over capacity box, the rest wait for a jump", function()
    sim.startRun(true)
    sim.slots.weapon = 0
    sim.cargoCap = 0
    for _ = 1, 10 do
        apQueueItem({ kind = "weapon", bp = "BEAM_2", display = "Halberd Beam" })
    end
    sim.tick(240)
    equals(#sim.overflow, 4, "four in the box")
    check(#_G.apFillerPendingForTesting() == 6, "the other six wait instead of piling up")
    sim.overflow = {}
    sim.jumpArrive()
    sim.tick(240)
    equals(#sim.overflow, 4, "after the jump empties the box, four more come")
    check(apDeliverEquipment({ kind = "weapon", bp = "BEAM_2", display = "Halberd Beam", chosen = true }),
        "a weapon picked in the start-of-run menu is never held back")
end)

test("with weapon slots and the cargo hold full, weapons and drones wait for room instead of the box", function()
    sim.startRun(true)
    sim.slots.weapon = 0
    sim.slots.drone = 0
    sim.cargoCap = 4
    sim.cargo = { "BEAM_2", "BEAM_2", "BEAM_2", "BEAM_2" }
    apQueueItem({ kind = "weapon", bp = "LASER_BURST_3", display = "Burst Laser Mark III" })
    apQueueItem({ kind = "drone", bp = "DEFENSE_1", display = "Defense Drone Mark I" })
    sim.tick(240)
    equals(#sim.overflow, 0, "nothing goes to the over capacity box, which a jump would empty")
    equals(#_G.apFillerPendingForTesting(), 2, "both wait in the queue")
    check(shownKey("item.waiting_cargo"), "the player is told why")
    sim.clearLog()
    sim.tick(240)
    check(not shownKey("item.waiting_cargo"), "once, not at every retry")
    table.remove(sim.cargo)
    sim.tick(240)
    equals(#sim.cargo, 3, "a slot freed during the stay stays free: selling does not refill it")
    sim.jumpArrive()
    sim.tick(240)
    equals(#sim.cargo, 4, "the next arrival fills it")
    equals(#_G.apFillerPendingForTesting(), 1, "the other keeps waiting")
    sim.cargo = {}
    sim.jumpArrive()
    sim.tick(240)
    equals(#_G.apFillerPendingForTesting(), 0, "and it comes when there is room")
    sim.cargoCap = 999
end)

test("a weapon held back by the beacon limit, then by a full cargo hold, still says why it waits", function()
    sim.startRun(true)
    sim.slots.weapon = 0
    sim.cargoCap = 4
    sim.cargo = {}
    for _ = 1, 4 do apQueueItem({ kind = "weapon", bp = "BEAM_2", display = "Halberd Beam" }) end
    apQueueItem({ kind = "weapon", bp = "LASER_BURST_3", display = "Burst Laser Mark III" })
    sim.tick(240)
    equals(#sim.cargo, 4, "four per beacon fill the cargo hold")
    equals(#_G.apFillerPendingForTesting(), 1, "the fifth waits for the next beacon")
    sim.clearLog()
    sim.jumpArrive()
    sim.tick(240)
    equals(#_G.apFillerPendingForTesting(), 1, "next beacon: the cargo hold is full, it still waits")
    check(shownKey("item.waiting_cargo"), "and the player is told the cargo hold is full")
    sim.cargo = {}
    sim.cargoCap = 999
    sim.tick(240)
end)

test("a weapon whose copy waits counts as received only once the copy is aboard", function()
    sim.startRun(true)
    _G.apShopConfig.deliver = true
    local marked = {}
    local restore = stub("apNetItemDelivered", function(index) marked[#marked + 1] = index return true end)
    for _ = 1, 4 do apQueueItem({ kind = "weapon", bp = "BEAM_2", display = "Halberd Beam" }) end
    apQueueItem({ kind = "shop", bp = "BEAM_2", display = "Halberd Beam", index = 7 })
    sim.tick(240)
    equals(#marked, 0, "held back by the beacon limit: not marked yet")
    sim.jumpArrive()
    sim.tick(240)
    restore()
    equals(marked[#marked], 7, "marked once the copy lands")
end)

test("a copy still owed when the game closes comes aboard in the next run, not only in the catalogue", function()
    sim.startRun(true)
    apShopForgetSeed()
    apFillerResetForTesting()
    _G.apShopConfig.deliver = true
    local marked = {}
    local restore = stub("apNetItemDelivered", function(index) marked[#marked + 1] = index return true end)
    for _ = 1, 4 do apQueueItem({ kind = "weapon", bp = "BEAM_2", display = "Halberd Beam" }) end
    apQueueItem({ kind = "shop", bp = "BEAM_2", display = "Halberd Beam", index = 7 })
    sim.tick(240)
    equals(#marked, 0, "held back by the beacon limit")

    apFillerResetForTesting()
    apShopForgetSeed()
    sim.started = false
    apQueueItem({ kind = "shop", bp = "BEAM_2", display = "Halberd Beam", index = 7 })
    sim.tick(240)
    equals(#marked, 0, "at the menu of the next launch, the item is not taken as done")
    local before = sim.delivered()
    sim.startRun(false)
    sim.tick(240)
    restore()
    equals(sim.delivered(), before + 1, "the copy comes aboard once the run is back")
    equals(marked[#marked], 7, "and only then is the item marked")
    apShopForgetSeed()
    apQueueItem({ kind = "shop", bp = "BEAM_2", display = "Halberd Beam", index = 7, isReplay = true })
    sim.tick(240)
    equals(sim.delivered(), before + 1, "a later replay does not give it a second time")
end)

test("a copy put aboard comes back after a crash, until the run is saved at the next jump", function()
    sim.startRun(true)
    apShopForgetSeed()
    apFillerResetForTesting()
    _G.apShopConfig.deliver = true
    apQueueItem({ kind = "shop", bp = "BEAM_2", display = "Halberd Beam", index = 3 })
    sim.tick(240)
    equals(#sim.equipped.weapon, 1, "the copy comes aboard")

    -- The game crashes: the run comes back as FTL saved it, before the copy.
    apFillerResetForTesting()
    apShopForgetSeed()
    sim.equipped.weapon = {}
    sim.startRun(false)
    apQueueItem({ kind = "shop", bp = "BEAM_2", display = "Halberd Beam", index = 3, isReplay = true })
    sim.tick(240)
    equals(#sim.equipped.weapon, 1, "the copy comes aboard again")

    -- This time FTL saved it: after a jump, a restart does not give it again.
    sim.jumpArrive()
    apFillerResetForTesting()
    apShopForgetSeed()
    sim.startRun(false)
    apQueueItem({ kind = "shop", bp = "BEAM_2", display = "Halberd Beam", index = 3, isReplay = true })
    sim.tick(240)
    equals(#sim.equipped.weapon, 1, "no second copy once the run was saved")
end)

test("a copy owed after a crash is not given twice when the saved run already has it", function()
    sim.startRun(true)
    apShopForgetSeed()
    apFillerResetForTesting()
    _G.apShopConfig.deliver = true
    apQueueItem({ kind = "shop", bp = "BEAM_2", display = "Halberd Beam", index = 3 })
    sim.tick(240)
    equals(#sim.cargo + #sim.equipped.weapon, 1, "the copy comes aboard")

    -- The game is closed without a jump, but FTL saved the run on the way out.
    apFillerResetForTesting()
    apShopForgetSeed()
    sim.equipped.weapon = {}
    sim.cargo = { "BEAM_2" }
    sim.startRun(false)
    apQueueItem({ kind = "shop", bp = "BEAM_2", display = "Halberd Beam", index = 3, isReplay = true })
    sim.tick(240)
    equals(#sim.cargo + #sim.equipped.weapon, 1, "the saved copy is enough")
end)

test("a weapon still waiting when the game closes comes aboard in the next run, not only in the catalogue", function()
    sim.startRun(true)
    apShopForgetSeed()
    apFillerResetForTesting()
    _G.apShopConfig.deliver = true
    local marked = {}
    local restore = stub("apNetItemDelivered", function(index) marked[#marked + 1] = index return true end)
    sim.enemy = sim.makeShip(1)
    apQueueItem({ kind = "shop", bp = "BEAM_2", display = "Halberd Beam", index = 9 })
    sim.tick(240)
    equals(#marked, 0, "held back by the fight")

    -- The game is closed in the middle of the fight; at the next launch the server sends the item again.
    apFillerResetForTesting()
    apShopForgetSeed()
    sim.enemy = nil
    sim.started = false
    apQueueItem({ kind = "shop", bp = "BEAM_2", display = "Halberd Beam", index = 9 })
    sim.tick(240)
    equals(#marked, 0, "at the menu, the item is not taken as done")
    local before = sim.delivered()
    sim.startRun(false)
    sim.tick(240)
    restore()
    equals(sim.delivered(), before + 1, "the copy comes aboard once the run is back")
    equals(marked[#marked], 9, "and only then is the item marked")
end)

test("a bundle unlocks each of its weapons, puts each aboard, and counts as received once", function()
    sim.startRun(true)
    apShopForgetSeed()
    apFillerResetForTesting()
    _G.apShopConfig.deliver = true
    applySeed({ kinds = { "filler", "shop", "bundle" }, items = {
        ["Weapon Bundle 1"] = { k = "bundle", bps = { "BEAM_2", "LASER_BURST_3" },
                                names = { "Halberd Beam", "Burst Laser Mark III" } } } })
    local marked = {}
    local restore = stub("apNetItemDelivered", function(index) marked[#marked + 1] = index return true end)
    local before = sim.delivered()
    apReceiveItem("Weapon Bundle 1", "Nina", false, 5)
    sim.tick(240)
    restore()
    equals(sim.delivered(), before + 2, "both weapons come aboard")
    equals(_G.apInventory.shopAvailability.BEAM_2, 1, "the first one is now sold in stores")
    equals(_G.apInventory.shopAvailability.LASER_BURST_3, 1, "and so is the second")
    equals(#marked, 1, "the bundle is marked received once")
    equals(marked[1], 5, "with its own number")
end)

test("further copies make the object more common", function()
