    apShopForgetSeed()
    _G.apInventory = { ships = {}, shopAvailability = {} }
    apApplyShopRules()
    equals(sim.rarityFor("BEAM_2", 4).rarity, 4, "the new seed starts from the game's own rarity")
end)

test("applying it twice doesn't drift the rarity", function()
