test("network: a shop scouted before the data packet is asked again, not left empty", function()
    connectWithShop(1)
    sim.netEvent("scout", { name = "Unknown", sender = "Berserker", extra = "Unknown", value = 1 })
    sim.tick(1)
    equals(sim.netCalls("ScoutLocations"), 1, "the first reply cannot be read")
    sim.tick(200)
    equals(sim.netCalls("ScoutLocations"), 2, "so the shop is scouted again a few seconds later")
    sim.netEvent("scout", { name = "Archipelago Shop 1", sender = "Berserker", extra = "Seashell", value = 1 })
    sim.tick(1)
    equals(_G.apShopGifts[1] and _G.apShopGifts[1].location, "shop:1", "and the second reply fills it")
    sim.tick(400)
    equals(sim.netCalls("ScoutLocations"), 2, "nothing more is asked once it worked")
end)

test("network: a shop the module cannot scout yet (first connection to a seed) is asked again", function()
    local refusals = 2
    local scout = sim.net.client.ScoutLocations
    sim.net.client.ScoutLocations = function(self, names)
        if refusals > 0 then
            refusals = refusals - 1
            sim.net.calls[#sim.net.calls + 1] = { "ScoutLocations", count = 0 }
            return false
        end
        return scout(self, names)
    end
    connectWithShop(1)
    equals(sim.netCalls("ScoutLocations"), 1, "the module had no location names, nothing went out")
    sim.tick(200)
    equals(sim.netCalls("ScoutLocations"), 2, "asked again a few seconds later")
    sim.tick(200)
    equals(sim.netCalls("ScoutLocations"), 3, "and again until the module knows the names")
    sim.netEvent("scout", { name = "Archipelago Shop 1", sender = "Berserker", extra = "Seashell", value = 1 })
    sim.tick(1)
    equals(_G.apShopGifts[1] and _G.apShopGifts[1].location, "shop:1", "the shop fills without restarting the game")
    sim.tick(400)
    equals(sim.netCalls("ScoutLocations"), 3, "nothing more is asked once it worked")
end)

test("network: a slow data package never leaves the shop empty for good, and the slot says it waits", function()
    local scout = sim.net.client.ScoutLocations
    local refusing = true
    sim.net.client.ScoutLocations = function(self, names)
        if refusing then
            sim.net.calls[#sim.net.calls + 1] = { "ScoutLocations", count = 0 }
            return false
        end
        return scout(self, names)
    end
    connectWithShop(1)
    sim.tick(200 * 25)
    local asked = sim.netCalls("ScoutLocations")
    check(asked > 20, "past the quick retries (" .. asked .. " asks)")
    check(apShopWaiting(), "the shop is still waiting")
    equals(apShopEmptyReason(), "waiting", "and its slots say so, not that all is sold")
    sim.tick(30 * 60 + 10)
    check(sim.netCalls("ScoutLocations") > asked, "it keeps asking, slowly")
    refusing = false
    sim.tick(30 * 60 + 10)
    sim.netEvent("scout", { name = "Archipelago Shop 1", sender = "Berserker", extra = "Seashell", value = 1 })
    sim.tick(1)
    equals(_G.apShopGifts[1] and _G.apShopGifts[1].location, "shop:1", "and fills once the server knows")
    check(not apShopWaiting(), "then it no longer waits")
    sim.net.client.ScoutLocations = scout
end)

