local function systemNamed(name)
    for i = 0, sim.player.vSystemList:size() - 1 do
        if sim.player.vSystemList[i].name == name then
            return sim.player.vSystemList[i]
        end
    end
    return nil
end

test("cap: a system with no item stays stuck at level 1", function()
    sim.startRun(true)
    _G.apInventory.systemCaps.shields = nil
    local shields = systemNamed("shields")
    shields.powerState.second = 1
    apSystemsForgetStartingPower()

    apApplySystemRules()
    equals(shields.maxLevel, 1, "shields are stuck at level 1")
end)

test("cap: each received item raises the cap by one notch", function()
    sim.startRun(true)
    local shields = systemNamed("shields")
    shields.powerState.second = 1
    apSystemsForgetStartingPower()

    for expected = 1, 4 do
        _G.apInventory.systemCaps.shields = expected
        apApplySystemRules()
        equals(shields.maxLevel, expected, "cap " .. expected)
    end
end)

test("cap: the FIRST item counts, even on a system that starts above 1", function()
    sim.startRun(true)
    apInventoryClear()
    local shields = systemNamed("shields")
    shields.powerState.second = 2
    apSystemsForgetStartingPower()
    apApplySystemRules()
    equals(shields.maxLevel, 2, "with no item, the ship keeps what it had")

    apInventoryAdd({ kind = "cap", sys = "shields", n = 1 })
    apApplySystemRules()
    equals(shields.maxLevel, 3, "the FIRST item gives one MORE notch, not the same one")

    apInventoryAdd({ kind = "cap", sys = "shields", n = 1 })
    apApplySystemRules()
    equals(shields.maxLevel, 4, "and the next one another")
end)

test("cap: a starting bonus opens its own notch, otherwise it's inert", function()
    sim.startRun(true)
    apInventoryClear()
    local engines = systemNamed("engines")
    engines.powerState.second = 2
    apSystemsForgetStartingPower()
    apApplySystemRules()
    equals(engines.maxLevel, 2, "with nothing, the cap equals what the ship had")

    apInventoryAdd({ kind = "start", sys = "engines", n = 1 })
    apApplySystemRules()
    equals(engines.maxLevel, 2, "received during the run, the bonus waits for the next one")
    engines.powerState.second = 2
    sim.startRun(true)
    engines = systemNamed("engines")
    equals(engines.powerState.second, 3, "the next run gets the level")
    equals(engines.maxLevel, 3, "the cap opens by one notch so the bonus fits")
end)

test("a head start received during a run waits for the next run, the cap with it", function()
    _G.apInventory = { ships = {}, systemCaps = { engines = 2 }, startingUpgrades = {}, shopAvailability = {} }
    sim.startRun(true)
    local engines = systemNamed("engines")
    local level = engines.powerState.second
    apApplySystemRules()
    local cap = engines.maxLevel
    apQueueItem({ kind = "start", sys = "engines", n = 1, display = "Engines Head Start" })
    drain()
    apApplySystemRules()
    equals(engines.maxLevel, cap, "no level an event or a store could sell before the run that gets it")
    sim.startRun(false)
    sim.tick(1)
    apApplySystemRules()
    equals(engines.maxLevel, cap, "nor after a Continue")
    sim.startRun(true)
    engines = systemNamed("engines")
    equals(engines.powerState.second, level + 1, "the next run starts with it")
    equals(engines.maxLevel, cap + 1, "and its cap counts it")
end)

test("cap: the game's maximum is never exceeded", function()
    sim.startRun(true)
    local shields = systemNamed("shields")
    shields.powerState.second = 1
    _G.apInventory.systemCaps.shields = 99

    apApplySystemRules()
    check(shields.maxLevel <= 8, "the game's maximum holds (" .. shields.maxLevel .. ")")
end)

test("cap: a starting bonus opens the notches it needs", function()
    sim.startRun(false)
    _G.apInventory.systemCaps.shields = 1
    _G.apInventory.startingUpgrades.shields = 3

    local shields
    for i = 0, sim.player.vSystemList:size() - 1 do
        if sim.player.vSystemList[i].name == "shields" then
            shields = sim.player.vSystemList[i]
        end
    end
    check(shields ~= nil, "the ship has shields")
    shields.powerState.second = 1

    apSystemsForgetStartingPower()
    sim.startRun(true)
    equals(shields.powerState.second, 4,
           "the three granted levels are applied: 1 starting + 3")
end)

test("cap: the same bonus applies as soon as the cap rises", function()
    sim.startRun(false)
    _G.apInventory.systemCaps.shields = 4
    _G.apInventory.startingUpgrades.shields = 2

    local shields
    for i = 0, sim.player.vSystemList:size() - 1 do
        if sim.player.vSystemList[i].name == "shields" then
            shields = sim.player.vSystemList[i]
        end
    end
    shields.powerState.second = 1

    sim.startRun(true)
    check(shields.powerState.second > 1,
          "the bonus is applied (" .. shields.powerState.second .. ")")
    check(shields.powerState.second <= 4, "without exceeding the cap")
end)

test("cap: a cap never drops below the level already reached", function()
    sim.startRun(true)
    local shields
    for i = 0, sim.player.vSystemList:size() - 1 do
        if sim.player.vSystemList[i].name == "shields" then
            shields = sim.player.vSystemList[i]
        end
    end
    shields.powerState.second = 4
    _G.apInventory.systemCaps.shields = 1

    apApplySystemRules()
    check(shields.maxLevel >= 4, "the cap stays at the level reached (" .. shields.maxLevel .. ")")
end)

test("cap: saving and continuing does not raise a system's cap", function()
    _G.apInventory.systemCaps.shields = 2
    _G.apInventory.startingUpgrades = {}
    sim.startRun(true)
    local shields
    for i = 0, sim.player.vSystemList:size() - 1 do
        if sim.player.vSystemList[i].name == "shields" then shields = sim.player.vSystemList[i] end
    end
    apApplySystemRules()
    local cap = shields.maxLevel
    check(cap < 8, "the cap is below the game's maximum, or the test proves nothing (" .. cap .. ")")
    shields.powerState.second = cap
    for _ = 1, 3 do
        sim.startRun(false)
        sim.tick(60)
        equals(shields.maxLevel, cap, "the cap has not moved after a reload")
        shields.powerState.second = shields.maxLevel
    end
end)

test("the overview tiles show their whole number, even a long one", function()
    local ships = {}
    for _, ship in ipairs(apGameData.ships) do
        ships[#ships + 1] = ship.name
    end
    _G.apInventory = { ships = ships, systemCaps = {}, startingUpgrades = {}, shopAvailability = {} }
    sim.startRun(true)
    sim.keyDown(Defines.SDL.KEY_TAB)
    apDashboardPage("overview")
    -- Closer to FTL's big digits than the harness default.
    local measure = Graphics.freetype.easy_measureWidth
    Graphics.freetype.easy_measureWidth = function(size, text) return #tostring(text) * size * 0.8 end
    sim.renderGui()
    Graphics.freetype.easy_measureWidth = measure
    local fraction = apT("dash.fraction", { done = #ships, total = 28 })
    local whole = false
    for _, line in ipairs(sim.drawn) do
        if line == fraction then whole = true end
    end
    check(whole, "the layouts tile reads " .. fraction .. " in full, not cut with an ellipsis")
    sim.keyDown(Defines.SDL.KEY_TAB)
end)

test("the panel shows what the player has earned", function()
    _G.apInventory = {
        ships = { "PLAYER_SHIP_ROCK", "PLAYER_SHIP_MANTIS" },
        systemCaps = { shields = 3, cloaking = 1 },
        startingUpgrades = { shields = 2, reactor = 4 },
