    check(not apCheckAlreadySent("ach:ACH_TOUGH_SHIP"), "the achievement stays due")
    check(not apCheckAlreadySent("PLAYER_SHIP_HARD:fight:1"), "and so do the fights")
    sim.starMap.worldLevel = 0
