test("at a store, a weapon that would go to cargo waits for the jump, so the freed slot is kept for buying", function()
    sim.startRun(true)
    sim.slots.weapon = 1
    sim.equipped.weapon = { "BEAM_2" }
    sim.cargoCap = 4
    sim.cargo = { "BEAM_2", "BEAM_2", "BEAM_2" }
    sim.setStore(true)
    sim.clearLog()
    apQueueItem({ kind = "weapon", bp = "LASER_BURST_3", display = "Burst Laser Mark III" })
    sim.tick(240)
    equals(#sim.cargo, 3, "the free cargo slot stays free at the store")
    equals(#_G.apFillerPendingForTesting(), 1, "the weapon waits")
    check(not shownKey("item.waiting_cargo"), "and the player is not told the cargo hold is full: it is not")
    sim.equipped.weapon = {}
    sim.jumpArrive()
    sim.tick(240)
    equals(#sim.equipped.weapon, 1, "arriving at another store, a free weapon slot still takes it")
    apQueueItem({ kind = "weapon", bp = "BEAM_2", display = "Halberd Beam" })
    sim.jumpArrive()
    sim.tick(240)
    equals(#_G.apFillerPendingForTesting(), 1, "the next one waits again for want of a slot")
    sim.setStore(false)
    sim.jumpArrive()
    sim.tick(240)
    equals(#sim.cargo, 4, "after the jump, away from the store, it goes to cargo")
    equals(#_G.apFillerPendingForTesting(), 0, "nothing left waiting")
    sim.cargo = {}
    sim.cargoCap = 999
end)

test("an Archipelago beacon counts as a store too, though its store comes from a sub-event", function()
    sim.startRun(true)
    sim.slots.weapon = 0
    sim.cargoCap = 4
    sim.cargo = { "BEAM_2", "BEAM_2", "BEAM_2" }
    sim.starMap.currentLoc = sim.makeLocation()
    sim.starMap.currentLoc.event = { store = false, eventName = "AP_STORE_EVENT" }
    check(apAtAStore(), "the beacon is seen as a store")
    apQueueItem({ kind = "weapon", bp = "LASER_BURST_3", display = "Burst Laser Mark III" })
    sim.tick(240)
    equals(#sim.cargo, 3, "the free cargo slot stays free for buying a package")
    sim.starMap.currentLoc.event = { store = false, eventName = "HOSTILE_REBEL" }
    check(not apAtAStore(), "an ordinary beacon is not")
    sim.cargo = {}
    sim.cargoCap = 999
end)

test("at a store, the cargo hold still fills up, all but its last slot", function()
    sim.startRun(true)
    sim.slots.weapon = 0
    sim.cargoCap = 4
    sim.cargo = { "BEAM_2" }
    sim.setStore(true)
    for _ = 1, 3 do apQueueItem({ kind = "weapon", bp = "LASER_BURST_3", display = "Burst Laser Mark III" }) end
    sim.tick(240)
    equals(#sim.cargo, 3, "two arrive in cargo, the last slot stays free")
    equals(#_G.apFillerPendingForTesting(), 1, "only the third waits")
