    equals(apDeathLinkToggle(), false, "refused")
    equals(_G.apDeathLink.enabled, true, "still on")
    apDeathLinkConfigure({ toggle = true })
end)

local trapLog = {}

local function trapStubs()
    trapLog = {}
    local aimed = stub("apNetSendTrapTo", function(slot, name)
        trapLog[#trapLog + 1] = { "SendTrapTo", slot = slot, name = name }
        return true
    end)
    local whole = stub("apNetSendTrap", function(name)
        trapLog[#trapLog + 1] = { "SendTrap", name = name }
        return true
    end)
    return function() aimed() whole() end
end

test("a pact lands on one FTL player, never on the whole link", function()
    _G.apTrapLink.enabled = true
    apTrapLinkForgetPartner()
    apTrapLinkPartner("Nina", true, 2)
    apTrapLinkPartner("Bers", true, 3)
    local restore = trapStubs()
    check(apTrapLinkSendToOne("Archipelago Deal"), "sent")
    restore()
    local calls = trapLog
    equals(#calls, 1, "one trap")
    equals(calls[1][1], "SendTrapTo", "aimed")
    check(calls[1].slot == 2 or calls[1].slot == 3, "at a partner")
    _G.apTrapLink.enabled = false
    apTrapLinkForgetPartner()
end)

test("a pact goes through the link when only other games were seen on it", function()
    _G.apTrapLink.enabled = true
    apTrapLinkForgetPartner()
    apTrapLinkReceive("Other game", "Ice Trap")
    local restore = trapStubs()
    check(apTrapLinkSendToOne("Archipelago Deal"), "sent")
    restore()
    local calls = trapLog
    equals(#calls, 1, "one trap")
    equals(calls[1][1], "SendTrap", "through the link")
    _G.apTrapLink.enabled = false
    apTrapLinkForgetPartner()
end)

test("a partner not heard for ten minutes is not aimed at any more", function()
    _G.apTrapLink.enabled = true
    apTrapLinkForgetPartner()
    apTrapLinkPartner("Nina", true, 2)
    apTrapLinkAgePartner(601)
    local restore = trapStubs()
    equals(apTrapLinkSendToOne("Archipelago Deal"), false, "no one left: the pact comes back")
    restore()
    equals(#trapLog, 0, "nothing sent")
    _G.apTrapLink.enabled = false
    apTrapLinkForgetPartner()
end)

test("a race a mod calls differently is recruited under the game's own name", function()
    sim.startRun(true)
    _G.apRaceNames = { anaerobic = "lanius" }
    local before = sim.player.vCrewList:size()
    check(apRecruitCrew("anaerobic"), "recruited")
    equals(sim.player.vCrewList[before].species, "lanius", "the game's own race")
    _G.apRaceNames = nil
end)

test("locked shops: a new sector's reset does not bring back what the seed locked", function()
    sim.weaponBlueprints.LOCK_TEST = 3
    sim.resetBlueprints()
    sim.net.shopLocks = {}
    _G.apInventory = { ships = {}, shopAvailability = {} }
    apShopForgetSeed()
    apShopConfigure({ mode = "locked", deliver = false, baseline = { "LOCK_TEST" } })
    sim.startRun(true)
    local desc = sim.rarityFor("LOCK_TEST", 3)
    equals(sim.net.shopLocks.LOCK_TEST, true, "the stores leave it out")
    equals(desc.rarity, 3, "never a rarity of 0: a whole family at 0 crashes the game")
    equals(desc.baseRarity, 3, "in both fields")
    sim.newSectorRarities()
    equals(sim.net.shopLocks.LOCK_TEST, true, "a new map changes nothing to the lock")
    apApplyShopItem({ bp = "LOCK_TEST", n = 1, noDelivery = true })
    equals(sim.net.shopLocks.LOCK_TEST, nil, "received: on sale")
    check(desc.rarity > 0, "and in the random picks")
    sim.newSectorRarities()
    equals(desc.rarity, 3, "a received item survives the reset")
    sim.newSectorRarities({ LOCK_TEST = 0 })
    sim.tick(1)
    equals(desc.rarity, 3, "and the sector's own list, from the next tick")
    apShopForgetSeed()
    equals(desc.rarity, 3, "a new seed gets the game's rarity back")
    equals(desc.baseRarity, 3, "in both fields")
    _G.apShopConfig.mode = "rarity_boost"
    _G.apShopConfig.baseline = {}
end)

test("a system without its blueprint stays off the store shelves until it comes in", function()
    sim.resetBlueprints()
    sim.net.shopLocks = {}
    local unlocked, loaded = _G.apSystemUnlocked, _G.apSeedLoaded
    local owned = {}
    _G.apSystemUnlocked = function(name) return owned[name] == true end
    _G.apSeedLoaded = function() return true end
    _G.apInventory = { ships = {}, shopAvailability = {} }
    apApplyShopRules()
    equals(sim.net.shopLocks.cloaking, true, "locked")
    owned.cloaking = true
    sim.tick(60)
    equals(sim.net.shopLocks.cloaking, nil, "the blueprint opens it within a second")
    _G.apSystemUnlocked, _G.apSeedLoaded = unlocked, loaded
    apShopForgetSeed()
end)

test("New Crew Member with the crew full: the player is told once and the dashboard counts it", function()
    sim.startRun(true)
    apNotifyResetForTesting()
    local full = sim.player.IsCrewFull
    sim.player.IsCrewFull = function() return true end
    apQueueItem({ kind = "filler", res = "crew", n = 1 })
    sim.jumpArrive()
    sim.tick(2)
    local function told()
        local count = 0
        for _, toast in ipairs(apToastsForTesting()) do
            if toast.text == apT("crew.waiting.new") then count = count + 1 end
        end
        return count
    end
    equals(told(), 1, "the player is told")
    apNotifyResetForTesting()
    sim.jumpArrive()
    sim.tick(2)
    equals(apOwedCrewCount(), 1, "it waits in the count")
    equals(told(), 0, "and it is not said again once the message has gone")
    sim.player.IsCrewFull = full
    sim.jumpArrive()
    sim.tick(2)
    equals(apOwedCrewCount(), 0, "and it boards once there is room")
end)

end

do
local DASH = { x = 140, y = 56, w = 1000, h = 608 }
local DASH_PAGES = { "overview", "ships", "systems", "checks", "journal" }

local function dashboardSeed()
    applySeed({
        goal = { kind = "victories", count = 3 },
        items = {},
        loc = {
            ["shop:1"] = "Archipelago Shop 1", ["shop:2"] = "Archipelago Shop 2",
            ["PLAYER_SHIP_HARD:sector:2"] = "Kestrel Cruiser A: Reach sector 2",
            ["PLAYER_SHIP_HARD:victory"] = "Kestrel Cruiser A: Defeat the Flagship",
            ["sys:shields"] = "Install Shields", ["crew:engi"] = "First Engi aboard",
        },
        links = { death = { enabled = true, trigger = "both", effect = "fire" },
                  energy = { enabled = false }, trap = { enabled = true } },
    })
end

local function openDashboard(page)
    if not apDashboardOpen() then apToggleHud() end
    apDashboardPage(page)
    sim.renderGui()
end

local function closeDashboard()
    if apDashboardOpen() then apToggleHud() end
end

local function overflowing()
    local out = {}
    for _, draw in ipairs(sim.draws) do
        local right = draw.x + (draw.maxWidth or 0)
        if draw.x < DASH.x or right > DASH.x + DASH.w or draw.y < DASH.y or draw.y > DASH.y + DASH.h then
            out[#out + 1] = draw.text
        end
    end
    return out
end

test("dashboard: every page stays inside the window, in every language", function()
    sim.startRun(true)
    dashboardSeed()
    _G.apInventory.ships = { "PLAYER_SHIP_HARD", "PLAYER_SHIP_HARD_2" }
    apRecordReceived("A very long item name that would not fit anywhere at all", "SomeoneWithALongName")
    for _, code in ipairs({ "en", "fr", "de", "es", "it", "pt" }) do
        apLangSet(code, "test")
        for _, page in ipairs(DASH_PAGES) do
            openDashboard(page)
            check(sim.errors == 0, code .. "/" .. page .. ": drawn without error")
            local out = overflowing()
            equals(#out, 0, code .. "/" .. page .. ": no text leaves the window (" .. tostring(out[1]) .. ")")
            check(#sim.draws > 5, code .. "/" .. page .. ": the page draws something")
        end
    end
    apLangSet("en", "test")
    closeDashboard()
end)

test("dashboard: TAB opens it in a run, pauses the game, and TAB closes it", function()
    sim.startRun(true)
    local gui = Hyperspace.App.gui
    gui.bPaused = false
    sim.keyDown(Defines.SDL.KEY_TAB)
    check(apDashboardOpen(), "TAB opens the dashboard")
    equals(gui.bPaused, true, "the game is paused behind it")
    sim.keyDown(Defines.SDL.KEY_TAB)
    check(not apDashboardOpen(), "TAB closes it")
    equals(gui.bPaused, false, "and the game resumes as it was")
end)

test("dashboard: a game already paused stays paused when it closes", function()
    sim.startRun(true)
    local gui = Hyperspace.App.gui
    gui.bPaused = true
    apToggleHud()
    apToggleHud()
    equals(gui.bPaused, true, "the player's own pause is kept")
end)

test("dashboard: arrows, digits and clicks on tabs change page; Esc and a click outside close", function()
    sim.startRun(true)
    dashboardSeed()
    openDashboard("overview")
    sim.keyDown(Defines.SDL.KEY_RIGHT)
    sim.renderGui()
    check(sim.drawnText(apT("dash.ships.header", { done = 0, total = 28 }):sub(1, 10)), "right arrow: ships page")
    sim.keyDown(Defines.SDL.KEY_LEFT)
    sim.keyDown(Defines.SDL.KEY_LEFT)
    sim.renderGui()
    check(sim.drawnText(apT("dash.journal.items")), "left arrow wraps around to the journal")
    sim.keyDown(Defines.SDL.KEY_4)
    sim.renderGui()
    check(sim.drawnText(apT("dash.cat.shop")), "4 opens the checks page")

    local tabW = math.floor((DASH.w - 32 - 6 * 4) / 5)
    sim.click(DASH.x + 16 + (tabW + 6) * 2 + 10, DASH.y + 60)
    sim.renderGui()
    check(sim.drawnText(apT("dash.system.locked")), "a click on the third tab opens the systems page")

    sim.keyDown(Defines.SDL.KEY_ESCAPE)
    check(not apDashboardOpen(), "Esc closes it")
    openDashboard("overview")
    sim.click(20, 20)
    check(not apDashboardOpen(), "a click outside closes it")
end)

test("dashboard: the overview gathers the goal, the checks, the links and the latest items", function()
    sim.startRun(true)
    apVictoriesResetForTesting()
    dashboardSeed()
    apSendCheck("shop:1", "test")
    apRecordReceived("Burst Laser II", "Axel")
    openDashboard("overview")
