                          passes = { PLAYER_SHIP_ROCK = "Sector Pass (Rock)", PLAYER_SHIP_STEALTH = "Sector Pass (Stealth)" },
                          checks = { ["shop:14"] = { ways = { { l = "PLAYER_SHIP_ROCK", i = {} },
                                                              { l = "PLAYER_SHIP_STEALTH", i = {} } }, bp = 0, pass = 1 } },
                          blueprint_items = {} } })
    apReceiveItem("Rock Cruiser Key", "Nina", false, 0)
