test("event: the relay with no package returns the scrap it took", function()
    sim.startRun(true)
    apShopGiftsConfigure({})
    sim.player.currentScrap = 40
    sim.openChoiceBox("AP_EVT_PACKAGE")
    sim.player.currentScrap = 25
