local function fightSeed(percent)
    _G.apInventory = { ships = {}, systemCaps = {}, startingUpgrades = {}, shopAvailability = {} }
    apContractResetForTesting()
    apForgetChecksForTesting()
    applySeed({ loc = { ["PLAYER_SHIP_HARD:fight:1"] = "Kestrel Cruiser: Fight 1 won",
                        ["PLAYER_SHIP_HARD:fight:2"] = "Kestrel Cruiser: Fight 2 won" },
                options = { combat_check_scrap = percent } })
    sim.startRun(true)
    sim.jumpArrive()
end

local function winFight(scrap)
    sim.enemy = sim.makeShip(1)
    sim.enemy:DamageHull(100)
    local event = { stuff = { scrap = scrap, fuel = 2, missiles = 1 } }
    fire("PRE_CREATE_CHOICEBOX", event)
    return event
end

test("combat checks: the first fights won in a run send their checks, with less scrap", function()
    fightSeed(50)
    local event = winFight(30)
    check(apCheckAlreadySent("PLAYER_SHIP_HARD:fight:1"), "fight 1 won sends its check")
    equals(event.stuff.scrap, 15, "half the scrap is kept")
    equals(event.stuff.fuel, 2, "fuel and missiles stay")
    winFight(30)
    check(not apCheckAlreadySent("PLAYER_SHIP_HARD:fight:2"), "a second box at the same beacon is the same fight")
    sim.jumpArrive()
    winFight(30)
    check(apCheckAlreadySent("PLAYER_SHIP_HARD:fight:2"), "the next beacon's fight is fight 2")
    sim.jumpArrive()
    local third = winFight(30)
    equals(third.stuff.scrap, 30, "a fight beyond the seed's checks keeps its full scrap")
    sim.enemy = nil
end)

test("combat checks: fights won before a crash, never received by the server, go out once connected", function()
    fightSeed(50)
    sim.runVariables.ap_fights_won = 2
    local sentNames = {}
    local restoreSend = stub("apNetSendCheck", function(name) sentNames[#sentNames + 1] = name return true end)
    local restoreNet = stub("apNetConnected", function() return false end)
    sim.jumpArrive()
    equals(#sentNames, 0, "offline: nothing to send yet")
    restoreNet()
    restoreNet = stub("apNetConnected", function() return true end)
    sim.jumpArrive()
    equals(#sentNames, 2, "both fights the save counted go out")
    sim.jumpArrive()
    restoreNet()
    restoreSend()
    equals(#sentNames, 2, "and only once")
end)

test("combat checks: after a crash, a continued run sends its missing fights without waiting for a jump", function()
    fightSeed(50)
    local sentNames = {}
    local restoreSend = stub("apNetSendCheck", function(name) sentNames[#sentNames + 1] = name return true end)
    local restoreNet = stub("apNetConnected", function() return true end)
    apForgetChecksForTesting()
    sim.startRun(false)
    sim.runVariables.ap_fights_won = 2
    sim.tick(90)
    restoreNet()
    restoreSend()
    equals(#sentNames, 2, "both fights go out a moment after Continue")
end)

