    shipDone()
end)

test("ships: a refused run stays refused once the key comes in, and after a restart", function()
    shipConnect({ "Kestrel Cruiser Key", "Rock Cruiser Key" })
    startRunWith("PLAYER_SHIP_CIRCLE")
    reachSector(2)
