test("kestrel key: the hangar opens on the starting ship, RANDOM SHIP draws among the ships received", function()
    shipConnect({ "Rock Cruiser Key", "Engi Cruiser Key" },
        { kestrel_locked = true, start_ship = "PLAYER_SHIP_ROCK" })
    sim.shipList.open = false
    sim.hangarOpen = false
    sim.renderMenu()
    sim.hangarOpen = true
    sim.hangarShip = "PLAYER_SHIP_HARD"
    sim.renderMenu()
    equals(sim.hangarShip, "PLAYER_SHIP_ROCK", "not on the Kestrel without its key")
    sim.hangarShip = "PLAYER_SHIP_HARD"
    sim.renderMenu()
    equals(sim.hangarShip, "PLAYER_SHIP_HARD", "only when the hangar opens: the player may still look at it")

    -- Back from a run: the menu is not drawn during the run, and the hangar shows its ship a few frames late.
    sim.hangarOpen = false
    sim.renderGui()
    sim.hangarOpen = true
    sim.hangarShip = ""
    sim.renderMenu()
    sim.renderMenu()
    sim.hangarShip = "PLAYER_SHIP_HARD"
    sim.renderMenu()
    equals(sim.hangarShip, "PLAYER_SHIP_ROCK", "back from a run, on the starting ship too")

    local seen = {}
    for _ = 1, 30 do
        sim.click(95, 194)
        seen[sim.hangarShip] = true
    end
    check(seen.PLAYER_SHIP_ROCK and seen.PLAYER_SHIP_CIRCLE, "both ships received come up")
    check(not seen.PLAYER_SHIP_HARD, "never the Kestrel without its key")

    -- The arrows step through the base ships that can be shown: Kestrel (NO KEY), Engi, Rock, in list order.
    sim.hangarShip = "PLAYER_SHIP_ROCK"
    sim.click(144, 158)
    equals(sim.hangarShip, "PLAYER_SHIP_HARD", "> from the Rock wraps to the Kestrel, marked NO KEY")
    sim.click(144, 158)
    equals(sim.hangarShip, "PLAYER_SHIP_CIRCLE", "> then the Engi")
    sim.click(50, 158)
    equals(sim.hangarShip, "PLAYER_SHIP_HARD", "< back to the Kestrel")
    sim.click(50, 158)
    equals(sim.hangarShip, "PLAYER_SHIP_ROCK", "< wraps to the Rock")

    sim.hangarShip = "PLAYER_SHIP_HARD"
    sim.click(1150, 40)
    sim.renderMenu()
    local words = {}
    for word in apT("hangar.kestrel_locked"):gmatch("%S+") do words[#words + 1] = word end
    check(sim.drawnText(words[#words]), "the refusal is drawn whole, down to its last word")
    sim.hangarOpen = false
    sim.hangarShip = nil
    shipDone()
end)

test("in logic: after a reconnection, the items received before still count", function()
    local logic = { layouts = { PLAYER_SHIP_ROCK = { "Rock Cruiser Key" } },
                    checks = { ["PLAYER_SHIP_ROCK:sector:3"] = { ways = { { l = "PLAYER_SHIP_ROCK", i = {} } }, bp = 0, pass = 0 } },
                    blueprint_items = {} }
    shipConnect({ "Rock Cruiser Key" }, { logic = logic })
    equals(apInLogic("PLAYER_SHIP_ROCK:sector:3"), true, "the Rock received: in logic")
    sim.netEvent("disconnected", {})
    sim.net.connected = false
    sim.tick(60 * 6)
    sim.netEvent("connected", { name = "Navigator", extra = shipSeed({ logic = logic }) })
    sim.netEvent("item", { name = "Rock Cruiser Key", sender = "Nina", index = 0 })
    sim.net.connected = true
    sim.tick(1)
    equals(apInLogic("PLAYER_SHIP_ROCK:sector:3"), true, "the server's replay of the Rock still counts once reconnected")
    shipDone()
end)

end

do
test("toasts: an item, a check and a trap each get their own colour, then fade away", function()
    sim.startRun(true)
    apNotifyResetForTesting()
    apNotifyItem("Burst Laser II", "Axel")
    apNotifyCheck("Archipelago Shop 3")
    apNotifyFlushForTesting()
    apNotifyTrap("a fire")
    local toasts = apToastsForTesting()
    equals(#toasts, 3, "three toasts")
    equals(toasts[1].tone, "good", "the item is green")
    equals(toasts[2].tone, "border", "the check is violet")
    equals(toasts[3].tone, "bad", "the trap is red")
    sim.renderGui()
    check(sim.drawnText("Burst Laser II"), "they are drawn")
    for _ = 1, 400 do sim.renderGui() end
    equals(#apToastsForTesting(), 0, "and gone a few seconds later")
end)

test("toasts: they last in seconds, not frames, so a fast screen does not cut them short", function()
    sim.startRun(true)
    apNotifyResetForTesting()
    local saved = Hyperspace.FPS
    -- 144 frames a second: SpeedFactor counts sixteenths of a second.
    Hyperspace.FPS = { SpeedFactor = 16 / 144 }
    apNotifyStatus("short")
    for _ = 1, 144 * 5 do sim.renderGui() end
    equals(#apToastsForTesting(), 1, "still there after five seconds at 144 Hz")
    for _ = 1, 144 * 2 do sim.renderGui() end
    equals(#apToastsForTesting(), 0, "gone after its six seconds")
    Hyperspace.FPS = saved
end)

test("toasts: a long message stays long enough to read, and a run that does not count is not pushed out", function()
    sim.startRun(true)
    apNotifyResetForTesting()
    local long = string.rep("word ", 30)
    apNotifyStatus(long)
    for _ = 1, 60 * 7 do sim.renderGui() end
    check(sim.drawnText(long), "150 characters are still shown after seven seconds")

    apNotifyResetForTesting()
    apNotifyWarning("this run does not count")
    for index = 1, 6 do apNotifyStatus("message " .. index) end
    local kept = false
    for _, toast in ipairs(apToastsForTesting()) do
        if toast.text == "this run does not count" then kept = toast.tone == "warn" end
    end
    check(kept, "the warning stays, in its warning colour, when a burst of messages follows")
end)

test("toasts: never more than four, and none over the dashboard", function()
    sim.startRun(true)
    apNotifyResetForTesting()
    for index = 1, 6 do apNotifyStatus("message " .. index) end
    equals(#apToastsForTesting(), 4, "the oldest ones make room")
    apToggleHud()
    sim.renderGui()
    check(not sim.drawnText("message 6"), "hidden while the dashboard is open")
    apToggleHud()
    sim.renderGui()
    check(sim.drawnText("message 6"), "back once it closes")
end)

