    apConnectResetForTesting()
    sim.startRun(false)
    sim.started = false
    applySeed({ loc = { ["shop:1"] = "Archipelago Shop 1" } })
    sim.renderMenu()
    check(sim.drawnText(apT("dash.status.offline")), "it says the seed is kept offline")
