test("hangar: the ship list marks the layouts the seed leaves out", function()
    apConnectResetForTesting()
    sim.startRun(false)
    sim.started = false
    applySeed({ layouts = { "PLAYER_SHIP_HARD", "PLAYER_SHIP_ROCK", "PLAYER_SHIP_MANTIS_2" } })
    local label = apT("hangar.out_of_seed")
    local function marked(left, top)
        for _, draw in ipairs(sim.draws) do
            if draw.text == label and draw.x >= left and draw.x < left + 205 and draw.y >= top and draw.y < top + 177 then
                return true
            end
        end
        return false
    end
    local function count()
        local n = 0
        for _, draw in ipairs(sim.draws) do
            if draw.text == label then n = n + 1 end
        end
        return n
    end

    sim.renderMenu()
    equals(count(), 0, "nothing while the list is closed")

    sim.shipList = { open = true, page = 0, variant = 0 }
    sim.renderMenu()
    equals(count(), 8, "type A: every ship but the Kestrel and the Rock")
    check(not marked(136, 161), "the Kestrel, top left, is in the seed")
    check(not marked(341, 338), "so is the Rock, third from the right at the bottom")
    check(marked(751, 338), "the Mantis A, bottom right, is not")
    check(marked(956, 161), "nor the Lanius, top of the right column")

    sim.shipList.variant = 1
    sim.renderMenu()
    check(not marked(751, 338), "type B: the Mantis B is in the seed")
    check(marked(136, 161), "the Kestrel B is not")
    equals(count(), 9, "nine layouts B out of ten")

    sim.shipList.variant = 2
    sim.renderMenu()
    equals(count(), 8, "type C: the Lanius and the Crystal have none, nothing to mark")

    sim.shipList = { open = true, page = 1, variant = 0 }
    sim.renderMenu()
    equals(count(), 0, "the pages of modded ships are left alone")

    sim.shipList = { open = false, page = 0, variant = 0 }
    sim.openedList = 0
    sim.renderMenu()
    sim.shipList = { open = true, page = 0, variant = 0 }
    sim.openedList = 2
    sim.renderMenu()
    equals(count(), 3, "first opening: the marks outside FTL's help, in the left and right columns")
    check(not marked(751, 338), "none over the help itself")
    check(marked(956, 161), "the right column keeps its marks")
    sim.shipList.open = false
    sim.renderMenu()
    sim.shipList.open = true
    sim.renderMenu()
    equals(count(), 8, "opened again, the marks are back")
    sim.openedList = nil

    sim.shipList = { open = true, page = 0, variant = 0 }
    applySeed({})
    sim.renderMenu()
    equals(count(), 0, "an older seed without its layouts marks nothing")
    sim.shipList = { open = false, page = 0, variant = 0 }
end)

local function ctrlKey(key)
    sim.keyDown(Defines.SDL.KEY_LCTRL)
    sim.keyDown(key)
    sim.keyUp(Defines.SDL.KEY_LCTRL)
end

local function ctrlV()
    ctrlKey(Defines.SDL.KEY_v)
end

test("connection panel: Ctrl+V pastes, and an address with its port fills both fields", function()
    apConnectResetForTesting()
    apNetResetForTesting()
    sim.renderMenu()
    sim.clipboard = "Tester Two"
    ctrlV()
    equals(apConnectState().slot, "Tester Two", "the slot field takes the clipboard")
    sim.keyDown(Defines.SDL.KEY_UP)
    sim.keyDown(Defines.SDL.KEY_UP)
    sim.clipboard = "/connect archipelago.gg:54321"
    ctrlV()
    equals(apConnectState().uri, "archipelago.gg", "the room page's /connect line gives the address")
    equals(apConnectState().port, "54321", "and its port")
    sim.keyDown(Defines.SDL.KEY_DOWN)
    sim.clipboard = "port 38 281"
    ctrlKey(Defines.SDL.KEY_a)
    ctrlV()
    equals(apConnectState().port, "38281", "Ctrl+A then Ctrl+V replaces the field, the port keeps only digits")
    sim.clipboard = ""
    ctrlV()
    equals(apConnectState().message, apT("connect.paste_empty"), "an empty clipboard says so")
    equals(apConnectState().port, "38281", "and changes nothing")
    sim.platform = "linux"
    ctrlV()
    equals(apConnectState().message, apT("connect.paste_empty.linux"), "only Linux hears about the clipboard tools")
    sim.platform = nil
    sim.keyDown(Defines.SDL.KEY_UP)
    sim.clipboard = "/connect archipelago.gg:51234 and the rest of the room message"
    ctrlV()
    equals(apConnectState().message, nil, "a paste that works clears the empty-clipboard message")
    equals(apConnectState().uri, "archipelago.gg", "text after host:port stays out of the address")
    equals(apConnectState().port, "51234", "and the port is still read")
    sim.clipboard = "wss://archipelago.gg:38281/some/path"
    ctrlV()
    equals(apConnectState().uri, "archipelago.gg", "a wss:// address with a path gives the host")
    equals(apConnectState().port, "38281", "and its port")
    sim.keyDown(Defines.SDL.KEY_DOWN)
    sim.keyDown(Defines.SDL.KEY_v)
    equals(apConnectState().port, "38281", "v alone is still a letter, not a paste (and the port refuses it)")
    sim.clipboard = nil
end)

test("connection panel: paste at the cursor, arrows, Ctrl+A and a held Backspace", function()
    apConnectResetForTesting()
    apNetResetForTesting()
    sim.renderMenu()
    for _, letter in ipairs({ "t", "e", "r" }) do sim.keyDown(Defines.SDL["KEY_" .. letter]) end
    sim.keyDown(Defines.SDL.KEY_LEFT)
    sim.keyDown(Defines.SDL.KEY_LEFT)
    sim.clipboard = "est"
    ctrlV()
    equals(apConnectState().slot, "tester", "pasted at the cursor, not in place of the field")
    sim.keyDown(Defines.SDL.KEY_HOME)
    sim.keyDown(Defines.SDL.KEY_DELETE)
    equals(apConnectState().slot, "ester", "Delete removes the character after the cursor")
    sim.keyDown(Defines.SDL.KEY_END)
    sim.keyDown(Defines.SDL.KEY_BACKSPACE)
    equals(apConnectState().slot, "este", "Backspace removes the one before")
    for _ = 1, 40 do sim.renderMenu() end
    equals(apConnectState().slot, "", "held down, it keeps going")
    sim.keyUp(Defines.SDL.KEY_BACKSPACE)
    sim.clipboard = "Navigator"
    ctrlV()
    ctrlKey(Defines.SDL.KEY_a)
    sim.keyDown(Defines.SDL.KEY_BACKSPACE)
    sim.keyUp(Defines.SDL.KEY_BACKSPACE)
    equals(apConnectState().slot, "", "Ctrl+A then Backspace empties the field")
    sim.clipboard = "Navigator"
    ctrlV()
    ctrlKey(Defines.SDL.KEY_a)
    sim.keyDown(Defines.SDL.KEY_x)
    equals(apConnectState().slot, "x", "Ctrl+A then a letter replaces it")
    sim.clipboard = nil
end)

local function labelColor(key)
    for _, draw in ipairs(sim.draws) do
        if draw.text == apT(key) then return draw.color end
    end
end

local function isTone(color, tone)
    local c = apUi.COLOR[tone]
    return color ~= nil and color.r == c[1] and color.g == c[2] and color.b == c[3]
end

test("connection panel: the field a refusal blames turns red until it is edited, and the button waits", function()
    apConnectResetForTesting()
    apNetResetForTesting()
    sim.renderMenu()
    sim.type("Nobody")
    apConnectNow()
    sim.renderMenu()
    check(sim.drawnText(apT("connect.button.busy")), "while connecting, the button says so")
    sim.netEvent("refused", { extra = "InvalidSlot" })
    sim.tick(2)
    sim.renderMenu()
    check(isTone(labelColor("connect.field.slot"), "bad"), "the slot name is drawn in red")
    check(not isTone(labelColor("connect.field.password"), "bad"), "not the password")
    check(sim.drawnText(apT("connect.button")), "the button is back")
    sim.type("x")
    sim.renderMenu()
    check(not isTone(labelColor("connect.field.slot"), "bad"), "typing in it clears the red")
    apNetResetForTesting()
end)

test("a label too long for one line goes on two instead of being cut", function()
    local ui = _G.apUi
    sim.draws = {}
    ui.textTwoLines(10, 0, 20, ui.width(10, "Rocky, repair") + 2, 14, "text", "Rocky, repair expert")
    local drawn = {}
    for _, draw in ipairs(sim.draws) do if draw.text then drawn[#drawn + 1] = draw.text end end
    equals(table.concat(drawn, "|"), "Rocky, repair|expert", "split at a space, nothing cut")
    sim.draws = {}
    ui.textTwoLines(10, 0, 20, 400, 14, "text", "Rocky")
    equals(#sim.draws, 1, "a label that fits stays on one line")
end)

end

